WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[66263] = { title = "A Precision Approach", description = "Gnolls are awful creatures. Smelly. Always scratching, laughing at you. And there are multitudes here and more are constantly arriving. We, and by that I mean you, could reap them like wheat for days and never get anywhere. They can't be suffered to stay here.\n\nWe must strike at the heart of the snake! Remove their leadership and they'll be paralyzed with indecision and despair. \n\nWhat do you mean why are we doing this? Isn't it obvious? They're gnolls! What more reason could one need?", objectives = "Kill Flayfist.", progress = "Did I mention I'm allergic to gnoll fur? My throat gets itchy just thinking about them.", completion = "How they must despair!" }
WordHunterWoW_QuestEN[66264] = { title = "Disarmed and Docile", description = "There's a frankly unnerving amount of weaponry being waved about up there. Relieving them of some should help calm things down. Or at least calm my nerves.\n\nWhat are they going to do without weapons, after all? Attack you with their bare hands? Ha!", objectives = "Acquire 15 Gnawbone Armaments.", progress = "Surely they're just lying about?", completion = "Oh, those? Just dump them anywhere. I'm sure the elementals won't mind." }
WordHunterWoW_QuestEN[66265] = { title = "Who's Next?", description = "Aha! Well, it seems that another gnoll has stepped up to assume command. Just as I expected. Yes.\n\nHaving a trusted vice-warlord to ensure continuation of government makes perfect sense now, doesn't it? We'll just have to hit them a little harder to tumble their bureaucracy, hm?\n\nWhat? Am I going to take this moment to reflect on whether I'm rushing to judgement on these gnolls? Ridiculous! They're gnolls! \n\nQuickly now! Kill Cracktooth before the iron cools off or they arrange for an election!", objectives = "Kill Cracktooth.", completion = "Ha! Maybe next time they'll think twice before electing a new leader!" }
WordHunterWoW_QuestEN[66266] = { title = "Filthy Mongrels", description = "Those flea-bitten Hyena Mongrels the gnolls breed have got to go! Not only do they have no manners at all--you would not believe the places I've seen them relieve themselves--but they may very well be able to sniff me out despite my exemplary illusions.\n\nDo the well-mannered world a favor and remove them from it.", objectives = "Slay 3 Hyena Matriarchs and 12 Hyena Mongrels.", completion = "Play dead, indeed!" }
WordHunterWoW_QuestEN[66267] = { title = "M.E.T.A.", description = "Those fiends! Pillaging and murder are one thing, but animal abuse? I'll not stand for it. \n\nThe gnolls have set out traps for animals to catch and feed to their slavering hyena mutts. Find a way to free their fluffy captives and show the ruffians how a mage ethically treats animals!\n\nOf course this makes ethical sense in light of my recent actions. What exactly are you trying to insinuate?", objectives = "Free 6 abused animals.", completion = "That'll show those brutes!" }
WordHunterWoW_QuestEN[66268] = { title = "Third Try's the Charm", description = "What? Another one's seized power? Whatever happened to abhorring a vacuum? Or at least waiting for a respectful period of mourning to pass in order to keep up appearances?\n\nDo they have no decency? No sense of propriety? No respect for a well-crafted plan? I made charts!\n\nDeal with this Bloodclaw fellow. I need a moment.\n\nAnd I don't need your nagging comments, thank you very much!", objectives = "Kill Bloodclaw.", progress = "All according to plan!", completion = "Finally! That has to be the last one. Right?" }
WordHunterWoW_QuestEN[66269] = { title = "Just To Be Sure", description = "Just... kill anyone who looks like they might be magically inclined. Or has organizational skills. Or looks overly ambitious.\n\nReally, just use your best judgement on this one.\n\nYour \"best judgement\" is to stop speaking to me? Come on, {class}! They're... up to something nefarious, obviously!", objectives = "Slay 12 Stormfang elementalists.", progress = "Don't they know they've been outwitted?", completion = "That had to work, right?" }
WordHunterWoW_QuestEN[66270] = { title = "Whack-a-Gnoll", description = "Oh, Light... there are more on their way! How could this happen?\n\nAll my careful planning! The days spent hiding in this rancid lake! The assassinations!\n\nThis should have thrown them into chaos and caused their settlement to crumble, but we've barely slowed them down!\n\nMaybe... maybe you're right, {name}. I've been wrong all along...\n\nNo! Impossible! We're in too deep now anyway.\n\nGo...deal with these new arrivals. I need time to collect myself.", objectives = "Defeat the would-be warlords.", progress = "What are you waiting for?", completion = "They're just going to keep fighting until they find a new leader? That settles it then. If I'm ever going to have a base of operations here, we'll have to kill all of them.\n\nThe plan is that we...\n\nWait, you're leaving? You don't want any part of this? What am I going to do? I can't leave this lake now that I've made an enemy of the gnolls!\n\nFine! Side with those flea-bitten miscreants!\n\nTake what I promised and go. You're not the only \"champion\" in these woods! I'll find someone else to help me!" }
WordHunterWoW_QuestEN[66278] = { title = "One Drakonid's Junk", description = "<A glistening pocket watch lays amongst the many piles of junk. Maybe Gryrmpech will know what to do with it.>", objectives = "Bring the pocket watch to Gryrmpech in the Gardens.\n\nProvided item:", completion = "This was in the shed? It's not mine, but I think I remember who it belongs to." }
WordHunterWoW_QuestEN[66279] = { title = "New Kid on the Clock", description = "Oh yeah, this pocket watch belongs to one of the stewards that help me tend to the gardens. \n\nHe's one of Nozdormu's. Orizmu, I think? I can't keep all these kids straight. Most days he stands next to that hourglass near Alexstraza's tree without moving. Or blinking.\n\nNozdormu's bunch have always been strange, if you ask me. But, he'll be grateful you brought this to him.", objectives = "Take the pocket watch to Orizmu in the Gardens.", progress = "Walking all the way down to the sundial is too much effort for my old bones.", completion = "Thank you, <name>.  Nozdormu will be pleased to have this returned." }
WordHunterWoW_QuestEN[66299] = { title = "The Awaited Egg-splosion", description = "Our prototype worked! Excellent!\n\nNow it's time for the main course. This time, YOU are the chef.\n\nWith some necessary adjustments, you'll suit up in your disguise again. Then you'll take our masterpiece EGG-splosive, dunk it in this rancid stew here, head up to the matriarch's cave, plate it for her, and glide back down with the blasts detonating behind you!\n\nIf all things go as planned, she'll be toast. Because of the explosion. Which will burn her to toasty bits.", objectives = "Slay the Screechflight Matriarch.", progress = "Careful with that chef's hat. It's bound to be a collector's item one day!", completion = "Things didn't go exactly to plan, but no good Goblin scheme ever does! Nice work!\n\nThere will still be Screechflight here, but they'll be easier to cull without their Matriarch organizing their efforts. And the Bluefeathers will actually have a chance to survive.\n\nHarpies and dragons aren't that different. Forgetting their attempted mass digestion of the cliffside, they're akin to a civilization of their own. Maybe there's a peaceful brood out there? \n\nOh, and keep the disguise. Looks good on you." }
WordHunterWoW_QuestEN[66308] = { title = "Feeding the Fire", description = "The creation of new weapons and armor in the Earth-Warder's Forge will insure our eventual victory over the Djaradin.\n\nThe flames of the forge though must be constantly kept fueled. Cindershard Coal will provide the strongest heat, necessary to forge weapons.\n\nYou can find Cindershard Coal from deposits and Elementals within the Cindershard Seam.", objectives = "Collect 30 Cindershard Coal.", progress = "Have you collected fresh Cindershard Coal?", completion = "This coal will do nicely, <name>. That should keep the forge going for a while longer." }
WordHunterWoW_QuestEN[66320] = { title = "The Flow of Time", description = "The threads of time flow like a river, with many bends and branches. Occasionally, those flows can be changed. However, any anomaly left unresolved may doom our destiny to a false timeline.\n\nWe are quickly approaching one of those anomalies. I have sent Chronormu to the Shifting Sands to investigate and correct any issues to the one true timeline.\n\nI foresee that your assistance will be invaluable. \n\nPlease lend us your aid and meet with Chronormu.", objectives = "Travel to the Shifting Sands and speak with Chromie.", completion = "Hello! ... again? I think?" }
WordHunterWoW_QuestEN[66321] = { title = "Bar Their Efforts", description = "Djaradin forces are threatening an attack on our position. I can feel it down to my claws. \n\nWe should strike first. Before they have a chance to mobilize!\n\nGo to the Burning Ascent and wreak havoc on the djaradin forces there.", objectives = "Djaradin forces eliminated.", progress = "Have you weakened the djaradin forces?", completion = "They won't forget the destruction you wrought for a while. Nicely done." }
WordHunterWoW_QuestEN[66323] = { title = "Idling Pie", description = "Now that we have the wares back we can finish up here. But all my workers are lazin' about the city. \n\nFind where they're hidin' and 'encourage' 'em to head back here. A little leftover pie to the face, should have 'em runnin'.", objectives = "Wake up 3 workers in Orgrimmar.", completion = "Many thanks, everyone is back and workin' hard. <his eyes glance over to an extra pie>" }
WordHunterWoW_QuestEN[66324] = { title = "Never Forgotten", description = "The antidote is ready. Use it to search the Support Creche for survivors. Work quickly--the effect will not last long, so you may have to reapply it.\n\nIf any of my people yet draw breath, save them.\n\nAnd if they do not, I ask that you recover their horn signets so that their names may be honored.\n\nWhile inside, perhaps you can find evidence of how this infestation came to be.", objectives = "Recover items and survivors from within the Support Creche.", progress = "None shall die or suffer if it is within my power to prevent it.", completion = "Thank you for rescuing those who could be saved.\n\nRethenash. Katrinasa. Tenezeth.\n\nI vow that the names of the fallen will be remembered." }
WordHunterWoW_QuestEN[66326] = { title = "The Tools of One's Trade", description = "A forge of this power needs specialized tools--ones that can take the tremendous heat. \n\nBut the djaradin have ransacked the place and stole many of the tools we need for this work.\n\nIf you can, recover those tools from them, so that we may continue our efforts to arm our allies.", objectives = "Collect 1 Precision Scale Hammer, 1 Obsidian Bickern, 5 Blacksteel Tongs, and 10 Dragonclaw Punches.", progress = "Have you found the tools we require?", completion = "This is a good start. We can work with the tools you recovered for the time being." }
WordHunterWoW_QuestEN[66327] = { title = "Chasing the Wind", description = "We must take a moment to pause and consider our strategy. \n\nWe need Ohn'ahra's blessing to sound the Horn of Drusahl and summon the green dragons. Without their aid, we cannot win this war. The Nokhud already outnumber the other clans, and their forces are bolstered by the Primalists. And now Koroleth has captured our Windmother! We must therefore find Ohn'ahra before the Nokhud can launch their final attack and encircle Maruukai.\n\nI will send all of our scouts. I only hope we can find her in time.", objectives = "Listen to Scout Tomul's report.", progress = "We should depart as quickly as possible. You may ride Taivan and accompany us, or meet us at the Horn of Drusahl.", completion = "We are too late. The Nokhud have overrun the Horn of Drusahl and slaughtered my people. \n\nThis act of aggression will not go unanswered." }
WordHunterWoW_QuestEN[66328] = { title = "Green Dragon Down", description = "Those dragons went down over the plains to the west. We must get to them quickly before the Nokhud do.\n\nWe would not want them to think of all Maruuk as their enemies because of Balakar's actions.", objectives = "Meet the Khanam Matra at the watering hole.", progress = "The dragons need our help, outsider. We should hurry!", completion = "Our ancestors said the green dragons were tempered and wise. We are fortunate they restrained their anger long enough to hear our side of the story.\n\nNow that we know the Primalists and Nokhud are our common enemy, it is time to take them down." }
WordHunterWoW_QuestEN[66329] = { title = "Blowing of the Horn", description = "Why would they have brought Ohn'ahra here? Unless... \n\n{name}! I do not think Balakar intends to destroy the Horn. I think this is a trap! We must find a way past this wind, quickly!", objectives = "Witness Balakar and Koroleth's plans.", progress = "No, Balakar!", completion = "I will not rest until Balakar answers for the crimes he committed here today. The slaughter of my people, the blasphemy against Ohn'ahra, the treachery against our ancient ally....\n\nVengeance will have to wait. There are more pressing matters. We must help the green dragons." }
WordHunterWoW_QuestEN[66331] = { title = "The Primalist Front", description = "The Khanam Matra sent word that she and her forces have arrived in the Emerald Gardens. They've located Koroleth and her Primalists. It appears a massive enemy invasion is gathering on a beach to the north.\n\nWisely, she has several scouts watching strategic locations around the battlefield. Go and collect their reports, then meet me and my forces at the battlefront. Glory awaits us in battle, and, if we succeed, there will be vengeance.", objectives = "Speak to Scout Tomul, Ari and Belika, Ohn Seshteng, and Merithra in the Storm Scar.", progress = "Every moment we delay, our enemies advance. We must move quickly, <name>.", completion = "Our enemies are one step ahead of us. Do not despair. Our resolve is as strong as our alliance. Prepare yourself, <name>." }
WordHunterWoW_QuestEN[66333] = { title = "Justice for Solethus", description = "So long as a single green dragon draws breath, these Primalists will not defile the Ancient Bough without a fight.\n\nWe are eager to do our part in this battle, but as long as those dragonkiller ballistae are on the field, we cannot approach. The Nokhud's strongest warriors guard them, so you will need to take down the warriors as well.\n\nDestroy the ballistae and Nokhud Warmongers. Eliminate this threat, and the green dragons will turn the tide of battle.", objectives = "Kill 3 Nokhud Warmongers and destroy 3 Dragon-Killer Ballistae.", progress = "Make haste, mortal. I will not commit dragons to battle while those ballistae remain.", completion = "Good riddance to those awful weapons. May no other dragon suffer as Solethus did." }
WordHunterWoW_QuestEN[66335] = { title = "Deconstruct Additional Pylons", description = "With those vile weapons destroyed, the green dragonflight can join the fray in force.\n\nWe are much more familiar with the situation on the ground. We need to light up some targets, so Merithra and her dragons can strike from above.\n\nMerithra gave me these enchanted seeds. Place them near the Primalist pylons. We will use their light to call in attacks from airborne dragons.", objectives = "Mark the Primalist Pylons with Enchanted Seeds.", progress = "I would appreciate if you did not stand so close to me with those enchanted seeds. Thank you.", completion = "I will remain forever grateful that the dragons were on our side during this battle." }
WordHunterWoW_QuestEN[66336] = { title = "The Isle of Emerald", description = "Your part in this has not escaped me, mortal. It is in large part due to your bravery that we were able to defeat the Primalists.\n\nI have invited the centaur to join me under the Ancient Bough. You, along with the Khanam Matra and her people, are welcome in our home.\n\nFollow this path through the archway across the water and into the trees beyond. I will wait for you there.", objectives = "Meet Merithra in the Ancient Bough.", completion = "Welcome to the Ancient Bough. You stand before the Emerald Oathstone of the green dragonflight." }
WordHunterWoW_QuestEN[66337] = { title = "Stormbreaker", description = "{name}, to me! We are within reach of victory!\n\nThe Primalist ranks are broken, and their war is all but through. Everything we have achieved hinges on this final battle against the Primalist leader, Koroleth.\n\nLet us finish this, you and I! Together! To battle, brother!", objectives = "Defeat Koroleth.", completion = "At last, it is done. Our sacred isle is safe once again. Thank you for all you have done for my kind, <name>." }
WordHunterWoW_QuestEN[66339] = { title = "The Nokhud Offensive: The Wind Belongs to the Sky", description = "Is this the end of your time with us, {name}, or will you aid us once again?\n\nMy scouts report that Balakar has withdrawn into his stronghold, where he is holding Ohn'ahra. This is unacceptable!\n\nMeanwhile, his Nokhud raiders storm across the plains wreaking havoc. While we engage them in battle, you could infiltrate the Nokhud stronghold and rescue Ohn'ahra. Will you do this for us?", objectives = "Defeat Balakar Khan and rescue Ohn'ahra in The Nokhud Offensive.\n\nYou can access The Nokhud Offensive solo by queuing for it in Follower Dungeons.", completion = "With this victory, you have helped the Maruuk more than you will ever know. Our most sincere thanks, <name>. Go with the blessings of Ohn'ahra." }
WordHunterWoW_QuestEN[66340] = { title = "Into the Azure", description = "We have done our part. Though I must remain here to watch over the Oathstone and guide the green dragonflight, know that you leave here with our gratitude and faith.\n\nI have received word the Kirin Tor are seeking help in claiming the Azure Oathstone. Helping them with their Oathstone will bring us one step closer to healing Azeroth.\n\nFind Pakina and Masud the Wise of the Kirin Tor. They will instruct you further. Safe journey and pleasant dreams, {name}.", objectives = "Meet Masud the Wise in the Forkriver Crossing.", completion = "Hail adventurer! I'm glad our call for help reached you." }
WordHunterWoW_QuestEN[66344] = { title = "With the Wind at Our Backs", description = "So the Primalists have recruited Clan Nokhud as allies. \n\nWe have held off the Primalists until now, but the Nokhud have brought a new weapon: a dragonkiller ballista. I fear Solethus will not be the last dragon to fall to its foul storm magic.\n\nCome. I will take you to the dragons' haven at Shady Sanctuary. You can tell me what you know of the Nokhud while the Khanam Matra gathers her forces. We must prepare for our next move.", objectives = "Ride with Gerithus and Merithra.", completion = "We have arrived, mortal. Welcome to the Emerald Gardens." }
WordHunterWoW_QuestEN[66349] = { title = "Training Rock", description = "Remove those rocks!", objectives = "Remove 3 rocks" }
WordHunterWoW_QuestEN[66351] = { title = "Smoke Over the Mountain", description = "<Pathfinder Jeb looks at the mountain ridge beyond the camp and sniffs.>\n\nI don't like it. Pathfinder Yips should've been here days ago. Was gonna help me teach this new batch of explorers how to climb these pillars safely.\n\nNow I see smoke in the distance.\n\nI don't like it at all.", objectives = "Find Pathfinder Yip's plane.", completion = "Ye're just in time. Pathfinder Yip is starting to lose her grip up there!" }
WordHunterWoW_QuestEN[66352] = { title = "What the Enemy Knows", description = "It is vital that we determine the Sundered Flame's mission in these ruins and how it relates to the arcane surge.\n\nWe'll do this the old fashioned way: reconnaissance and espionage.\n\nThe ruins are overrun with Sundered Flame devotees. I am sure some of them carry orders that may illuminate their mysterious goals.\n\nUse any means necessary to obtain these documents.", objectives = "Find Sundered Flames documents and bring them to Lathos.", progress = "Have you found anything yet, <name>?", completion = "Thank you, <name>. I am humbled by your skill and efficiency.\n\nMaybe I'm not the only one who will be a \"good influence\" on Rannan.\n\nNow... let us find out what the Sundered Flame is doing here." }
WordHunterWoW_QuestEN[66353] = { title = "R.A.D. Anomalies", description = "There is a LOT of arcane energy here...\n\nBut! The R.A.D. can help with that! It's an awesome device--it's right in the name: \"Rannan's Awesome Device!\" It detects AND dispels arcane energy.\n\nHere... hold it! Do you feel the POWER in your hands? No?\n\nWell, now that you've got it, take it and dispel those anomalies!", objectives = "Use the R.A.D. to dispel three arcane anomalies.", progress = "Go! Go! That arcane energy is not going to dispel itself.", completion = "Hm... You dispelled the anomalies, but the R.A.D. still detects an arcane surge... and it's rising by the minute.\n\nThat... can't be a good thing." }
WordHunterWoW_QuestEN[66354] = { title = "The Spark", description = "The forge is ready. All it needs now is flame.\n\nPlace the damaged Oathstone fragments upon the forge, and Wrathion shall provide the spark to ignite the process.", objectives = "Reform the damaged parts of the Oathstone.", progress = "Have the fragments been reformed?", completion = "The damaged pieces of the Oathstone are repaired! This is only the beginning of what can be accomplished here!\n\nWith the forge re-ignited I can begin the process of crafting new weapons and armor to aid our efforts." }
WordHunterWoW_QuestEN[66356] = { title = "Irontree", description = "", objectives = "" }
WordHunterWoW_QuestEN[66363] = { title = "Basilisk Bucklers", description = "Interlinked scales are the key to stopping an arrow. The bucklers we make are the best in the plains. However, I am short of basilisk hides for my next order. \n\nI see you are interested in learning about our crafts. Gather basilisk hides from around the Dragon Isles, and I will give you instruction on our techniques.", objectives = "Gather 20 Rigid Basilisk Hides from the basilisks of the Dragon Isles for Dhurrel of the Maruuk Centaurs.", progress = "Do you have the hides?", completion = "These are of excellent quality! You have my thanks.\n\nFor your help, please take some of the extra leather we have in our stores. I can also give you some insight about your trade, as I promised." }
WordHunterWoW_QuestEN[66364] = { title = "To Fly a Kite", description = "Let me tell you about an opportunity.\n\nThe proto-drakes and proto-dragons have an amazing range of motion on their wings. And the ribbing! It is so extendable. We mostly make our kites from stretched hides. With the proto-drakes causing havoc, I was wondering if you could return some of their wings to me? I can make kites that would be the envy of the tribe.", objectives = "Gather 10 Fresh Proto-Dragon Wings from the proto-drakes and proto-dragons of the Dragon Isles for Temnaayu of the Iskaara Tuskarr.", progress = "Do you have the wings?", completion = "These will work masterfully. I will have a working kite fashioned in no time. \n\nOh, and for all your help, let me give you some insight to your trade. It is the least I can do." }
WordHunterWoW_QuestEN[66368] = { title = "Island In A Storm", description = "There has been little time to rest. The elementals' assault is relentless!\n\nA moment of respite would be welcome and allow me to craft more wards for our defense.\n\nSee what you can do to thin out the onslaught on our perimeter.", objectives = "Eliminate 10 Blazing Manifestations and Melter Igneous.", progress = "They must be culled.", completion = "It was a welcome moment of rest. In return I have a gift for you." }
WordHunterWoW_QuestEN[66369] = { title = "The Earthen Ward", description = "I have empowered a ward using the rings you collected. It has gathered the very stones of the earth around it and created a Living Earthen defender to protect this territory.\n\nTest the Earthen Ward to ensure it's functional.", objectives = "Activate the Earthen Ward.", progress = "Was the test successful?", completion = "Thank you for your aid, <name>. I will place more of these wards throughout the area to combat the djaradin and the elementals. Use these charms to activate them when you need assistance." }
WordHunterWoW_QuestEN[66383] = { title = "Legendary Assistance", description = "{name}, we have convinced the Enlightened Brokers to provide additional supplies for the battle against the Jailer!", objectives = "Visit Vilo, the Enlightened Quartermaster, to see what is available.", completion = "Welcome. Please view my wares, several of which can assist you in the crafting of Legendaries!" }
WordHunterWoW_QuestEN[66390] = { title = "Missing Merchandise", description = "Hmmph, those sea-brained Seabraids are off on another adventure, and I'm stuck here sifting through their goods!\n\nAh, maybe I'm a bit bitter, but I do wish Tawny could be a bit more brief. I don't need a novel, just some instructions is all. And on top of it all some of the merchandise has disappeared, along with one of my workers! \n\nWould ye mind gettin' it back for me? I'm sure ye could tempt him with an exchange of a drink, or throw this at him if ye can't.", objectives = "Retrieve the stolen goods from the thief at the Stormwind Harbor.", completion = "Ah! Ye got seawater on the merchandise! Ah well, I don't think the Seabraids will mind too much... long as it's intact." }
WordHunterWoW_QuestEN[66391] = { title = "To the Ruins!", description = "Are you interested in hearing about my invention, the R.A.D.? No?\n\nWell, I'll tell you anyway--because it found something.\n\nToday it detected a HUGE SURGE of arcane energy from the Karnthar Ruins. Lathos thinks the Sundered Flame are to blame. It's the PERFECT opportunity to showcase the R.A.D.!\n\nWanna come? It's going to be awesome.", objectives = "Meet Rannan and Lathos in the Ruins of Karnthar.", completion = "You missed it! We walked RIGHT into a Sundered Flame patrol. \n\nLathos SLASHED through them, but there were too many!\n\nSo, I started casting arcane explosions left and right... KAPOW! ZING!\n\nOh, but um, yes... the energy surge..." }
WordHunterWoW_QuestEN[66392] = { title = "Rallying Nature's Allies", description = "We cannot give into despair now. We must push forward. We must think of another way through the barrier.\n\nFirst, we need our allies. Countless elementals summoned by Rymek are pouring through the portal. We will need an army that can move in the Dream like we can, or one that can be brought in easily.\n\nRally the druids and centaur in Shady Sanctuary. It is time to call upon their oaths to preserve the grove.", objectives = "Muster the druids and gather the empowered anchors in Shady Sanctuary.", progress = "Are you ready to cross to Ardenweald?", completion = "I will go with you into Ardenweald. I will tell Ysera that we need her back, and we know a way to do it. \n\nI should be the one who makes this sacrifice. I've lived a long life. I never wanted to live longer than my son. This way, I can atone for Rymek's betrayal and bring back our Aspect.\n\nAre you with me?" }
WordHunterWoW_QuestEN[66393] = { title = "To Somnikus", description = "Somnikus has been melancholy and agitated since the death of his son.\n\nThough we have all endured loss, I cannot imagine what I would feel were something like that to happen to Gerithus.\n\nGo with Rymek to the isle, and see if there's anything we can do. Somnikus suspects that the Primalists are on the verge of another attack. I fear that he may do something rash.\n\nDo not worry. Because of your help with the Emerald Oathstone, you can cross the barrier easily.", objectives = "Meet Somnikus with Rymek near the Oathstone in Ancient Bough.", completion = "Welcome to Ancient Bough, young one. \n\nDid Merithra send you to check on me? I am far too old for her to be worrying about me." }
WordHunterWoW_QuestEN[66394] = { title = "Thin the Veil", description = "There must be a way to lower the barrier from within this grove. I sense several points around us that strengthen it.\n\nIf you can deactivate enough of those, we should be able to lower it the rest of the way so the others may join us.", objectives = "Deactivate Barrier Moorings in Ancient Bough.", progress = "Have you found the barrier moorings?", completion = "That should do it. The barrier is about to come down. \n\nSoon the others will be able to join us in the Emerald Dream, and we can fight together again." }
WordHunterWoW_QuestEN[66395] = { title = "The Chittering Rocks", description = "Merithra needn't worry about me. I'm fine. My son's death... I'm fine.\n\nIf you really want to help put my mind at ease, there is something you could do. I suspect Primalists will try to invade these lands again. Unlike last time, I doubt they'll attack the Ancient Bough directly. They know we'd defeat them.\n\nSee those rocks over there? Those off-color, slightly smelly rocks? I hear something moving underneath them. Perhaps Primalists are lurking nearby! Could you investigate? Squash whatever you find.", objectives = "Investigate Suspicious Permafrost and slay Glacial Tunnelers.", progress = "I can hear them skittering around under the rocks. Who'd dare to summon creatures like that so close to the portal?", completion = "I knew there had to be something there. And to think, they were so close to the portal. Now I can contemplate... other things.\n\nWhile you were hunting, Rymek and I had a lovely conversation. He's quite understanding and sympathetic. In a way, he reminds me of Solethus...\n\nHe asked if he could see the portal to the Emerald Dream with his own eyes. I see no reason why not, especially since you've cleared those spiders away. I'm sure he'll be quite impressed." }
WordHunterWoW_QuestEN[66396] = { title = "Guarded Appreciation", description = "I know it can be quite exhausting work to defend such an important locale. And often, we drakonids and dragonspawn get very little thanks for our dedication.\n\nI wish to bestow some of my own appreciation to the guards here in Ancient Bough.\n\nHere, offer them these gifts from me, as a sign of friendship. I hope my heartfelt gesture properly expresses my gratitude.", objectives = "Give 6 guards Rymek's Gift.", progress = "Have you given the guards my gifts?", completion = "Very good. I hope they like those gemstones. I made them myself, just for this special occasion." }
WordHunterWoW_QuestEN[66397] = { title = "Our Full Strength", description = "We need reinforcements, and quickly. But Merithra cannot yet join us in the grove because of the barrier. We will need to manage both from here within the Dream.\n\nSlay these Primalists and take anything you need from them, so we can melt those ice prisons and free the grove guards.", objectives = "Free Emerald Scaleguards and Wardens.", progress = "That was too cold. Close. Too close.", completion = "Thank you for breaking me out! I can't believe that Ysera is actually here, back in the Emerald Dream! Just like in my theory. \n\nI'd dearly love to ask her ten thousand questions, but I have to focus. There's still the problem of Rymek.\n\nAnd I saw where he was headed, too, just as he caught me in ice.\n\nHe's after something in the Dream, something powerful. I don't know what, but we have to reach him before he finds whatever it is!" }
WordHunterWoW_QuestEN[66398] = { title = "The Emerald Dragonflight", description = "If we are to eradicate the Primalists from the Emerald Dream, the one place we must secure is Lunedane. According to my son, that is where Rymek has gone.\n\nIt is the last line of defense for the nascent Tree. There, an ancient artifact shields the Tree from being found. And, it is powerful enough to expel all our enemies at once.\n\nI do not know if my mother has the power to command and use it anymore. But we will deal with that once we have found and stopped Rymek.\n\nFly with us, as one.", objectives = "Speak to Gerithus, and fly with Merithra and Ysera to Lunedane.", completion = "We've made it. But Rymek has already started his assault. We can't let him break through!" }
WordHunterWoW_QuestEN[66399] = { title = "We'll Cross that Bridge", description = "We have to do something about this snow! If we're to give you proper support against Rymek and his minions, we can't have our wings freezing off.\n\nI sense powerful Frost Cores nearby. They're probably sustaining this blizzard. If you can destroy them, we can take out Rymek's minions in short order.\n\nAnd Somnikus is out there too. He flew off for Rymek like a dragon possessed. We need to get to him as soon as we can.", objectives = "Destroy the Frost Cores and reach Somnikus.", progress = "Everything hurts.", completion = "<Somnikus's breathing is labored and pained. He shivers with cold.>\n\nI held him off... as long as I could." }
WordHunterWoW_QuestEN[66400] = { title = "Winter's Fall", description = "<Somnikus struggles to breathe as he slowly freezes.>\n\nI managed... to stop him from reaching the tree. I hope it was enough.\n\nRymek must fall, now. It is up to you.\n\nTell Ysera and Merithra that I am sorry... for being a foolish old dragon.", objectives = "Defeat Rymek.", completion = "Rymek is defeated, but there are still too many elementals and Primalists roaming through the Dream.\n\nI suppose... now we find out who the Dreamer really is." }
WordHunterWoW_QuestEN[66401] = { title = "The Dreamer", description = "We have fought so hard to reach this point, and only one thing remains. The power in Lunedane will only respond to someone who can command the Emerald Dream from within.\n\nI had thought that it could only be my mother, but... I see how she has changed. \n\nI do not know if that difference is better, but it is real and I must acknowledge that.\n\nCome, let us face this moment together.", objectives = "Unleash the power of the Dream Locus.", completion = "I am the Dreamer." }
WordHunterWoW_QuestEN[66402] = { title = "Like Mother, Like Daughter", description = "From the moment I stepped into the Dream again, I knew that things were different. But now that we have beaten Rymek and his Primalists, I must consider all of the implications of what has happened.\n\nMy daughter has worked to keep the green dragonflight together after my death. It is only fitting that she be the one to ascend now. \n\nMerithra must lead the Emerald Flight.", objectives = "Witness the ascension of Merithra.", progress = "I am ready. I must be.", completion = "Where my mother once flew, I must fly now and in the future. Where her breath brought peace and life, so must mine.\n\nI pledge that I will do my best as the leader of the green dragonflight. I promise that I will do whatever it takes, as Ysera did for so many millennia." }
WordHunterWoW_QuestEN[66409] = { title = "Pressing Matters", description = "The chieftain is not taking visitors.\n\nWhether Iskaara sent you or not, we're dealing with our own share of trouble right now. We don't need outsiders bringing more of it.\n\nIf you want our time, make yourself useful and help our guards. The djaradin have been attacking us from across the river. Flameshaper Lorak is behind the assault. He may not look like much as far as djaradin go, but he's got more brains than the rest of them.\n\nDeal with him and bring back proof. Then we'll talk.", objectives = "Collect a trophy from Flameshaper Lorak at Scalecracker Keep.", progress = "If that weapon's just for show, tell us now so we don't waste time.", completion = "I'll admit I didn't expect you to come back alive." }
WordHunterWoW_QuestEN[66410] = { title = "Worst Impressions", description = "<Hakota turns the trophy over in his hand before clasping it. He grimaces.>\n\nSo this is what we've been reduced to. An outsider does more work for us in a day than our chieftain has in weeks.\n\nCome. I will take you to him.\n\nMaybe this will be the kick in the stern that he needs.", objectives = "Speak to Tutaqan.", progress = "What do you seek to take from us?", completion = "<Tutaqan tosses the trophy on the ground nearby, tired and disinterested.>" }
WordHunterWoW_QuestEN[66411] = { title = "Troubled Waters", description = "It saddens me to see our chieftain like this, but our needs cannot wait.\n\nThe river has provided for us for generations. But as the djaradin push forward, the waters recede, and the creatures fight with each other for space and resources. \n\nWithout guards, our anglers cannot venture far to fish. Our food stores dwindle by the day.\n\nYou do not seem to need protection though. Take this net to help gather any fish you can from the river. Meat from the nearby crabs would also be welcome.", objectives = "Gather 10 Warmwater Riverfish and 6 Succulent Snapper Meat.", progress = "The river was once beautiful and its bounty plentiful. I pray that its gifts will return to us one day.", completion = "At least our children will not go hungry while our chieftain neglects his duties. Thank you, <name>." }
WordHunterWoW_QuestEN[66412] = { title = "Carry On, Basilton", description = "There is one more thing this old drakonid would like to ask you, before you leave.\n\nBack when Lord Basilton and I first met, we would go on all sorts of adventures together. I think that's why he wanders off. He misses exploring.\n\nI can't do that for him anymore. But you can! You can take him to see places I never would have dreamed of, I can tell.\n\nHowever, we should ask Basilton what he thinks first.", objectives = "Speak with Basilton in the Gardens.", progress = "Let's see what Basilton thinks.", completion = "I'm jealous of him, if I'm being honest. To be young again, and exploring the world. You'll have to visit, sometime, so you can tell me what he's been up to." }
WordHunterWoW_QuestEN[66413] = { title = "Encroaching Heat", description = "<This fish has clearly been dead for some time.\n\nUpon closer inspection, you notice that it appears to have been boiled--probably while still alive in the river.\n\nUnujaak back at the village might be interested in this.>", objectives = "Take the Half-Boiled Fish to Elder Unujaak.", completion = "Oacha'noa preserve us! How my heart aches to see the river disturbed in this way. \n\nThis must be yet another of the djaradin's atrocities. Their fiery magic has been heating the river beyond anything these poor creatures can endure.\n\nBut it would be disrespectful to allow this one to go to waste. Go on, throw it in the pot. We will use it for tonight's meal." }
WordHunterWoW_QuestEN[66414] = { title = "All But One", description = "I have seen what you've done for the village. In easier times, I would have handled it, but...\n\n<Tutaqan glances towards the river, then back to you.>\n\nSome of our ottuks went missing recently. We believe they swam too close to the djaradin's territory. Several were recovered. None of them alive. Few in one piece.\n\nWe could not find my ottuk, Ipko. She has been my hunting partner for many years. If she...\n\n<He shakes his head.>\n\nPlease... aid me. If you search the river, I will search the shore.", objectives = "Find Ipko.", progress = "I shouldn't have let her wander so far...", completion = "This is my fault." }
WordHunterWoW_QuestEN[66415] = { title = "The Only Way Past Is Through", description = "Unujaak told you to come, didn't he? He was the one who helped me find Ipko when I became a hunter--or, rather, helped Ipko find me. They choose and we are chosen.\n\nHe is hurting. Everyone is hurting because of me. I know that they need me to lead, but I have been half of a leader without her. If I couldn't protect her, how can I protect all of Uktulut?\n\n<He takes a deep breath.>\n\nI cannot forgive myself. But I cannot let that weight keep me from putting at least one foot on the path I must walk.", objectives = "Help Tutaqan find a new ottuk companion.", progress = "I knew this would happen one day, though it does not blunt the pain.", completion = "Nothing will replace Ipko. But water can only fill hands cupped to receive it." }
WordHunterWoW_QuestEN[66417] = { title = "Salvaging Supplies", description = "Bah! I can't believe Tutaqan's still moping around when we need him to command his guards and hunters!\n\nWe used to trade with the Iskaara at our pier, but that's gone belly up with the djaradin closing in and scaring off our traders. Half of last month's supplies and most of our boats are still lost out in the shallow river.\n\nThe guards and hunters want to help, but they've got no weapons. You look like you can protect yourself, so get out there and grab something I can make spears with!", objectives = "Collect 8 Whalebone Fragments and 30 Waterlogged Wood.", progress = "Once our guards and hunters have new weapons, I can pull together a group to gather the rest of the wreckage.", completion = "It's about time! They're a little wet, but I'll be able to make many fine weapons with these." }
WordHunterWoW_QuestEN[66418] = { title = "Testing the Tuskarrsenal", description = "The first weapon is ready! Soaking the bones in river water warmed by the djaradin's fire made them more pliable. I'll remember that trick!\n\nSince you've been helpful so far, I'll do you the honor of letting you test out some authentic Uktulut weaponry. You'll find no sharper blade or sturdier haft this side of the Dragon Isles.\n\nGo test this out in our training area for me. Maybe it'll remind the chieftain what real fighting looks like! Ha!", objectives = "Take the Uktulut Bone Spear and destroy 4 Tuskarr Training Dummies.", progress = "Our training area is just up the hill. Make sure those weapons are ready to crush some djaradin.", completion = "Haha! I heard that commotion all the way over here! \n\nIf that talk doesn't get Tutaqan moving again, I don't know what will.\n\nAt least our hunters will have all the weapons they need to defend our village, with or without their huntmaster's help. Thanks, <name>." }
WordHunterWoW_QuestEN[66419] = { title = "Allegiance to One", description = "", objectives = "" }
WordHunterWoW_QuestEN[66420] = { title = "Happy Hour", description = "Now that the merchandise is back, it's time ta get everything else sorted out.\n\nWith everything going on some of my crew decided it would be okay to disappear for some extended meal times.  See if ye can find them and get them back here. \n\nWe can all celebrate AFTER the work is done.", objectives = "Throw briny seawater at 3 workers in Stormwind.", completion = "Great job! Now that we're all back ta work we'll make good time." }
WordHunterWoW_QuestEN[66421] = { title = "The Storm Scar", description = "", objectives = "" }
WordHunterWoW_QuestEN[66422] = { title = "The Expedition Continues!", description = "An ancient site, an organization with inscrutable motivations--even Rannan's R.A.D and its analyses... \n\nIt all stirs the explorer in me.\n\nWe must discover more about what's going on here.\n\nThere are stairs to the south leading up to a tower. We shall press on.", objectives = "Meet Rannan and Lathos by the tower.", completion = "These Sundered Flame did not die by my hand... or by Rannan's \"signature move.\" \n\nThey were dead when we arrived. \n\nRannan believes they suffered multiple traumatic wounds caused by arcane energy.\n\nI agree with his observations. But it's unclear if it was the dragon console discharging or friendly fire..." }
WordHunterWoW_QuestEN[66423] = { title = "Worries and Validations", description = "The deaths of these Sundered Flame underscore how dangerous the Ruins of Karnthar are.\n\nBut Rannan believes that with some tinkering the R.A.D. can still quell the energies here.\n\nAgain, we're treating the symptoms and not the root cause.\n\nSearch the ruins for clues and see if you can discern their original function. And make haste, {name}. We may not have much time.", objectives = "Find clues about the origin of the ruins.", progress = "Were you able to learn anything about the ruins?", completion = "This is... not good news.\n\nIf Sindragosa could not control Karnthar and ordered this station abandoned, I can only imagine the nefarious things that the Sundered Flame could do with it.\n\nWe must not let it fall into their hands." }
WordHunterWoW_QuestEN[66425] = { title = "Arcane Overload", description = "There! Finished!\n\nMay I present to you... the R.A.D.D.E.R!\n\nDUN DUN DUUUUN! \n\nI have calibrated it to the frequency of the energy surrounding the dragon consoles and inscribed a glyph of dispel magic on it.\n\nThe R.A.D.D.E.R. will dispel the arcane energy and shut down the dragon console, but the glyph will weaken after each use.\n\nPretty handy, isn't it?\n\nI detect four of these consoles in our vicinity. Go shut them down!", objectives = "Help Rannan dispel the arcane bubbles.", progress = "Were you able to dispel all the arcane bubbles with the R.A.D.D.E.R.?", completion = "You've done it <name>!\n\nWell, you and the R.A.D.D.E.R...\n\nBut whatever... Now, help me get Lathos back to Camp Nowhere." }
WordHunterWoW_QuestEN[66426] = { title = "Running Out of Time", description = "I can feel the arcane surge growing as we speak. \n\nI suspect there is not much time before the ruins make Rannan's J.A.M. look like a distant star in the night sky. \n\nWe have to get there and stop it.\n\nPlease be careful, {name}. \n\nMeet us by the east tower. We will assess the situation there.", objectives = "Reach the east tower.", completion = "This is worse than we thought. The arcane energy is almost at its peak.\n\nSomething is hastening the process." }
WordHunterWoW_QuestEN[66427] = { title = "A Looming Menace", description = "The arcane wounds I suffered cannot be healed in the field. I am afraid that they are too grave for me to fight. \n\nI must ask your help again, {name}.\n\nYou have to find Tharohn and stop her from overloading more consoles. \n\nDoing so would buy Rannan a few precious moments to calibrate the R.A.D. ... R.A.D.D.E.R... whatever he's calling it now. \n\nMaybe then we can thwart the Sundered Flame's machinations.", objectives = "Kill Tharohn.", progress = "Do not waste a moment. We are on borrowed time.", completion = "It is done then.\n\nNow it is all on Rannan. I trust his abilities. They have gotten us this far..." }
WordHunterWoW_QuestEN[66428] = { title = "Friendship For Granted", description = "Alright! The R.A.D.D.E.R.E.R is calibrated and ready to go--for you!\n\nWhy am I not using it? Simple! \n\nYou have to think of and consider all the possibilities. \n\nLet's say it blows up. Who would fix it if I am injured, unconscious, or dead? Could you imagine? \n\nNow, go dispel the barrier so we can return to camp and get Lathos patched up. I'll be... standing back.", objectives = "Use the R.A.D.D.E.R.E.R to dispel the arcane barrier.", progress = "Is this day going to get any better?", completion = "Just like that he's... gone?\n\nHe gave his life to save us because the R.A.... the machine didn't work.\n\nLathos believed in me... I should have listened... I let him down..." }
WordHunterWoW_QuestEN[66429] = { title = "I Will Remember", description = "I... I need a few moments, please. \n\nGo back to Camp Nowhere, {name}. I will meet you there.", objectives = "Meet Rannan outside of Camp Nowhere.", completion = "It was only at the very end that I began to appreciate Lathos. I took his patience and experience for granted.\n\nWe owe him our lives.\n\n<Rannan looks towards the Ruins of Karnthar.>\n\nI will never forget him." }
WordHunterWoW_QuestEN[66431] = { title = "In Mourning", description = "This did not need to happen. Those cowardly djaradin... slaughtering our ottuks and leaving them for their twisted beasts to pick clean...\n\nI do not take Tutaqan's grief lightly, but I worry for the future of our people if he dwells in darkness and grief for too long. \n\nWe need to act.\n\nIt looks like he was headed to the overlook above us. You have done him a great favor this day. He may be open to any good will you can show him. Please, see what can be done.", objectives = "Attempt to help Tutaqan.", progress = "Please leave me be.", completion = "<Tutaqan rubs his face with both hands, sighing deeply. He looks haggard.>" }
WordHunterWoW_QuestEN[66435] = { title = "Site Salvage", description = "I've worked with many elementals as a shaman, but I've never seen any this aggressive!\n\nThe Expedition discovered a titan vault here, but a barrier protects the inner chamber. When we tried to dispel the barrier, I think we triggered some kind of security system... There were suddenly angry elementals everywhere!\n\nMany explorers were working in the dig site when the elementals attacked. Many of them are trapped, and NONE of them are fighters. \n\nPlease go down into the dig site and help them retreat!", objectives = "Rescue 5 Beleaguered Explorers in Life Vault Ruins.", progress = "I am only a consultant for the Expedition, but I care for the explorers I've met here. We can't leave any of them behind!", completion = "Everyone's safely within our new perimeter. Thank you, <name>." }
WordHunterWoW_QuestEN[66436] = { title = "Unearthed Troublemakers", description = "The earth elementals are not just trying to repel us, they're destroying artifacts and equipment, too! It's as though they've been programmed to destroy anything titan...\n\nWe're holding them off, but we can't continue to study this site while they're here. Please help us push them back so we can have some exploring room!", objectives = "Kill 12 Earth Elementals in the Life Vault Ruins.", progress = "The elementals caught us by surprise! Be careful!", completion = "That should be enough to solidify our position here. Good work, <name>." }
WordHunterWoW_QuestEN[66437] = { title = "A Key Element", description = "<This orb of earth thrums with energy.>\n\n<Elementalist Taiyang might know what to do with it.>", objectives = "Return the Orb of Primal Stone to Elementalist Taiyang in the Life Vault Ruins.\n\nProvided item:", completion = "I can feel the elemental energy stored within this orb. You may have found a solution to our troubles here." }
WordHunterWoW_QuestEN[66438] = { title = "Lofty Goals", description = "Air is a powerful element. It cuts through stone and fills sails to take us where we need to go.\n\nMy hypothesis is that air will be the most effective at removing this barrier. It's simple, really.\n\nMy scouts report they've found the Orb of Primal Gales. Scout Ri'tal can lead you to it. You can find them near Hornswog Hollow. Quickly!", objectives = "Find Scout Ri'tal in Hornswog Hollow.", progress = "Have you found the scout?", completion = "Tae'shara stays above many tasks, preferring to delegate. I can see why the Orb of Primal Gales interests her. I'll hold onto it for now." }
WordHunterWoW_QuestEN[66439] = { title = "Rapid Fire Plans", description = "Elemental orbs, eh? If there's earth, there's bound to be fire!\n\nThe primalists over near tae hornswog nests are reshapin' tae land with lava. If anyone has an interest in tae Orb o' Primal Flames, it'd be them!\n\nTake them out and see if they have anythin' useful!", objectives = "Collect Primal Flame Fragments from Primalist Forces in Hornswog Hollow.", progress = "Acadia had a lead on the Orb of Primal Flames. Have you found it?", completion = "Ah, the Orb of Primal Flames. It is as vibrant and fiery as Acadia. I will hold onto it for now." }
WordHunterWoW_QuestEN[66440] = { title = "Closure", description = "I do not know what to say. I had no idea that the chieftain's pain ran so deep.\n\nIt makes sense. Ottuks are not pets to our people--especially not to hunters like our chieftain. They are our friends, our companions... and members of our families.\n\nIpko was Tutaqan's first and only ottuk. Uktulut hunters hold this bond to be sacred.\n\nI will see that her passage to the place of our ancestors is a peaceful one.", objectives = "Speak to Tutaqan.", progress = "This is all I can do.", completion = "<Tutaqan's jaw is set tightly, tears brimming in the corners of his eyes. He does not look at you.>" }
WordHunterWoW_QuestEN[66441] = { title = "Distilled Effort", description = "The Orb of Primal Stone is a fortuitous find, but Acadia and Tae'shara have conflicting hypotheses regarding the barrier.\n\nI have my own hypothesis. Perhaps with more elemental orbs an answer will become clear.\n\nOne of the explorers saw an oversized water elemental in a nearby cave. Defeat the elemental, and perhaps you will find another orb.", objectives = "Kill Acequian in the cave east of the Life Vault Ruins.", progress = "Did the elemental have another orb?", completion = "We must be like water: ready to adapt. Thank you for bringing the Orb of Primal Waves to me." }
WordHunterWoW_QuestEN[66442] = { title = "Let's Get Theoretical", description = "We now have four elemental orbs! Let us see which hypothesis proves fruitful.", objectives = "Help test the orbs against the Titan Barrier in Life Vault Ruins.", completion = "My original hypothesis stands firm. The elements are more effective together." }
WordHunterWoW_QuestEN[66443] = { title = "Calling the Hunting Party", description = "<The resounding call of a hunting horn rumbles from the center of the village, calling the Uktulut hunters to attention.\n\nYou should investigate.>", objectives = "Investigate the reason for the hunting call.", progress = "This could be our only chance to hit them where it hurts!", completion = "If the chieftain doesn't take care of the job, I'll smash that djaradin to pieces myself. Mark my words." }
WordHunterWoW_QuestEN[66444] = { title = "While the Iron Is Hot", description = "I spoke to our lookouts on the way down. They say this djaradin--Zhurtan the Riverboiler--has begun his heinous ritual southwest of here, close to the waterfalls where many of our ottuks build their nests.\n\nIf they're boiling the river upstream from us now, I assume they've decided to be done with us more quickly. We would be forced to starve or retreat. We will do neither.\n\nThey've prodded us like cowards afraid of a true fight. So let's bring the fight to them this time, shall we?", objectives = "Slay Zhurtan the Riverboiler.", progress = "We have your back, as you have ours.", completion = "Our river--and our people--could not have been saved without your help. \n\nThe Uktulut tribe owes you a great debt." }
WordHunterWoW_QuestEN[66445] = { title = "Honor Our Fallen", description = "The djaradin have no regard for the sanctity of the Citadel or the bodies of our kin! They break the bones of the dead and take their personal keepsakes as souvenirs.\n\nThis disrespect cuts at the heart of every proud black dragon. They deserve honor. \n\nRecover these items that the djaradin have stripped from the bodies of our fallen.", objectives = "Recover 8 Fallen Defenders Ring, 3 Earth-Warder's Flame Blade and 1 Horn of Scorxia", progress = "Have you recovered the items of the fallen?", completion = "The memory of those who fell will not be lost. No thanks to the djaradin.\n\nThese items will be kept safe and we will remember the dead." }
WordHunterWoW_QuestEN[66447] = { title = "Beyond the Barrier", description = "Now that the barrier is down, let us explore the vault!", objectives = "Investigate the Life Vault in the Life Vault Ruins.", progress = "There's a lot to examine in the vault, but we should start small to be safe first!", completion = "I think we'll be alright now, <name>. Thank you. It's time for the Expedition to dig deeper!\n\n\n\nJust a little shaman humor. Too soon?" }
WordHunterWoW_QuestEN[66448] = { title = "The Wayward Waywatcher", description = "The Waywatchers have kept the roads of Thaldraszus safe for travelers for as long as I can remember. It is a duty that my family has upheld with honor for generations.\n\nAlas, my sister Alvi seems less than interested in that honor of late. She is supposed to report to me here each morning, but I have not heard from her in over a day. \n\nIf you find a bronze drakonid east of here, lazing about with her head in the clouds, I ask that you direct her to me. Otherwise, I will have to seek her out myself.", objectives = "Find Waywatcher Alvi.", completion = "Oh, gracious, a traveler. Please forgive me, I am a bit of a mess at the moment." }
WordHunterWoW_QuestEN[66449] = { title = "Hands-Off Operation", description = "Qalashi dustbinders are trying to imprison our whelps. It seems their leader is planning to use them for some nefarious purpose. We cannot let this happen!\n\nBut the djaradin are not the only enemy here. Phoenixes are also tracking our whelps, presenting even more danger. \n\nYou must protect the the whelps and eliminate the enemies that threaten them. Osoria will assist you.", objectives = "Save 8 Endangered Whelps while eliminating 12 Searclaw Phoenixes and Ashbinder Tornecha.", progress = "Have you eliminated the threats?", completion = "Even the smallest black dragon whelp must be protected. Our future depends on it.\n\nYou have accomplished great things today." }
WordHunterWoW_QuestEN[66456] = { title = "A Poisonous Palette", description = "I may not be great at my job, but at least I paid attention when I was learning how to do it. Every Waywatcher worth her scales knows how to make a proper antidote. I just need enough poison to mix it properly.\n\nNori said the tarasek who attacked her had spears coated with the stuff. Find them and bring their spears to me. If my hunch is correct, I'll be able to make an antidote with the residue from the spearheads.\n\nI just hope we have enough time.", objectives = "Gather 8 Envenomed Spears.", progress = "Please hurry, <name>. I am keeping Nori stable for now, but the poison is still spreading.", completion = "<Alvi takes the spears that you gathered. She carefully scrapes her dagger across one of the blades, removing a film of sticky, sickly sap.>\n\nIt's just as I thought. Thank you, <name>. This should be enough for an antidote, and I even think I know where the poison is coming from." }
WordHunterWoW_QuestEN[66457] = { title = "Ending the Blue Period", description = "The Embertooth all follow an oversized brute that I've taken to calling Bluescale. He has always been the aggressive sort, but until now he's always kept his pack of scavengers away from the main roads. Sure, they were territorial, but hostile? Not until now.\n\nBluescale has to be responsible for this sudden escalation. Find him and take him down.", objectives = "Slay Bluescale.", progress = "Be careful, <class>. Bluescale is tougher than your average Tarasek scavenger.", completion = "With Bluescale taken care of, I doubt we will have to deal with any organized tarasek encroachment any time soon.\n\nNow all that's left is to deal with the poison." }
WordHunterWoW_QuestEN[66458] = { title = "Legacy of Tyr: Secrets of the Past", description = "To stop Raszageth from freeing the other Incarnates, the power of the Aspects must be restored.\n\nInconveniently, the Titans are rather preoccupied and Keeper Tyr is long dead.\n\nQueen Alexstrasza has suggested a plan. In the depths of the Badlands lies a Titan facility called Uldaman. Apparently allies of Tyr may have hidden a disc of his memories there.\n \nWord is that the place has been overrun by troggs. Gather your allies, head to Uldaman, and seize the disc in the name of the Dragon Queen!", objectives = "Enter Uldaman: Legacy of Tyr in the Badlands and recover the disc.", progress = "Did you retrieve the disc?", completion = "Infinite dragons? Their kind always has some kind of plan.\n\nI will inform the Dragon Queen that she will have to find some other way to restore the power of the Aspects." }
WordHunterWoW_QuestEN[66459] = { title = "The Field of Ferocity: Terror of the Swamp!", description = "Welcome one and all to the Fields of Ferocity!\n \nWhile this sparring field is used for traditional events, the centaurs have graciously allowed me to set up shop off-season. They say it tests their strength and brings them honor.\n \nYou want to take home the title of champion? Well then, let me know when you're ready and you can take on the introductory competition.", objectives = "Defeat Maneet.", progress = "Speak with Gurgthock to start the round, then defeat the first competitor of the Field of Ferocity.", completion = "You've done well, for the first ladder. But we're just warming up. Speak with Gurgthock again when you're ready to move on to the second round." }
WordHunterWoW_QuestEN[66460] = { title = "The Field of Ferocity: Lord of Decay!", description = "I tried to get one of those nasty gnolls for this gauntlet. Unfortunately, none of my associates know how to speak with them.\n \nWe did manage to catch one of their freaky creations though. That should serve as a good opponent! Let me know when you want to start the second round!", objectives = "Defeat Nightrot.", progress = "Well, what are you waiting for?  Speak with Gurgthock to start the round, then defeat the second competitor of the Field of Ferocity.", completion = "I'm glad you dealt with that as quickly as you did. The stench was starting to reach the podium here." }
WordHunterWoW_QuestEN[66461] = { title = "The Field of Ferocity: Foe from the Volcano!", description = "One of the first volunteers for this competition hails from the Waking Shores. A big djaradin fellow, not quite as angry as his kin.\n \nHe just seems to enjoy the sport of fighting. Hey, that works for me.", objectives = "Defeat Ceeqa the Peacetaker.", progress = "Ceega has a famous entrance. You need to speak with Gurgthock to start the round, then defeat the third competitor of the Field of Ferocity.", completion = "What a show! I could feel sparks flying from here!" }
WordHunterWoW_QuestEN[66462] = { title = "The Field of Ferocity: Lost in the Dream!", description = "You know, for it being the Dragon Isles, I haven't seen too many dragons. We did get a duo of dragonkin that requested to be signed up for this competition together though.\n \nThey seem plenty eager to prove themselves though, so good luck!", objectives = "Defeat Sherath and Taresh.", progress = "You need to speak with Gurgthock to start the round, then defeat the fourth competitors of the Field of Ferocity.", completion = "... Wuzzat? Is the fight over? I think I fell asleep in the middle of it for some reason.\n\nI'm guessing you won if you're standing in front of me?" }
WordHunterWoW_QuestEN[66463] = { title = "The Field of Ferocity: Elemental Revenge Round!", description = "We're changing the roster at the last minute. Some Primalist bigwig wants to join in on the competition to face you. And I'm not saying no to an angry elemental dragon.\n \nI'm sure you'll be fine. If not, then... well, you signed the waiver, right?", objectives = "Defeat the Primalist champion.", progress = "You need to speak with Gurgthock to start the round, then defeat the fifth competitor of the Field of Ferocity.", completion = "I now understand the rumors I have heard about you and your crew. You have gotten further than I would have ever expected." }
WordHunterWoW_QuestEN[66464] = { title = "The Field of Ferocity: Master of the Hunt!", description = "This is it. You and your pals have hit the big time. A match against the champ, Huntmaster Amaa herself. Don't pat yourself on the back just yet. She's ruthless. It was nice knowing you.\n \nAfter she kills you, can I have your stuff?", objectives = "Defeat Huntmaster Amaa.", progress = "You need to speak with Gurgthock to start the round, then defeat the final competitor of the Field of Ferocity. Good luck.", completion = "You are quite the impressive and fearsome combatant. The centaurs are in awe of you. Gurgthock is fuming for not betting his farm on you instead of Amaa. You win the grand prize." }
WordHunterWoW_QuestEN[66465] = { title = "Cache and Release", description = "Even with their leader gone, the Tarasek are unlikely to stop using their poison-tipped spears simply because we ask them nicely. I cannot risk even one of these weapons being used on an unsuspecting traveler.\n\nThey will all need to be destroyed. If you did not see any in the caches by the pools, then the Embertooth are likely keeping their spears closer to the source. \n\nNo one else will get hurt because of my carelessness. Enter the cave and destroy any weapon caches that you find.", objectives = "Destroy 8 Poisoned Spear Stashes.", completion = "The Passage will be a far safer place without those poisoned spears to worry about.\n\nYou have kept a lot of people safe with your deeds this day, <name>. The Waywatchers - and I - owe you a great debt." }
WordHunterWoW_QuestEN[66466] = { title = "The Essence of Fury", description = "Journal entry: 9\n\nI swear I better not get stuck with these two as my assistants again, they can barely pull this wagon! We're supposed to arrive at pools of supposedly enchanted waters, where water congeals into swirling essence that seems to have attracted a swarm of elementals.\n\nIf we can examine samples of this congealing essence before it becomes completely concentrated we might be able to figure out how to stop the elementals from drawing power here. IF WE EVER ARRIVE!", objectives = "" }
WordHunterWoW_QuestEN[66467] = { title = "Art Imitates Life", description = "The last time I was in this cave, I sketched a massive flower that dripped a vile, viscous sap. It's one of my best drawings, I couldn't forget it if I tried.\n\nThat sap is what's stuck to these tarasek spears, I'm sure of it. They must have started harvesting it to envenom their weapons.\n\nThe plant is beautiful; it will be a shame to kill it. Still, we can't let the tarasek keep harvesting it. {name}, please cull the plant and put a stop to this whole mess.", objectives = "Slay the Greater Venomsprout.", completion = "Thank you, <name>. The Embertooth's venom harvesting days should be behind them now that they have been deprived of their source.\n\nI realize now that I don't have to be a Waywatcher to make a difference in the world. I am going to resign my post and commit myself to my art. Hopefully some day I will be able to depict the most beautiful vistas in the Dragon Isles, for all the world to see.\n\nI just hope my sister understands." }
WordHunterWoW_QuestEN[66468] = { title = "What Once Was Ours", description = "<Thadezus scoffs at your approach.>\n\nAre you a mortal of action, or are you going to get out of our way, {class}?\n\nI have lost many good soldiers to those Primalists up ahead.\n\nWe have an idea of what they are planning, but we must first rout the enemy and rescue those serving under me.", objectives = "Defeat the Primalists occupying the Gelikyr Overlook.", progress = "Have you stopped the Primalists, or do I need to do this myself?", completion = "<Sharnax stares down at you.>\n\nHmm... It appears you are someone with more skill than the commander had originally assumed.\n\nThere is more to be done before the day is over." }
WordHunterWoW_QuestEN[66470] = { title = "The Forward Push", description = "<Sharnax scratches her chin.>\n\nThe commander was right. The Primalists are calling reinforcements from the elemental planes.\n\n<Sharnax smirks.>\n\nIt would be a shame if something happened to their gateways, {class}.", objectives = "Obtain Misttouched, Earthen, and Iceforged gateway stones, and close the 3 elemental gateways.", progress = "We need to close those gateways.", completion = "Looks like you made it in one piece." }
WordHunterWoW_QuestEN[66471] = { title = "Prime Planning", description = "The commander ordered me to establish a forward base and dispatch any resistance. It wasn't until I did all the dispatching that I realized something.\n\n<Sharnax lets out a long sigh.>\n\nThe Primalists were talking about Tyrhold.\n\nUnless you are exceptionally skilled at interrogation, I need you to discover their plans.", objectives = "Collect 7 Primalist Orders from the nearby Primalists in the upper terrace of Gelikyr Overlook.", progress = "Do you have something we can show the commander?", completion = "This is just what we needed." }
WordHunterWoW_QuestEN[66472] = { title = "Primal List", description = "The gateways closed, the elementals slain, and the Primalists stopped... for now.\n\n<Sharnax laughs.>\n\nIs there anything we cannot do, {class}? I guess only time will tell.\n\nTake the plans back to the commander. I am certain he will be glad to see we have been successful.", objectives = "Deliver the Bundle of Primalist Orders to Commander Thadezus on the bridge at the Gelikyr Overlook.", progress = "<Thadezus stares at you.>\n\nWhat do you want, <class>?", completion = "<Thadezus pauses for an uncomfortable amount of time.>\n\nAllis and I had bets on if you would be successful, <class>\n\n I am glad that you were." }
WordHunterWoW_QuestEN[66473] = { title = "The Land Awakens", description = "The fiends in this cave were too much for me.\n\n<Sharnax lets out a labored cough.>\n\nI have seen what you can do.\n\nI need you to slay these elementals before they reach their full potential. We cannot allow the Primalists to take control of Tyrhold!", objectives = "Defeat the Primordial Wrath and Primordial Hail in the Gelikyr Overlook.", progress = "<Sharnax coughs.>\n\nIs it done?", completion = "Thank you for everything you have done for us, <class>." }
WordHunterWoW_QuestEN[66474] = { title = "The Other Scouts", description = "Journal entry: 10\n\nIdiots! Shortsmith and Stockson took off as soon as we arrived, their enthusiasm will be their death! We were sent here to study the elementals not play hide and seek.\n\nHow am I supposed to study these elementals without a decent distra... assistants?", objectives = "" }
WordHunterWoW_QuestEN[66477] = { title = "The Pond and the Fury", description = "Journal entry: 15\n\nThese waters are swarming with elementals drawing power from the swirling essences that gather here naturally. As much as I would love to see where this leads, the elementals pose a significant threat to the Expedition and get in my way of studying the source of this pools magic.\n\nIf only we could thin out their numbers but my two overly enthusiastic assistants have decided to get themselves trapped! How am I supposed to do everything on my own!", objectives = "" }
WordHunterWoW_QuestEN[66482] = { title = "Scout for Trophies: Terramaw", description = "[PH] Get rid of that annoying flying lizard!", objectives = "" }
WordHunterWoW_QuestEN[66484] = { title = "Know Your Enemy: Proto-Dragons", description = "The area is crawling with those powerful beasts! Conveniently. the Surveying Scope has allowed you to spot a few weak spot in their tough scale. You can also devise a few tricks to avoid their sharp claws and fangs.", objectives = "Hunt down a few Proto-Dragons around the Apex Canopy." }
WordHunterWoW_QuestEN[66488] = { title = "WANTED: Frigellus", description = "<The page's script glows with a soft blue light.>\n\nPreviously a cherished plaything of Malygos, the elemental Frigellus suffered from his master's neglect. \n\nWhile this once-happy settlement crumbled apace, the churlish and playful creature grew warped and twisted by the evils that plague this land.\n\nPlease see that it is safely neutralized.\n\nBring word of your success to Custodian Cynegos.", objectives = "Kill Frigellus near Camp Antonidas.", progress = "Return to Custodian Cynegos in Camp Antonidas.", completion = "Let us hope there aren't any more surprises trapped in that glacier." }
WordHunterWoW_QuestEN[66489] = { title = "Setting the Defense", description = "Custodian Cynegos and I were just discussing the impact the Primalist attack has had on the plans to assault the Cobalt Assembly, and I had an idea. \n\n<Celeste withdraws a wand from the folds of her robes.>\n\nTake my wand and empower their weapons!\n\nA little bit of fire should do the trick...", objectives = "Empower Azure Defenders in Camp Antonidas.", progress = "Have they been sufficiently enchanted?", completion = "Fantastic job! \n\nAfter repelling their attack on the camp, it's imperative that we keep the Primalists on the back foot. \n\nNow please give me my wand back." }
WordHunterWoW_QuestEN[66493] = { title = "Send It!", description = "<You hear muffled muttering coming from the other end of the portal.>\n\nHey! Hey you! \n\nI have some mail for our apprentices in the field: care packages, gifts, things they've ordered via magical courier... \n\nStandard fare, really.\n\nMind doing me a favor and handing them out?", objectives = "Throw packages to Kirin Tor Apprentices in Camp Antonidas.", progress = "How's your arm? \n\nDon't forget to stretch, or you might hurt yourself.", completion = "Well done! Don't worry... it's the courier's fault if a parcel wasn't marked \"fragile.\"" }
WordHunterWoW_QuestEN[66500] = { title = "Ways of Seeing", description = "We're not doing anything! We're not doing anything!\n\nHang on a minute...\n\nYou look like a pretty important {race}... Want in on a secret?\n\nTurns out there's magical art in these ruins. And we can see it!\n\n<Scrumpy proudly sticks out his chest.>\n\nI can show you how to see 'em too! Just... don't tell Noriko yet.", objectives = "Uncover ancient images in Camp Antonidas.", progress = "Noriko told us to stay out of trouble. Not sure how to do that to be honest.", completion = "Malygos and Sindragosa, huh? Never heard of 'em. Sounds like they were pretty in love though.\n\nI wonder who put these here?" }
WordHunterWoW_QuestEN[66503] = { title = "For The Love of Others", description = "Ah, I see my apprentices have roped you into their little games. \n\n<Noriko chuckles.>\n\nIt appears they--and you--have stumbled onto something. The purpose behind these ruins is slowly revealing itself to us, and there's more than faded images and song...\n\nSomething calls out from atop this tower.\n\nI see the intrigue in your eyes. Go. You have my permission. \n\nSee what you can see.", objectives = "Investigate the top of the Ruined Tower in Camp Antonidas.", progress = "Remembrance is a gift--and a burden.", completion = "To watch your world crumble into ruin and think it lost forever...\n\nI cannot imagine.\n\nWe must remember." }
WordHunterWoW_QuestEN[66504] = { title = "A Shard of Crystalized Mana", description = "<The small blue crystal vibrates lightly when touched, then produces a low tune that sounds like a distant song. You can hear the words echoing like a soft melody in your head.>\n\nLathos may find it interesting.", objectives = "Take the crystal to Lathos." }
WordHunterWoW_QuestEN[66507] = { title = "A Winter Veil Gift", description = "", objectives = "A small tag on this present reads:\n\nHappy holidays, <name>!" }
WordHunterWoW_QuestEN[66508] = { title = "A Gently Shaken Gift", description = "", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special <race> <class>." }
WordHunterWoW_QuestEN[66509] = { title = "Paranoid 1", description = "Agura sent me out here to pick FLOWERS for my ANXIETY but there are CREATURES and I'm terrified.", objectives = "Agura sent me out here to pick FLOWERS for my ANXIETY but there are CREATURES and I'm terrified.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[66510] = { title = "Paranoid 2", description = "Getting out here was so scary. Now I have to go BACK? Please come with me.", objectives = "" }
WordHunterWoW_QuestEN[66511] = { title = "Renowned with the Iskaara Tuskarr", description = "You continue to show us that you are an integral member of our community. \n\nTo honor that bond seek me out in Iskaara as I have prepared a pack of supplies to aid you.", objectives = "Speak with Murik in Iskaara.", completion = "Again, we can only thank you so much and these supplies do not do that thank you justice, but please know your aid means a great deal to us!" }
WordHunterWoW_QuestEN[66513] = { title = "Ground Leave", description = "Perhaps we should get an idea of this city, if it is to be our new home. A scouting mission, if you will.\n\nGo, see what this place has to offer. I will follow Wrathion and attempt to help in any way I can.\n\nTry not to upset the locals any more than you must, though. I doubt many of them are used to seeing dragons walk among them.\n\nMeet up with us once you've gotten the lay of the land.", objectives = "Explore Stormwind.", completion = "The Alliance has granted us asylum here in Stormwind.\n\nIt sounds like quite an interesting place." }
WordHunterWoW_QuestEN[66516] = { title = "Mundane Gems, I Think Not!", description = "It's such a waste. The djaradin of this land use powerful gems as mundane decorations. Mere jewelry! Gems have so many uses: telescopes, mirrors, focusing pointers, not to mention the myriad magical properties they possess.\n\nWe must rectify this situation, explorer. Relieve the djaradin of their gems, and bring them back to me. I'll make sure they're put to better use! Be careful though--the djaradin are fierce warriors.", objectives = "Gather 25 'Mundane' Gems from the djaradin of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition.", progress = "Were you able to get the gems?", completion = "There's so much potential in these gems, even Lugrah wouldn't know what to do with them all!\n\nLugrah is the jewelcrafting representative to the Artisan Consortium. Let me share some of the notes she sent me before I left. They're sure to help you with your jewelcrafting studies here in the Dragon Isles." }
WordHunterWoW_QuestEN[66517] = { title = "A New Source of Weapons", description = "These Sundered Flame pose a great threat to our borders. Their weapons are concerning. Gather what you can of their weapons--we can study them for any weaknesses, and even use them for our own defenses.\n\nI have faith in you, outsider. If you perform this task for us, I will teach you some of our own blacksmithing arts.", objectives = "Gather 25 Intact Dracthyr Weapons from the Sundered Flame of the Dragon Isles for Dhurrel of the Maruuk Centaurs.", progress = "What were you able to secure?", completion = "Thank you, outsider. This should help greatly.\n\nAs promised, here is a scroll I had our blacksmiths prepare for you. May the knowledge grant you swift learning." }
WordHunterWoW_QuestEN[66523] = { title = "Tending the Forge", description = "If you're looking for an instructor, I'm sorry to say I... Ah, you're not an apprentice! My apologies. Allow me to introduce myself. \n\nI am Custodian Vernagos, one of the caretakers of these ruins. More specifically, the task of restoring this workspace to its former glory has fallen upon my very tired shoulders. \n\nWould you be able to lend a hand? All the reagents I need are nearby: ice elemental cores, embercones, hornswog leather...\n\nFairly standard, easily gathered stuff. What say you?", objectives = "Gather reagents for the forge by collecting hornswog hides, dormant embercones, and calving cores around Camp Antonidas.", progress = "Fresh air and magical relics. What more could one ask for? Ha!", completion = "Thank you, <name>. The embercones will burn hot. The elemental cores will temper the heat. And this leather... is fairly disgusting. But the bellows they produce will more than suffice!\n\nNow all I need is time." }
WordHunterWoW_QuestEN[66524] = { title = "Amateur Protography", description = "So, you want to be a seasoned cataloger like me? You've come to the right place! \n\nThe Wild Preserve is teeming with knowledge waiting to be found and filed! And how do I do that you ask? Why, with my handy Catalog-izer 3000 Dragon Isles edition--now with improved motion capture!\n\nTo gain experience, photograph a proto-dragon egg, a whelp learning to fly, and a hunting proto-drake. Meet me at the ancient, proto-dragon skeleton west of here, and I'll assess your photos.", objectives = "Take pictures of proto-dragons.", completion = "These are wonderful! Just wonderful! Say, have you done this before?" }
WordHunterWoW_QuestEN[66525] = { title = "Competitive Protography", description = "Well, now that you've cut your teeth on some starter shots, how about we move onto something a little spicier?\n\nI spotted a gorgeous proto-drake flying around the area behind us. Beautiful horns, scales crackling with electricity... Probably the work of the Primalists, no doubt, but art is art!\n\nSee if you can get a picture of the proto-drake and some of its eggs. You might have to climb up a bit to get a good shot!", objectives = "Photograph an Infused Proto-Dragon Egg and an Infused Proto-Drake.", progress = "If you get in a fight with the Primalists, make sure you keep that camera pristine! It's my only prototype!", completion = "Oh, look at that! The colors came through beautifully. Looks like you're a pretty good cataloger already!" }
WordHunterWoW_QuestEN[66526] = { title = "Preserving the Wilds", description = "The Wild Preserve is one of the few areas where proto-dragons thrive. But the Primalists are disrupting their nesting grounds by sending sorties to capture and experiment on proto-whelps and proto-drakes.\n\nShow them no mercy. Locate these Primalist poachers, wipe them out, and free their captives. The proto-dragon species depends on it.", objectives = "Free 5 Captured Proto-Whelps or Captured Proto-Drakes.", progress = "If we want these creatures to survive, we must protect them.", completion = "Good. The Primalists remain a threat, but these dragons enjoy their freedom once again." }
WordHunterWoW_QuestEN[66527] = { title = "Professional Protography", description = "I haven't trained a photographer as good as you... that's still alive, that is. It's a dangerous profession.\n\nSpeaking of dangerous, our final target is a large proto-dragon we believe may be one of the next apex predators in this preserve. Let's get up close and personal and take a picture!", objectives = "Use the Vertical Enhancement Apparatus and photograph the Slumbering Proto-Dragon.", progress = "Don't worry, <name>. You're much more competent than the last person I sent up there.", completion = "So totally unrelated, but you didn't see another camera up there, did you?\n\nYou know what? Forget I said anything." }
WordHunterWoW_QuestEN[66528] = { title = "King Without a Crown", description = "This ancient proto-dragon must have been a glorious creature when it was alive--perhaps the largest the Wild Preserve has ever seen.\n\nBut it wasn't enough. Observe the skeleton more closely, so we may learn the story of its final moments.", objectives = "Investigate the Proto-Dragon Skeleton.", progress = "An incredible specimen--and a reminder of our origins.", completion = "So, a fight to the death with something just as strong? I wonder if it was protecting the preserve from invaders?\n\nThank you, <name>. It's good to remember the sacrifices of those that have come before us." }
WordHunterWoW_QuestEN[66529] = { title = "A Thousand Words", description = "With all that we've learned here, I can't imagine moving on without a memento. \n\nWould you be kind enough to take my picture next to the proto-dragon fossils?", objectives = "Photograph Dervishian near the Proto-Dragon Skeleton.", progress = "It should only take a moment.", completion = "Someday, I hope to fight for my people with the same bravery as this proto-dragon in its final moments.\n\nThanks again, <name>." }
WordHunterWoW_QuestEN[66534] = { title = "Ground Leave", description = "It seems like our arrival was noticed after all. Maybe there's hope for these people yet.\n\nI'll follow up with Ebyssian and the Horde leadership and try to smooth this out. You're on recon.\n\nSee what this place has to offer. We may be here for a while, after all.\n\nCome find us once you're finished. Hopefully we'll have all the boring bits sorted out by then.", objectives = "Explore Orgrimmar.", completion = "But how was the food?" }
WordHunterWoW_QuestEN[66546] = { title = "Retrieve the Discs", description = "The discs in here represent the sum of this facility's knowledge. We need to retrieve them!\n\nI'll bring the barrier down with this console. It'll be on ye to retrieve the discs.", objectives = "Retrieve the three discs.", progress = "Can ye imagine the knowledge that these discs hold?", completion = "I knew we could count on ye!" }
WordHunterWoW_QuestEN[66547] = { title = "It Belongs in a Museum... Eventually", description = "Waves of titan security, escaped proto-dragons, keys that turn you into constructs... I'll just say it.\n\nI've never had so much fun in my LIFE!\n\nAlthough Naleidea will probably say this is where the real fun begins. We're sitting on a trove of confidential titan data, thanks to the effort ye put in!\n \nWhen ye can, come meet us at camp and we'll compare notes.", objectives = "Meet Toddy back at the Dragonscale Expedition camp.", progress = "Thanks again for a once-in-a-lifetime experience!", completion = "Our leads have dried up for now... at least until we can parse more information from these discs.\n\nUntil then, stay observant and follow the clues. You never know where the next adventure will come from!" }
WordHunterWoW_QuestEN[66549] = { title = "Waking Shores Rally", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66551] = { title = "The Terrible Three", description = "", objectives = "Defeat Haniko in a Pet Battle" }
WordHunterWoW_QuestEN[66553] = { title = "Hollow Up", description = "The Winterpelt are a special case among the furbolgs. \n\nI'd categorize 'em as a wee bit \"isolationist.\" They are ghosts in the hollow, their pelts blendin' in with tha snow. \n\nUsedta keep to themselves, but now they're outright aggressive. They attacked our camp with nae provocation!\n\nSomethin' must be wrong to drive 'em to it. I can't ask 'em what happened--yet--but maybe ye can find some clues in their village?", objectives = "Uncover 6 clues in Winterpelt Hollow.", completion = "So, what did ya find?" }
WordHunterWoW_QuestEN[66554] = { title = "Aggressive Self-Defense", description = "With the Winterpelt all in a tizzy, I don't imagine they'll appreciate ya poking around up there. \n\nDon't be afraid to defend yourself if they start somethin'. A firm reminder that ya mean business might knock some sense back into 'em.\n\nTry not to kill anyone though, will ya? I know how ya adventurin' types can get.", objectives = "Defeat 6 Winterpelt furbolgs.", completion = "Hopefully ye didn't go too hard on 'em." }
WordHunterWoW_QuestEN[66555] = { title = "Bear With Me", description = "Aye, sounds like a right mess up there--like a storm blew through and wrecked the whole place. I can see why they'd be up in arms, but why attack us?\n\nThis would be a lot easier if we could just talk it out, but the Winterpelt are famously tight-lipped and don't seem to speak any of the common branches of Furbolg-ish. Furbolgian? Eh, ye know what I mean.\n\nI don't suppose ya happened to have a nice chat with any of 'em while ye were checking in on them, did ye?", objectives = "Assist Sonova's translation.", progress = "Are ye even listenin'?", completion = "Now to translate this mess..." }
WordHunterWoW_QuestEN[66556] = { title = "Ice Cave Ya Got There", description = "Well, yer accent is atrocious, and ten-thousand years o' isolation an' linguistic drift hasn't done us any favors, but I think I got a rough impression at least.\n\nThe common thread in what they were tryin' to say was somethin' aboot a \"bad cave wind\" or an \"evil storm cave.\" That, or their laundry was too Thursday?\n\nLook, this isn't like learnin' Gnomish; there're goin' to be some hiccups. I'm pretty sure aboot the cave though, so let's start there.", objectives = "Investigate the cave.", progress = "That's the best I got. Ye try translatin' this stuff if ye don't like it.", completion = "I told ye I had the cave part right. Now we can see about establishin' some proper diplomatic relations." }
WordHunterWoW_QuestEN[66557] = { title = "Academic Acquaintances", description = "Aye, this Winterpelt variation on furbolg is provin' to be a tough nut to crack even for me.\n\nI've got some colleagues down in Camp Nowhere who might be able to help. I hear there are other furbolg tribes in the area, and comparin' notes on those dialects might give us somethin' to go off of.", objectives = "Find another expert in furbolg languages in Camp Nowhere.", completion = "I speak my own tongue, yes, but there is something I need your help with first." }
WordHunterWoW_QuestEN[66558] = { title = "Rowie", description = "You were the one that came back with the others from Brackenhide, weren't you? Then you probably know what happened to Kaqiata...\n\nHer son, Rowie, has been distraught ever since Brena and the others returned without her. I'll stay here in case he comes back, but could you look for him? \n\nI think he ran off towards the ice cave to the east. He said something about trying to fight the yeti in there!", objectives = "Find Rowie.", progress = "I have to prove myself!", completion = "Thanks for helping me. You're nice." }
WordHunterWoW_QuestEN[66559] = { title = "Back To Camp", description = "I saw Mordigan run out of there like a dwarf possessed. I'll go chase him down and make sure he gets back to the others in one piece.\n\nIf you hug the cliff and jump down the waterfalls, you should be able to avoid stirring up any more of the gorlocs. \n\nSee you back at camp.", objectives = "Return to Examiner Rowe in Whaler's Nook.", completion = "It appears you've managed to return our dwarf. And in a single piece, no less. On behalf of both our team and the Dragonscale Expedition, I thank you. \n\nWe'll get Mordigan some fluids, then start packing up. \n\nThere's nothing in these hills save blood and salt." }
WordHunterWoW_QuestEN[66575] = { title = "Item as Questgiver: Vial", description = "<This strange vial nestled amongst the odds and ends of the Tarasek stash seems to be filled with a viscous, bubbling fluid.>\n\n< It would be wise to show this to Alvi.>", objectives = "Turn in the item to Waywatcher Alvi.<This strange vial nestled amongst the odds and ends of the Tarasek stash seems to be filled with a viscous, bubbling fluid.>\n\n< It would be wise to show this to Alvi.>You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[66577] = { title = "Aspectral Invitation", description = "Ah, {name}. Impeccable timing!\n\nI just met with Lord Commander Turalyon and his allies, and they have accepted the Aspects' invitation to the Dragon Isles. \n\nYou will be coming along, of course? It wouldn't be the same without you!\n\nI imagine you have noticed some unfamiliar faces gathered here. The ones with the wings are called dracthyr. They have only known me a short time, but they are already great admirers.\n\nAh, but where are my manners? We should have a chat.", objectives = "Speak with Wrathion to learn of the Council's meeting.", completion = "I cannot wait to see the Dragon Isles with you, <name>!\n\nNow then, I believe that diminutive ally of yours said something about putting together an expedition." }
WordHunterWoW_QuestEN[66578] = { title = "A > B Reward Test (Low Health)", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[66579] = { title = "Sounds of Healing", description = "<You hear a soothing sound emanating from the disc as it hums softly.\n\nOlea Manu might know more about this.>", objectives = "Bring the Resonating Disc to Olea Manu at Faith's Repose.\n\nProvided item:", completion = "The Jailer is no more. What you bring is proof--Zereth Mortis is beginning to heal itself! You may find new tools born of that healing. Tools that resonate strongly with the Cyphers. With them, you can rid us of the remaining Mawsworn." }
WordHunterWoW_QuestEN[66582] = { title = "Power Procurement", description = "In normal circumstances, the capture of energy is not problematic. However, the energy we require is massive and unstable. This enchanted vessel should provide a safe means of transport.\n\nThere is a region to the southwest filled with energy-laden creatures. The anomalous energy within these creatures is powerful, but unstable.\n\nCapture their energy and return it to me. Then we may embark on the remainder of this journey together.", objectives = "Gather energy within the vessel for Warpcaster Delandra at Camp Antonidas.", progress = "Have you collected what we discussed?", completion = "Oh my. The warmth within the vessel is fascinating." }
WordHunterWoW_QuestEN[66584] = { title = "Additional Waygate Energy", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[66586] = { title = "Legacy of Tyr: Secrets of the Past", description = "To stop Raszageth from freeing the other Incarnates, the Aspects' power must be restored.\n\nBut this will not be an easy task. The Titans are silent and Keeper Tyr is long dead.\n\nQueen Alexstrasza has devised a plan. In the Badlands lies a Titan facility called Uldaman. She believes Tyr's companions hid a disc of his memories inside its depths.\n \nTake your allies to Uldaman and find the disc for the Dragon Queen. Let us hope Tyr's knowledge can be used to re-empower the Aspects.", objectives = "Enter Uldaman in Badlands. Discover the cause of the disturbances.", progress = "Has the exploration been a success?", completion = "Infinite dragons? Their kind always has been troublesome.\n\nI will inform the Dragon Queen that she must find another way to restore the power of the Aspects." }
WordHunterWoW_QuestEN[66588] = { title = "Swog the Elder", description = "", objectives = "Defeat Swog in a Pet Battle." }
WordHunterWoW_QuestEN[66589] = { title = "Expeditionary Coordination", description = "The name's Toddy. I'll be headin' up our band of cheery adventurers under the banner of the Dragonscale Expedition. We'll get into the details later. For now, let's focus on gatherin' up our crew.\n\nEvery expedition worth its salt has a variety of folk. We'll be needin' scholars, artisans, and of course explorers.\n\nWell? What're you standin' here for? Assemble that crew!", objectives = "Recruit explorers, artisans, and scholars throughout Stormwind for the expedition to the Dragon Isles.", progress = "Everyone packed and ready?", completion = "That was fast!\n\nEager to get to the Dragon Isles, eh? Me too!" }
WordHunterWoW_QuestEN[66595] = { title = "Dormant Discovery", description = "<Nevermind how this curious parchment ended up in your bags. What's important are the contents of the message.>\n\nMembers of the Dragonscale Expedition:\n\nYour assistance is required! Report to the Rubyscale Outpost at once!\n\n<Before the signature can be read, the magical lettering inscribed on the note dissipates into a cloud of white and blue-tinted dust, leaving behind an empty page and a deliciously flowery scent in the air.>", objectives = "Deliver the message to Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores.", completion = "Message? What message?\n\nWhat do ye mean it vanished mysteriously?\n\nWell, no matter. We've got much to discuss." }
WordHunterWoW_QuestEN[66596] = { title = "Whispers on the Winds", description = "Hello, {name}. It's been a while, and I wish we had more time to catch up.\n\nBut you see, I've just had a rather enlightening... no, make that foreboding... yes, a foreboding conversation with an old friend.\n\nSometimes a revelation can be both, after all.\n\nI really must tell you of what I've learned.", objectives = "Speak with Archmage Khadgar in Stormwind.", progress = "Our journey begins with you.", completion = "Your reaction is understandable. I dare say I felt the same." }
WordHunterWoW_QuestEN[66597] = { title = "This Old Stone", description = "This stone behind me is just one piece of, what do ye call it--ancient technology--we stumbled upon here in the Isles.\n\nBut, we're not entirely sure what they are just yet. Baffling, really.\n\nWe've sent word to some friends to see if they can help. In the meantime, perhaps ye can figure out how tae use it?", objectives = "Inspect the Etched Ancient Monolith.", progress = "So. Is there more to it, or is it really just a heaping hunk o' stone?", completion = "A what symbol!? That can't be right...\n\n<Thaelin scratches his beard.>\n\nThere's only one way to find out." }
WordHunterWoW_QuestEN[66598] = { title = "Nightborne Know-How", description = "Ancient symbols aren't really me thing. However...\n\n<Thaelin searches through his belongings, eventually pulling out a map. At the top of the parchment appears the name Antonidas, scribbled in large, sloppy letters.>\n\nAh hah! Here it is!\n\nBit of a trek, but a few of those old magic users can be found... here. \n\n<Pointing to a spot on the map.>\n\nMaybe they have somethin' tae offer.", objectives = "Locate Warpcaster Delandra at Camp Antonidas in The Azure Span.", completion = "Well traveled, I see. These symbols you speak of are quite mysterious, as well as old.\n\nSince you seem interested enough to travel all the way out here to find me, the least I can do is offer some guidance." }
WordHunterWoW_QuestEN[66611] = { title = "Clearing the Skies", description = "Can you hear that? Bugs! All around. Some of them are getting pretty big.\n\nWhy don't you and your gliding friend use the thermal behind me and do something about it?", objectives = "Kill 50 insects." }
WordHunterWoW_QuestEN[66612] = { title = "Crabtender's Quandry", description = "The crabs are in danger!\n\nThis particular bunch has been through a rough season. Their previous habitat was ransacked by the Primalists, and then I led them to this area only for gorlocs to invade!\n\nI thought they would be safe here, but the gorlocs only nurture aggression in their crabs, leading them to an early demise!\n\nPlease, defeat some of the gorlocs so the crabs can escape!", objectives = "Kill 12 gorlocs in Cliffdrip Camp.", progress = "These crabs deserve better than to serve a gorloc!", completion = "Aspect's grace shine down on you, <name>! You saved my precious crabs! I will watch them more closely this time. No gorloc will overtake my charges again!" }
WordHunterWoW_QuestEN[66614] = { title = "Valinor, the Light of Eons", description = "", objectives = "" }
WordHunterWoW_QuestEN[66615] = { title = "Nurgash Muckformed", description = "", objectives = "" }
WordHunterWoW_QuestEN[66616] = { title = "Oranomonos the Everbranching", description = "", objectives = "" }
WordHunterWoW_QuestEN[66617] = { title = "Mortanis", description = "", objectives = "" }
WordHunterWoW_QuestEN[66618] = { title = "Mor'geth", description = "", objectives = "" }
WordHunterWoW_QuestEN[66619] = { title = "Antros", description = "", objectives = "" }
WordHunterWoW_QuestEN[66620] = { title = "Emerald Summons", description = "Merithra, the current leader of the green dragons, wishes for you to meet her in the Emerald Gardens.\n\nDrakonid emissaries from the azure flight have come to learn about the gardens. Things have not always been peaceful with the blue dragons, so it is important to her that relations are kept cordial and positive.\n\nShe is on her perch above the Shady Sanctuary in the Emerald Gardens, at Merithra's Watch.", objectives = "Speak to Merithra at Merithra's Watch in the Ohn'ahran Plains.", completion = "Thank you for coming, <name>. My guests are eager to see the Emerald Gardens, and I am pleased to host them.\n\nShall we get started?" }
WordHunterWoW_QuestEN[66622] = { title = "Wayward Tools", description = "This is terrible! My *hic* tools seem to have run off when I wasn't looking. I can't *hic* stand the thought of them all alone out there, no doubt scared out of their minds!\n\nWould you round them up for me? Just be patient and *hic* try to soothe their nerves and I'm sure they'll warm right up to you!", objectives = "Rescue 6 Wayward Tools.", progress = "Did you *hic* find them?", completion = "Thank you, <name>! I'll *hic* always remember your heroism!" }
WordHunterWoW_QuestEN[66633] = { title = "Make a Statement", description = "These djaradin believe the black dragonflight is finished. They don't fear or respect Wrathion's authority here.\n\nWe need a statement to remind them that the obsidian flight has returned, and that we are stronger than ever.\n\nSlay the djaradin and mark each corpse so they don't forget who rules here.", objectives = "Plant a black dragon banner into the corpses of 12 djaradin.", completion = "Masterfully done, <name>. That's how you send a message." }
WordHunterWoW_QuestEN[66635] = { title = "Reunited, Once Again", description = "That should be enough. I can sense the others just on the outside of the grove, ready to enter the Dream.\n\nWhen you're ready, speak to me and I will break the ice walls and bring down the dome. I hope that my changes will not dishearten the flight. \n\nWe will not be done, but we will be all together again.", objectives = "Speak with Ysera to lower the barrier.", completion = "I cannot believe it. All that I could have hoped for... \n\nShe is here.\n\nBut I can tell that she's changed. I do not know what this means, and I fear we do not have much time to ponder it. We must go after Rymek." }
WordHunterWoW_QuestEN[66636] = { title = "The Other Side", description = "We've finally figured out the placement of the third stone--and ye get to do the honors! I've affixed the stone to what's left of the watcher's staff. Just climb the scaffolding there, hold it up, and watch the show!", objectives = "Open the door with the watcher staff.", progress = "When I get back tae Stormwind, my name is going into the book beside the greatest explorers of our time. \n\nMove over Brann, Toddy's here to stay!", completion = "There's so much to see, and we're just getting started!" }
WordHunterWoW_QuestEN[66646] = { title = "Quelling Causalities", description = "The Infinite has forced the energies of time to aggression. This is not good.\n\nPlease slay any time elementals you encounter while assisting Ambassador Chronormu. I will remain here and help her hold Eternus in place.", objectives = "Kill Time Elementals.", progress = "Did any of them escape to the past? I wonder if we would realize if they did? Hmmm.", completion = "Excellent work! Usually I am against killing time, but today is an exception." }
WordHunterWoW_QuestEN[66647] = { title = "Elemental Unfocus", description = "Kalecgos and I are under heavy fire in the skies above the mountain. The Primalists are unrelenting and their army endless.\n\nSoon, Kalecgos and I may be overrun by their forces.\n\nBut I have a plan.\n\nAt the base of the mountain is a disturbed orc named Ruvin Stonegrinder. The Kirin Tor fought her numerous times.\n\nShe holds a device that can absorb and redirect elemental energies. \n\nTake it from her, then meet me further in.", objectives = "Recover the Elemental Focus.", progress = "The Elemental Focus should prove useful if you can recover it.", completion = "This is it! Hold onto it... you'll need it for what's next." }
WordHunterWoW_QuestEN[66648] = { title = "Crossing Fate", description = "<Reality spins around you. Your memories of this place become obscured, and shift intensely with each passing moment. Something has changed.>\n\n<You are certain that for all its similarities, this is not the place you once knew. Not exactly.>\n\n<Regardless, the path ahead beckons. Neither deception nor distortion will delay your destiny.>", objectives = "Defeat 30 different Fated raid bosses." }
WordHunterWoW_QuestEN[66649] = { title = "Turning the Wheel", description = "<Through your many trials you feel the power inside you growing. Whatever the source of these anomalies, they now bring you comfort instead of confusion.>\n\n<Dive once more into uncertainty, strive against the darkness, and grasp Fate with both hands.>", objectives = "Defeat 15 different Fated raid bosses." }
WordHunterWoW_QuestEN[66650] = { title = "Fate's Finale", description = "<You are calm. The nature of this experience remains unknown, but it is no longer unfamiliar. Your now possess mastery over these ordeals with clarity as your ultimate reward.>\n\n<With clear mind and steady hand you stride forth one last time. Create your own destiny, and watch it unfold under your very feet.>", objectives = "Defeat 5 different Fated raid bosses." }
WordHunterWoW_QuestEN[66651] = { title = "Up to No-khud", description = "The Nokhud and Ukhel clans have overtaken the Eternal Kurgans. Their purpose can only be malign. Our most esteemed ancestors are buried there.\n\nI sent Initiate Zorig to investigate. He still has not returned.\n\nHe is capable, but lacking in confidence. Please help him put a stop to their foul activities!", objectives = "Meet Initiate Zorig at the Eternal Kurgans.", completion = "Clan Ukhel dishonors itself with dark magic. Now they have moved into the kurgans with their Nokhud allies. Neither clan should be here! I've been watching from here, where I'm safely out of sight." }
WordHunterWoW_QuestEN[66652] = { title = "Return to Mender", description = "I can't see what they're doing from here, but I fear they're desecrating the kurgans.\n\nPlease go to the nearest tomb, and see if you can stop the ritual they're performing. \n\nAnd if you find anything that may tell us their purpose here, please bring it back to me.", objectives = "Investigate the Ukhel ritual at the nearby mound.", progress = "Did you stop the ritual? Any clues as to what it was about?", completion = "This spear... it belonged to my mother, Cathan. She was a great hunter. When she got sick, I... I couldn't save her.\n\nLike all great Maruuk centaur, she was buried with her weapon. But this means the Ukhel are using these weapons to raise spirits and bind them to their service - including my mother!" }
WordHunterWoW_QuestEN[66654] = { title = "Desecrator Annihilator", description = "My mother was a hero. She deserves peace and rest, not this... enslavement! None of our heroes do.\n\nThey must pay for this. And our ancestors must rest once more with their weapons, with honor. Take the weapons back from those desecrators!", objectives = "Kill Nokhud Desecrators and Ukhel Gravestirrers, and recover the ancestral weapons they have taken.", progress = "Did you get the weapons back from those graverobbers?", completion = "This is a good start. I can use these weapons to free their owners... I hope." }
WordHunterWoW_QuestEN[66655] = { title = "Reagents of De-Necromancy", description = "I fear the spirits will be unable to find their tombs, even if we release them from the Ukhel's grip.\n\nThe Ukhel are also raising the ancestors' animal companions who guided and protected them in life.\n\nBring me the skulls of those animals, and the sacred soil disturbed by these enemies. Combined, these reagents should help the ancestors find peace.", objectives = "Gather 4 Intact Skulls from risen companions and 6 Clumps of Sacred Soil.", progress = "Do you have the reagents? We must free the ancestors before Clan Ukhel takes them away from the Kurgans.", completion = "Perfect! I should be able to use these to release them from the Ukhel. Then they can return to the rest they deserve." }
WordHunterWoW_QuestEN[66656] = { title = "Definitely Eternal Slumber", description = "The ancestors are gripped by this dark magic. They will fight before they follow. The Ukhel raised our fiercest warriors and hunters. Stopping them will be no easy task.\n\nI'm going to come along and help. It's time I put my mother's spear back to use.\n\nOnce they are defeated, use this totem I've crafted to help the subdued spirits find their way back to the kurgans.", objectives = "Defeat each renowned centaur spirit, then use Zorig's Totem of Respite to release them.", progress = "Hurry. We must free these spirits.", completion = "I'm so relieved that my mother is at peace again. Thank you, <name>!" }
WordHunterWoW_QuestEN[66657] = { title = "And Stay Dead!", description = "Tombcaller Arban has holed up in the largest kurgan, where the first Maruuk ancestors were laid to rest. Stop Arban before he raises Maruuk and Teera!", objectives = "Enter the main kurgan and defeat Tombcaller Arban.", progress = "He'll have no tomb of his own when this is done.", completion = "Unlike my mother, and our ancestors, no one will wish for Arban to live again. Thank you for helping me avenge them." }
WordHunterWoW_QuestEN[66658] = { title = "The Nokhud Offensive: Founders Keepers", description = "Teera and Maruuk's weapons were removed before we stopped Tombcaller Arban. Our greatest ancestors may fight again in these plains... for the Nokhud.\n\nGo to the Nokhud Offensive. Find Maruuk and Teera. When you have subdued them, bring their weapons back to the Teerakai burial mound. We will lay them back to rest with the honor they deserve, in a place we can protect more easily.", objectives = "Enter the Nokhud Offensive, defeat Teera and Maruuk, and place their weapons in the Teerakai kurgan.", progress = "Were you able to defeat the legendary spirits of our founders?", completion = "I would never have expected such help from an outsider before. You have my thanks." }
WordHunterWoW_QuestEN[66660] = { title = "On Your Mark... Get Set...", description = "<Nozdormu's gaze is unfocused.>\n\nThe further they fall, the faster they travel. They punch holes through the fabric of time which send out great ripples. You will need to be swift to catch them.\n\n<Nozdormu's focus sharpens and shifts to you.>\n\nI will send my timewalkers to help you navigate the timeways and speed your efforts. Avoid entangling with the temporal locals and do not stop until you have found Chronormu!\n\nGo. We have precious little time.", objectives = "Join Andantenormu and Siazerathel in the past.", completion = "Are you ready, <name>?" }
WordHunterWoW_QuestEN[66661] = { title = "It's Just a Coin, What Could it Cost?", description = "<This curious object provides more questions than answers. How did you come to have it? What is it used for? Is it dangerous?>\n\n<If the Eternal City does not hold answers for you, then surely the Brokers who trade there will.>", objectives = "Seek out a Broker in Oribos for information.", completion = "That coin... no one in Oribos will take its kind, and I doubt you'd survive the trip to the market that could. If I may be so bold, perhaps my associates and I could provide assistance?" }
WordHunterWoW_QuestEN[66671] = { title = "Path to Nowhere", description = "Ye look like a willin' and able adventurer! How would ye like to help out the Dragonscale Expedition?\n\nWe've got ourselves a lovely camp in the middle of a nice bit of wilderness.\n\nThere's plenty for ye to do if ye'd like to take the trip over there. \n\nTalk to me sis, Maddy, when ye get there. She'll get ye all settled in.", objectives = "Meet Maddy Scattershot at Camp Nowhere within the Azure Span.", completion = "Caddy sent ye? She wasn't here before all the commotion broke out with the tuskarr and the furbolg!\n\nTo say we got things to do in the camp is a wee understatement. We're flooded with problems!" }
WordHunterWoW_QuestEN[66673] = { title = "Speak to Koranos", description = "The Watchers have observed much over the years. Many of them are lost to the vagaries of time, but we still have Koranos.", objectives = "Speak to Koranos in Valdrakken.", progress = "Koranos has been here since the beginning. If he doesn't have answers, he should be able to point you in the right direction.", completion = "The Sundered Flame won't let us recover these stones without a fight." }
WordHunterWoW_QuestEN[66675] = { title = "Aspect Power", description = "The Mother Oathstone is an ancient gift bestowed to our flights by the Titans. If what we have learned is true, I might be able to reactivate it and in doing so restore our aspectral powers.\n\nThough we are unsure of the outcome, if this has the slightest chance of working I must attempt it.\n\n{name}, I would appreciate if you would join me in this.", objectives = "Assist Alexstrasza at the Mother Oathstone.", completion = "What happened, <name>? Where is Alexstrasza?" }
WordHunterWoW_QuestEN[66676] = { title = "Sneaking In", description = "This is Lizi... she's my secret friend. I've been taking care of her since she was rejected by her mother.\n\nThis isn't looking good. Whatever they did to her is beyond my knowledge. I have to bring her home. My Ohn may ground me for the rest of time, but Lizi must get help. I am ever grateful to you, {name}. I'm sorry this was more trouble than you signed up for.\n\nIf you wouldn't mind one more adventure... please face my Ohn's wrath with me? Meet me back at the springs.", objectives = "Return to Radiya in Ohn'iri Springs.", completion = "You've returned! Look--Lizi is going to be all right." }
WordHunterWoW_QuestEN[66679] = { title = "Ruby Lifeshrine Loop", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66680] = { title = "Counting Sheep", description = "How frustrating. A rabid stag did this while my brother Olekk and I were scouting.\n\n<Watu gestures at his bloody leg and winces.>\n\nAre you here to help? After the primalists attacked, our herd of argali scattered into the pines. Their wool and milk are essential to the camp's functions.\n\nTake this whistle, which commands Wish to herd the argali back home. Sondo the butcher has her favorite treats if she needs extra encouragement.", objectives = "Befriend Wish with food, and use Wish's Whistle to save 5 Lost Argali in the Sagecrest Pines.", progress = "Make haste. Argali are a favorite snack for the local--well, local everything.", completion = "So our argali live. Give Wish an extra pat for me, will you? I would do it myself, but I can't move. <Watu sighs.>" }
WordHunterWoW_QuestEN[66681] = { title = "Tempests Abound", description = "If you're venturing out into the pines, please slay any stormtouched animals. This is not easy for me to ask, but they're clearly in pain, unable to be helped, and spreading the aggression.\n\nI suspect it's the primalists' doing. It must be coming from their outpost nearby, where I saw a strange magical altar at work.\n\nI'm going to go investigate again. If I'm not back by the time you return, Scout Watu can brief you on additional tasks. We're grateful for any help.", objectives = "Kill 8 Stormtouched Beasts in Sagecrest Pines.", completion = "The pines should be a little safer now." }
WordHunterWoW_QuestEN[66683] = { title = "Last Resort Analysis", description = "<Watu mumbles to himself, eyes closed and arms crossed.>\n\nOf course I get gored by a stag, of all creatures. Now I'm just another one who needs help. My brother will get all the credit, and no one back home will be surprised.\n\n<Watu looks up.> What? What's that you've got there? Glowing rocks? I'll look at one, but take the rest to somebody else. I'm a hunter, not an archaeologist. <Watu snorts, glaring at his leg.> Maybe this is a sign for me to switch jobs. Go on, you've proven more useful than I.", objectives = "Inquire about the Stormtouched Shards in Pinewood Post.", progress = "<A strange look has overcome Watu. He barely registers your presence, infatuated with turning the shard over in his hands.>\n\nYou see how it glows, like new lightning?", completion = "<Watu stares at shock at his leg, newly bloody and pierced with the shard.>" }
WordHunterWoW_QuestEN[66684] = { title = "Storm Chasing", description = "<Watu rips the shard out and gasps for air.>\n\nI...completely lost control. Olekk was right. This terrible magic has to be the primalists' doing. Please, stop them!\n\nI must get my brother back to camp.", objectives = "Destroy the Primalists' source of storm magic.", progress = "Go with haste! That kind of power must be kept in check.", completion = "You've returned! I felt the destruction of the source from here." }
WordHunterWoW_QuestEN[66687] = { title = "Land of the Apex", description = "You should know of Rellen, the Learned, who gave centaur the tools to survive a merciless land. His memory requires offerings from worthy beasts.\n\nTake care, traveler. They are not as dangerous as they were eons past, but they're still the plains' apex predators.", objectives = "Collect 10 Shadespinner Webs, 2 Slyvern Talons, and 2 Thunderspine Scales.", progress = "Have you returned with the offerings?", completion = "You've returned intact. Good. Always respect the animals' prowess." }
WordHunterWoW_QuestEN[66688] = { title = "Signs of the Wind", description = "When the elements, true primals of the world, challenged the centaur, Himia met them with our given gift. The wind.\n\nA singing stone stands strong in the plains. There, you can offer tokens of the wind to evoke her memory. Such tokens may be found all around us--a bird's feather, a plant spore, a river's reeds.", objectives = "Gather wind tokens and give them to the Offering Vessel near the singing stone.", progress = "The singing stone is a morning's ride from here.", completion = "<There are ashen remains of previously offered wind tokens in the iron container.>\n\n<You place what you've gathered on top.>" }
WordHunterWoW_QuestEN[66689] = { title = "More Than A Rock", description = "<The shards are smooth and slightly hot to the touch. Lightning sparks deep within their core.>\n\n<Maybe Watu or Olekk would know more.>\n\n<The thought of parting with the shard fills you with compulsion to hold the shard close. To keep it forever.>", objectives = "Show the Stormtouched Shards to Watu.", completion = "<Watu doesn't register your presence. He remains sitting, favoring the injured leg, and has his eyes closed.>" }
WordHunterWoW_QuestEN[66690] = { title = "The Nokhud Offensive: The Final Ancestor", description = "You've proven yourself an ally to us, with genuine interest in our values and way of life. There is one more ancestor I'd like to tell you about, but it will be dangerous.\n\nKill the traitorous Balakar, leader of Nokhud, son of none. He wears a precious medallion at all times. Bring it back to me, and I will be forever in your debt.", objectives = "Defeat Balakar Khan and collect the Medallion of the Ancestors in the Nokhud Offensive.\n\nYou can access The Nokhud Offensive solo by queuing for it in Follower Dungeons.", progress = "Balakar never parts with the pendant. You'll have to kill him.", completion = "...I thought I'd never see the day." }
WordHunterWoW_QuestEN[66691] = { title = "Waking Shores - Race 01 - Intermediate", description = "This course has a similar layout to the previous, just with more variance in the checkpoint placement.\n\nIf you get stuck, blow the whistle and I'll reset you.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66692] = { title = "Ruby Lifeshrine Loop - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66693] = { title = "Tempting Fate: Castle Nathria", description = "", objectives = "" }
WordHunterWoW_QuestEN[66694] = { title = "Tempting Fate: Sanctum of Domination", description = "", objectives = "" }
WordHunterWoW_QuestEN[66695] = { title = "Tempting Fate: Sepulcher of the First Ones", description = "", objectives = "" }
WordHunterWoW_QuestEN[66696] = { title = "Tempting Fate: Fate of the Shadowlands", description = "", objectives = "" }
WordHunterWoW_QuestEN[66698] = { title = "Counting Argali", description = "One of our key resources is our argali herd. Every loss is felt deeply for the strength of our clan.\n\nA few of the argali have gotten separated and have wandered away from the herd. Our shepherds could use your assistance reclaiming them.", objectives = "Speak with the Aylaag Shepherd and return the lost sheep to the clan.", progress = "Have you reunited the herd?", completion = "Thank you. Our clan deeply appreciates the assistance." }
WordHunterWoW_QuestEN[66699] = { title = "Ask the Locals", description = "Kalecgos is wise to seek the tuskarr's counsel. They have generations of experience with this land.\n\nMany are resting here on their way to their various camps across the Span. \n\nAsk around! One of them must know about local ley lines.", objectives = "Speak to tuskarr around Camp Antonidas.", progress = "I'd offer you a bowl, but you appear to be in a hurry.", completion = "Brena is your best bet." }
WordHunterWoW_QuestEN[66700] = { title = "The Black Locus", description = "It really is quite enticing, isn't it? The Locus was too much for the Sundered Flame. However, it fits just right in my hands. Funny, that.\n\n<Adenedal shakes his head.>\n\nPerhaps not. Not this day. Not again. Take it from me. It is not my burden to bear.\n\nGood bye, dear friend.", objectives = "Bring the Black Locus to the Telemancer Aerilyn.", progress = "Do you have something to show me?", completion = "This was found at the Nelthazan Ruins? Fascinating. \n\nIts markings are ancient, but they bear a resemblance to other artifacts we have discovered in and around the ancient machinations of Deathwing.\n\nFurther study is necessary." }
WordHunterWoW_QuestEN[66703] = { title = "Snowball Effect", description = "Snowhide gnolls smart. They know you put food on ice, food is good longer. But just ice no good. Magic ice be better! \n\nThis be the work of shamans. And they put Frostbite here, so he starve to death next to delicious tuskarr meat.\n\nIf {race} want help tuskarrs, time running out. \n\nBut Frostbite knows how to break the spell.\n\nWhy Frostbite help? He no like shamans either.", objectives = "Retrieve 3 Snowhide Totems from the Snowhide Shamans in the Azure Span.", progress = "Tuskarr friends don't look so good, <race>.", completion = "So the sneaky shamans are dead?" }
WordHunterWoW_QuestEN[66704] = { title = "Mugurlglrlgl!", description = "Mrglgulglrrlglgul! Grurguglullgurl!\n\nGruglrlgllrugl rrgulgrulgrgl grugll gurgull gur. Murgllgllrugl gurgllglrl Murgul gruggullgl. Murguglegurgllgur gurgll gurgulgul guruulgurllgr guuglrllgl.\n\nMgrgulllglll gurl gugll.\n\n<You aren't certain what's being said, but there are lots of stabbing motions. It seems like this murloc wants you to kill something.>", objectives = "Murglgulglrrlglgul!", progress = "Murglgulglrrlglgul!", completion = "Lrgktrr O'Glrlrlrl!\n\n<The murlocs appear to be pleased.>" }
WordHunterWoW_QuestEN[66706] = { title = "[DNT]QuestNameHere", description = "", objectives = "" }
WordHunterWoW_QuestEN[66708] = { title = "Riders in the Snow", description = "Greetings, {class}. This magical dome is truly astonishing, is it not? But even though it protects us from the biting cold and the wilderness, we cannot count on the Kirin Tor forever.\n\nA few days ago, some of our most seasoned hunters ventured into the forests looking for food and supplies, but they never came back. Even though I know their leader, Old Grimtusk, is a seasoned hiker and hunter, it is very hard not to worry about him and his hunting party.\n\nCan you find them for me?", objectives = "Find the missing tuskarr hunters in the Azure Span.", completion = "<This tuskarr lies unconscious on the snow with a wooden spear protruding from his side>" }
WordHunterWoW_QuestEN[66709] = { title = "Field Medic 101", description = "<It's hard to say how long this wounded tuskarr has been lying here alone in the forest, but he won't last much longer without help.>", objectives = "Help Old Grimtusk recover from his wounds.", progress = "Of course, take your time. That's what you young pups do best.", completion = "Honestly? I thought your \"help\" would be the end of me." }
WordHunterWoW_QuestEN[66710] = { title = "Flashfrost Flyover", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66711] = { title = "Delicacy in the Dark", description = "Due to the nature of our clan, some resources are in short supply. We do not have the luxury of time to claim the land's metal resources.\n\nThe late khan established multiple trade connections with a variety of individuals, and I see no reason to discontinue their services.\n\nThe nearby bay contains buckets where we catch whelks - they're considered a delicacy for some of our neighbors. Bring a collection back to me for use in trade.", objectives = "Collect 12 river whelks for Hadari.", progress = "Take care with the traps, they may contain some more aggressive nuisances.", completion = "Ah, this will be helpful.\n\nIt is hard for me to rely on outsiders for such a key resource, but I cannot think of an alternate route." }
WordHunterWoW_QuestEN[66712] = { title = "Flashfrost Flyover - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66713] = { title = "[DNT]QuestNameHere", description = "", objectives = "" }
WordHunterWoW_QuestEN[66714] = { title = "[DNT]QuestNameHere", description = "", objectives = "" }
WordHunterWoW_QuestEN[66715] = { title = "The Extraction", description = "Right now the most important thing is to bring back my people. Preferably in one piece.\n\nAnd as much as it pains me to say this, I'm in no condition to fight them on my own. \n\nWill you help us?", objectives = "Rescue tuskarr from the Snowhide Camp in the Azure Span.", progress = "You look strong, little <race>. Are you?", completion = "You smell like death... Frostbite likes that." }
WordHunterWoW_QuestEN[66718] = { title = "Gnolls Must Die", description = "", objectives = "" }
WordHunterWoW_QuestEN[66719] = { title = "One Step Backwards", description = "My friend, it is with great sorrow that I must say that I am familiar with the plight facing your kind in these ruins. If you proceed any further, you too will surely succumb to their madness.\n\nBe it through your nurture or your nature, the call you hear is a physiological one. You have a craving that must be sated.\n\nIt brings me great shame to say that I possess the means to feed this malediction. It will not quite be the same, but you will be able to function... For now.", objectives = "Protect yourself from The Call.", progress = "I regret that it came to this.", completion = "Perhaps your people and mine are not so different after all." }
WordHunterWoW_QuestEN[66721] = { title = "Wild Preserve Slalom", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66722] = { title = "Wild Preserve Slalom - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66724] = { title = "The Gleamfisher", description = "I am sorry you have been dragged into this, traveler. \n\nMy brother tends to get... carried away. This is only the latest of his follies. But this one might get him killed. \n\nHe won't listen to me. He probably won't listen to you, either. \n\nOur ancestor, Kauriq the Gleamfisher, though, is the center of his fixation. She may be able to.\n\nPlease catch some Gleamfish and bring them here. I shall use them to help us commune with her spirit, which lingers in this stone.", objectives = "Retrieve 3 Gleamfish and place them in the offering basket.", progress = "Not all my ideas have worked out, but that doesn't mean this one won't!", completion = "Did you hear all that, hero?" }
WordHunterWoW_QuestEN[66725] = { title = "Wild Preserve Circuit", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66726] = { title = "Wild Preserve Circuit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66727] = { title = "Emberflow Flight", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66728] = { title = "Emberflow Flight - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66729] = { title = "Conditionals", description = "I don't like the alliance. Remember me? \n\nGo kill Mawsworn.", objectives = "Kill 1 Mawsworn" }
WordHunterWoW_QuestEN[66730] = { title = "True Survivors", description = "I know we're pretty banged up, but we can't forget why we're here. Our people are counting on us, and I don't plan on letting them down. We've got to find a temporary place for ourselves in these savage parts, and I know just the place.\n\nNow quit whining and MOVE IT.", objectives = "Find and speak with Old Grimtusk at the Frozen Lake in the Azure Span.", completion = "That wasn't so hard, was it?" }
WordHunterWoW_QuestEN[66732] = { title = "Apex Canopy River Run", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66733] = { title = "Apex Canopy River Run - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66734] = { title = "Leave Bee Alone", description = "Oh, thank the Life-Binder! Someone with empty hands!\n\nThese gardens are normally a lovely playground for our whelps, but the bees have multiplied uncontrollably. The blooms returned with vigor--and so have the bees. The whelps are terrified, the dragons are annoyed, and just yesterday one was stung and--\n\n<Vaeros takes a deep breath to center himself then looks at you pleadingly.>\n\nWill you please gather up the bees and relocate them to the lake? Take this smoke diffuser; it will calm them down.", objectives = "Use the Smoke Diffuser to calm and gather 8 Bothersome Bees, then release them near the lake.", progress = "Try not to be too rough with the bees. They are doing their best. We all are.", completion = "Please tell me the relocation went well.\n\n<Vaeros lets out a deep sigh of relief.>\n\nHopefully the bees will be kept busy pollinating the plants that are far away from our whelps. Thank you, <name>." }
WordHunterWoW_QuestEN[66735] = { title = "Just a Trim", description = "The bees scaring the whelps is not the only problem. While pollination is usually a good thing, the recent swarm has caused the flora to grow out of control.\n\nWould you mind taking my gardening shears and cutting back the shrubs? Some have already begun to sprout dangerous lashers, but I hope we can stop more from doing so. An ounce of prevention is worth a pound of cure, after all.\n\nAnd I could... very much use some prevention right now, {name}.", objectives = "Prune 5 Overgrown Shrubs.", progress = "If you use my gardening shears on anything other than plants, I will be very cross with you.", completion = "Thank you, <name>. With any luck, the bees will have fewer reasons to be close to the whelps now." }
WordHunterWoW_QuestEN[66737] = { title = "A Better Start", description = "Vaeros is diligent, but whelps have a way of finding trouble. Not mine, of course--but I suppose not every dragon rears their clutch to understand the gravity of their station.\n\nWhile I am loathe to encourage outdoor play over study, I will help you safeguard the garden more effectively. Take these seeds and plant them nearby. When mature, the blooms produce a fragrance that insects find disagreeable.\n\nThe gardeners can help you--and maybe my bronze brethren, if you mind your manners.", objectives = "Plant seeds in 6 Fertile Soil patches and allow them to mature.", progress = "Do remember to be courteous to our bronze companions, lest they toss you into a timeline without luxurious stationery and herbal tea.\n\n<Adazius sighs wistfully.>\n\nWhat a terrible existence that would be.", completion = "I am rather surprised you did not earn more than a scathing reproach from Veladormi. She must be feeling generous today.\n\nI suspect the insect problem is now solved. You are welcome." }
WordHunterWoW_QuestEN[66777] = { title = "Uktulut Coaster", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66778] = { title = "Uktulut Coaster - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66779] = { title = "Heir Apparent", description = "As Neltharion's heir and leader of the only surviving flight of black dragons, I was not expecting to find myself in competition for my birthright. Particularly not against a self-important whelp younger than you, mortal.\n\nNevertheless, if you need more than these self-evident facts, feel free to speak with members of my flight. There's no need to take my word on the subject.", objectives = "Speak with Sabellian's followers.", progress = "My flight awaits.", completion = "I trust that you understand, now." }
WordHunterWoW_QuestEN[66780] = { title = "Claimant to the Throne", description = "I have dedicated myself to saving Azeroth from destruction time and time again, and this fool thinks he can just swoop in and claim the title of aspect? I think not.\n\nTalk to my people, {name}. See what they have to say about me and what I have done for this world.", objectives = "Speak with Wrathion's followers.", progress = "Their loyalty is unquestionable.", completion = "Surely you back my claim, do you not, <name>?" }
WordHunterWoW_QuestEN[66781] = { title = "A Matter of Taste", description = "The disrespect around here!\n\nA couple smelly gorlocs steal bits from our equipment and we have to shut it all doon... Ha! I've been lickin' rocks since before ye were a wee babe! Did nae need nae fancy gnomish gadgetry. \n\nBring me a rock, and I'll prove it!", objectives = "Find a rock for Mordigan Ironjaw to lick in Whaler's Nook.", progress = "Find a good rock yet?", completion = "Perfect! Prepare to witness the most impressive feat o' geology ye've ever seen!" }
WordHunterWoW_QuestEN[66783] = { title = "Renewal of Vows", description = "Centuries ago, I made a vow of friendship and cooperation with the first centaur. Although much has changed, I feel it is time for us to renew that vow again.\n\nA recitation was composed to help future generations of centaur remember their bond with the green dragonflight. Each verse must be answered with an offering from the khans. I hope the centaur can still remember the original meanings.\n\nThe choice of gift is critical. Choose the right offering, and our allegiance is bound.", objectives = "Help Sansok Khan, Tigari Khan, Khanam Matra Sarest, and Merithra exchange gifts.", progress = "The recitation is as follows:\n\nFrom the hunters who value skill above all, a rite of passage: a first.\n\nFrom the mystics who commune with the wind, her lightest touch: a lift.\n\nFrom the descendants of the matriarch, a drop of unbroken progeny: a line.", completion = "Now that our bonds are renewed, nothing can stand in our way. By wind and wing, so be it." }
WordHunterWoW_QuestEN[66784] = { title = "Starve the Storm", description = "You fight well for one who must balance on only two legs!\n\nIt matters not how hard we fight so long as the Primalists continue to draw reinforcements. We must close that portal, the Storm Corridor!\n\nFight your way into the nearby cavern and slay the Primalist Storm-Summoners holding it open. I will aid you if I am able.", objectives = "Kill Primalist Storm-Summoners to close the Storm Corridor Portal.", progress = "All this is pointless if that portal remains open!", completion = "Now that we have cut off our enemy's reinforcements, the battle will enter its final stage. Great work, <name>." }
WordHunterWoW_QuestEN[66785] = { title = "The Last Eggtender", description = "I understand your concern, {class}, but all will be rectified shortly as it seems that we are about to have company. \n\nFeel free to stay and witness what transpires. It should be quite cathartic.\n\nDo speak with our egg tender when you have a moment, though. She will no doubt need the support.", objectives = "Speak with Mother Elion.", completion = "Can you believe it?" }
WordHunterWoW_QuestEN[66786] = { title = "Wingrest Roundabout", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66787] = { title = "Wingrest Roundabout - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66788] = { title = "Egg-cited for the Future", description = "I can scarcely believe it! Eggs of the Black Dragonflight! After all this time!\n\nBut look at the state of this place! It will not do at all! Nothing is too good for these eggs.\n\nThough with those two blowhards squabbling like children for the Life-Binder's favor, you can bet they have not spared a thought for us! You, though, will not leave an old egg tender all alone, will you?", objectives = "Help Mother Elion restore the area.", progress = "We are not done yet, young one.", completion = "Thank you, <name>. I feel like we have a future once more." }
WordHunterWoW_QuestEN[66805] = { title = "Keys of Loyalty", description = "", objectives = "Collect 1 Greater Obsidian Key." }
WordHunterWoW_QuestEN[66814] = { title = "The Judgment of Tyr", description = "Welcome to the Veiled Ossuary. Originally built to house and memorialize the dead. Now the likely location of the stone we've come to call the Judgment of Tyr.\n\nWe haven't received reports of any overt Sundered Flame presence here, but the expedition has learned that they prefer to strike unawares.\n\nBe on your guard, {name}.", objectives = "Recover the Judgment of Tyr.", progress = "All I ever wanted was to study. Instead, I'm sifting through rubble and getting chased by draconic ghosts.", completion = "Tyr held this at one point. Incredible." }
WordHunterWoW_QuestEN[66825] = { title = "A Ruby Lifecalling", description = "{name}! How fortunate you are here! We are about to begin a Lifecalling Ceremony and would be honored if you assisted us. \n\nA dragonspawn's Calling is very special. Some become masterful gardeners; others care for particular wildlife.\n\nThese young dragonspawn have finished their training and are ready to take on their first Callings. I know they would be thrilled to have you participate. When you're ready, please present each of the items on this table to them.", objectives = "Participate in the Lifecalling Ceremony at the Ruby Lifeshrine.", progress = "Ah, I remember my first calling like it was yesterday...", completion = "A Calling can change throughout a dragonspawn's life, but we each cherish our first greatly. Thank you again for participating in our ceremony." }
WordHunterWoW_QuestEN[66827] = { title = "Flowers of our Labor", description = "The legend says she only sings it for those who prove their devotion to life.\n\nI've been tending this garden for years... And I think my plants and I are finally ready.\n\nI'll start setting up by the pool here. You can help me with the harvest!\n\nGather seed pods from beneath bushes, dragonflowers from sunny fields, and dragonfruit high in the trees. You can borrow my old rake to help with those. And watch out--sometimes the foliage can be feisty!", objectives = "Collect 5 Ripened Dragonfruit, 5 Fragrant Dragonflowers and 5 Lush Seed Pods from around the garden to offer to the Dragon Spirit.", progress = "<Akora talks nervously to herself.>\n\nJust remember the mantras...\n\nFruit that is sweet,\nis harbored from heat.\n\nTilling early the soil,\nsaves future toil.\n\nIf a tree should bare fruit,\ndon't forget its roots...", completion = "Well... at least the animals seemed to enjoy my work.\n\n<Akora tries to smile but is unable to hide her disappointment.>\n\nMaybe the legend was never real at all." }
WordHunterWoW_QuestEN[66828] = { title = "Huddle at the Hollow", description = "I've never seen Akora this upset. Usually she's as sunny as her flowers, but that legend means a lot to her. She talks about it all the time. Hm...\n\n<Keshki fidgets with their glasses.>\n\nI don't know a lot about plants, and I don't think frogs would cheer up anyone but me...\n\nBut north of here there's a quiet spot where I do my thinking: Hornswog Hollow. Maybe we can find something to cheer her up there? Or, uh, try to formulate a plan to help?", objectives = "Meet Keshki at Hornswog Hollow.", completion = "As much as I want to cheer up Akora, <name>, taking care of these poor frogs is a bigger priority.\n\nFor the red dragonflight, preserving life always comes first!" }
WordHunterWoW_QuestEN[66830] = { title = "Hornswoggled!", description = "Oh, those hornswogs make me so mad!\n\n<Keshki stomps her foot angrily, knocking her glasses askew>\n\nThey're big, greedy bullies! Just because the place is named after them doesn't mean they get to jump all around and eat everything smaller than them!\n\nHere, use my jar of fireflies--it's a frog-minder's best friend. It'll calm the frogs enough that you can collect them, and we can get them out of harm's way.\n\nAnd if any hornswogs get in your way, don't be afraid to bully them back!", objectives = "Use Keshki's Jar of Fireflies to lure 8 Bullied Frogs to safety.", progress = "Frogs are gentle creatures! It's not fair to push them around like this!", completion = "Whew, all the frogs we helped are in the carrier!" }
WordHunterWoW_QuestEN[66831] = { title = "Home Is Where the Frogs Are", description = "All the frogs are rounded up, {name}! I guess we're, uh, taking the frogs to Akora anyway. They'll be safe at the Life Pools until the hornswogs get bored and move on.\n\nUm, well, I guess we didn't find anything to cheer up Akora. I hope she understands...", objectives = "Meet Keshki back at the Life Pools to release the rescued frogs.", progress = "Honestly? I'm just glad the frogs are safe.", completion = "I guess the legend was real this whole time.\n\n<Keshki grins, looking bashfully at Akora.>\n\nAnd maybe we're, um, both pretty good at tending life after all." }
WordHunterWoW_QuestEN[66833] = { title = "Marmoni in Distress", description = "", objectives = "" }
WordHunterWoW_QuestEN[66834] = { title = "Rellen, the Learned", description = "Bring your offerings to the central den. You may witness the legend of Rellen, the Learned, who gave centaur our livelihood as we know it.", objectives = "Make your offerings in the offering den and witness each of Rellen's teachings.", progress = "The offering den is in the center of Teerakai.", completion = "Rellen established the centaur's footing in these plains. We would have never survived without his teachings." }
WordHunterWoW_QuestEN[66835] = { title = "Sundapple Copse Circuit", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66836] = { title = "Sundapple Copse Circuit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66837] = { title = "Nothing for Breakfast", description = "My brother Valdo was supposed to order more supplies. But it's been a week and nothing has come. \n\nI'm not surprised. The lazy oaf probably took a nap instead! Now we're short on food, and I'm too busy to hunt on top of my chores--and Valdo's! \n\nWould you hunt for us? The meat of the vorquin striders and striped bruffalon south of here would keep the kitchen open until I can order supplies.", objectives = "Collect meat from the vorquin striders and striped bruffalon south of Three-Falls Lookout.", progress = "Did you get some vorquin meat? Any bruffalon flanks? Great! I was ready to put fillet of boot on the menu...", completion = "Thanks to you--and no thanks to Valdo--I can feed all these hungry travelers!\n\nHmm... are you looking for a job? I've got a recent \"opening\"...\n\nCan't pay you much, but you can have Valdo's spot! No? Ah well, can't blame me for trying." }
WordHunterWoW_QuestEN[66838] = { title = "It's Cold Up Here", description = "Being a good innkeeper means anticipating guests' needs. Unfortunately, I didn't anticipate how cold the nights would be here. Oops?\n\nMy guests are going to need blankets--and good, thick ones. Maybe bear pelts will do?\n\nThere are some large bears in the forest just east of here. If you bring me some of their pelts, I'll pay you for them! \n\nPlease? Think of the adventurers and their cold, cold feet...", objectives = "Collect thick bear pelts from thickmane bears.", progress = "Huh? Oh! You're back already?\n\nSorry, I got kind of involved in my card game... \n\nDo you have the pelts?", completion = "Oh! These are awesome. So luxurious and soft...\n\nNow, only if Valdo were here to clean them up!" }
WordHunterWoW_QuestEN[66839] = { title = "It's Brew Time!", description = "The gang had some time off and was hankerin' for a pint, so we bellied up to the inn.\n\nBut, ach! I can nae believe it! They didna have any brew! What kind o' inn is that? One ran by the Stonehinges--that's what kind!\n\nSo we're takin' matters into our own hands! The forest to the east has flowers and herbs that we could use to brew some sweet mead. Feel like helpin' me and doin' some flower pickin'? There'd be somethin' in it for ye!", objectives = "Gather Blood Berries, Bronze Horn Berries, and Dragon Foil Blossoms.", progress = "Ye get a nice mead-brewin' bouquet yet?", completion = "Oh, these are be-u-ti-ful! This one is spicy! And this one reminds me of Earthroot. Oh, I can taste the sweet mead now...\n\nThank ye kindly, friend! Ye saved me and the gang's afternoon!" }
WordHunterWoW_QuestEN[66840] = { title = "Water Safety", description = "My greatest responsibility is to make sure everyone has access to clean drinking water.\n\nWith the gnolls to the east dealing with the decay, I must make sure that the camp is safe.\n\nI don't want to alarm anyone by personally taking samples, but I feel testing is necessary.\n\nBring me samples from the three nearby waterfalls, and I will reward you handsomely.", objectives = "Bring three water samples to Manny Read.", completion = "A deep wyrm?\n\nSomething must have driven it away from its underground nest. Whatever spooked this apex predator  must be very terrible indeed.\n\nThank you, <name>, I will make sure to remove the carcass it doesn't contaminate the water." }
WordHunterWoW_QuestEN[66841] = { title = "A Shard of the Past", description = "I've seen ye runnin' in and out of the camp helpin' people. Ye think ye could help ol' Gannar too?\n\nI surveyed the area, and somethin' caught me old eyes. I think 'tis an ancient potsherd or a jar or somethin' just down south of here at the edge of that waterfall.\n\nNow, I am not much of a swimmer, but I'll give ye some coin and you can deliver the findings to Thanessa Silverbloom.", objectives = "Recover and bring the artifact to Thanessa Silverbloom.", progress = "You must be <name>.\n\nGannar said you were running some sort of an errand for him?", completion = "This is an unbelievable find! I have never seen ancient pottery like this. And these markings... Give me a moment while I inspect them." }
WordHunterWoW_QuestEN[66843] = { title = "Out of Lukh", description = "Ach! Have ye seen me assistant, Lukh?\n\nThe kid wanted a moment to look 'round, but he's been gone for an hour! \n\nI told him it ain't safe here and to nae walk far, but the kid has a head as thick as a ram's.\n\nI can nae say I blame him. it's pretty out here, and he has a thing for flowers.\n\nCould ye help me find 'em? They need me and the wagon back at Three-Falls Lookout!", objectives = "Find Lukh's whereabouts.", progress = "Well? Where is he? Did ye find 'em yet? \n\nWe have to go! That collapsed cave at Three-Falls Lookout won't clear itself!", completion = "Thank ye for findin' him. Betcha he won't stray far alone anymore.\n\nHere's a little somethin' for ye help." }
WordHunterWoW_QuestEN[66844] = { title = "The Great Shokhari", description = "Of all da animals I have seen here, Shokahri, da great sky vixen, be da most proud.\n\nIt be a shame she preyed on a gnoll shaman, cause now she be crazed with decay. When I saw her eating one of her kits, I knew something was not right.\n\nI took da kits away and brought them here, but Shokhari attacked me, swiping me good. I almost didn't make it.\n\nShokhari must be put down. If da decay rots more of her mind, she be coming for us soon.", objectives = "Kill Sky Vixen Shokhari.", progress = "Shokhari got a taste for our flesh now. It be a matter of time before she come to Three-Falls Lookout.\n\nYa must end her suffering!", completion = "Oh, it be a sad time for me, but it had to be done. \n\nHere, take one of Shokhari's kits. I can't keep dem all. Carin' for dem be the least we can do. \n\nRaise it well." }
WordHunterWoW_QuestEN[66845] = { title = "Legendary Foil", description = "Last night, I was lying in my bedroll, tossing and turning, when an unnatural chill filled the inn. \n\nThen, out of nowhere I saw... the ghost of a draconid! It went through my luggage then vanished into thin air! \n\nBut the true horror is that when I woke up... the ghost had taken my most beloved card!\n\nWould you be so kind as to track down the ghost and get my card back? It is my most prized possession.", objectives = "Find the draconid ghost and retrieve the legendary card.", progress = "Please, you have to find my legendary card! It was a family heirloom given to me as a young cub. It means the world to me!", completion = "The apparition explained itself and asked for forgiveness.\n\nBut then they asked to play a single match with me. \n\nOur game is apparently very different from what they used to play, and they wanted to try it.\n\nThank you for helping both of us. Maybe the match will be fun?" }
WordHunterWoW_QuestEN[66846] = { title = "The Heart of the Deck", description = "The day the Dragon Isles began their slumber was the day of my very last match. Fate was cruel, and I lost my strongest card before I could compete.\n\nGuo-Hee's card, you see, was mine. I do not know how her ancestors came upon it.\n\nAlas, I cannot claim it as my own as it has been in her family for centuries. That was a foolish mistake on my part.\n\nPerhaps you and I could craft a card together? A truly unique card... Yes! Will you help me?\n\nSpeak to me once you are ready.", objectives = "Help the apparition craft a new card.", progress = "The card we create must be powerful as well. I will need your assistance in creating it!", completion = "This is it! I have never seen such a card before! Such power! So many possibilities!\n\nMagnificent!\n\nThank you, <name>. Now I am ready..." }
WordHunterWoW_QuestEN[66847] = { title = "Vault of the Incarnates: Fury of the Storm-Eater", description = "No! We locked the Incarnates away to save this world and now Raszageth seeks to free them!\n\nShe cannot succeed, {name}. All life on Azeroth is in grave danger if you do not stop her!\n\nI shall return to Nozdormu at the Seat of the Aspects to plan for whatever is to come. \n\nKhadgar and Kalecgos are already inside with a contingent of allies. Join them to put an end to Raszageth.\n\nGood luck, champion.", objectives = "Enter the Vault of the Incarnates and defeat Raszageth.", progress = "Have you stopped Raszageth? We cannot let her plans go unchecked, <name>.", completion = "This is grave news, <name>. Azeroth is in danger once more, but Khadgar is right.\n\nWe can't lose hope." }
WordHunterWoW_QuestEN[66848] = { title = "Omens on the Wind", description = "Ohn'ahra does not speak in language as we do. Her voice carries through the very winds. We mystics are trained to feel her presence, follow her call, and interpret her messages.\n\nI have used the materials you gathered to bind totems to this particular call. Aid me in a ritual to center her voice, then I will interpret her song.", objectives = "Aid Ohn Seshteng in her ritual.", progress = "Ohn'ahra's voice is all around us. You just have to listen.", completion = "The storm is an omen of grim portent. Trouble is brewing." }
WordHunterWoW_QuestEN[66856] = { title = "Becca Black and the Seven Gnomes", description = "The djaradin have ransacked the Obsidian Citadel and stolen a number of valuable artifacts.\n\nWrathion has tasked us to recover every item taken from the Citadel. My team has located several in the area, but we could use your help.", objectives = "Recover the missing artifacts.", progress = "Have you found everything on the list?", completion = "Excellent work, <name>. Once we've located more of the stolen artifacts, we'll be sure to call for your help again." }
WordHunterWoW_QuestEN[66858] = { title = "Tour the Trading Post", description = "<A flyer, carried by the wind, flaps into your hands.>\n\nFancy yourself a collector, trader, or adventurer? \n\nWe've travelled all over Azeroth collecting goods of the finest quality for someone exactly like you!\n\nVisit one of our outposts in Stormwind or Dornogal and browse all the latest goods!\n\n--T&W Trading Post\n\n<You squint to read the fine print.>\n\nBe sure to present this flyer for some extra Trader's Tender!", objectives = "Collect Trader's Tender from the Collector's Cache and tour the Trading Post.", progress = "Welcome to the Tradin' Post! \n\nWe've got goods from all over Azeroth for ye to collect. Would ye like to take a look?", completion = "Now that ye've visted the shop and taken a look at our wares, here's a few more Trader's Tender for bringin' in that flyer.\n\nIf you want to keep earnin' tender, then check out the Traveler's Log portion of the Adventure Guide to see what activities ye can do. Complete enough activities and we'll reward you with tender and other amazing items." }
WordHunterWoW_QuestEN[66860] = { title = "Relic Recovery: Legacy of Tyr", description = "Kemora has been having me search for any reference to Keeper Tyr and Uldaman that exists. My paper cuts have paper cuts with all the books I have had to go through trying to find what she is looking for. \n\nAlmost all mentions are torn away or destroyed. Aside from this one that I... set aside to show her later. Apparently there is something precious in Uldaman that has been hidden away. I would be very interested in having you bring it to me. \n\nSo that I may help Kemora in her research of course.", objectives = "Obtain the Hourglass of Shifting Sands from Chrono-Lord Deios in Uldaman.", progress = "Do you have it?", completion = "Splendid!\n\nI have no idea what this is, but I am sure it is powerful. I shall put it somewhere safe... for Kemora to find later. \n\nDo not worry about telling her, she is quite busy at the moment." }
WordHunterWoW_QuestEN[66861] = { title = "Relic Recovery: Neltharus", description = "You there! The djaradin have been a menace to dragonkind for far, far too long -- and they have only grown more powerful thanks to the secrets they've managed to pilfer from Neltharus. \n\nGo, find what you can and bring it to me. At this rate, I'll take anything that could give m... us an advantage against them.\n\nOh, and take some friends along. I am sure you think you are strong, but the djaradin are stronger. Trust me.", objectives = "Obtain the Spellbound Musken-Hide Satchel from Warlord Sargha in Neltharus.", completion = "A bag? You've brought me a bag? \n\nNo, you cannot have it. Who knows what lies inside? I need to see if there is anything of use... to our research, of course." }
WordHunterWoW_QuestEN[66862] = { title = "Relic Recovery: Ruby Life Pools", description = "So, the Primalist continue with their onslaught on the dragons within the sanctity of the Life Pools? Disgusting. Those pools hold the future of dragonkind.\n\nI am sure Alexstrasza would not mind some extra aid in driving those Primalists out. Show them no mercy. \n\nOh yes... and bring back a trophy of your triumph. I despise any who come for the young.", objectives = "Obtain Kyrakka's Fangs from Kyrakka in the Ruby Life Pools.", progress = "Have you dealt with the Primalists?", completion = "<Theldren nods coldly at your offering.>\n\nExcellent work, <name>.\n\nAll who enter shall see these fangs upon our shelf and fear the wrath brought upon those who would stand against the dragon flights." }
WordHunterWoW_QuestEN[66863] = { title = "Relic Recovery: The Nokhud Offensive", description = "Brutish Nokhud forces on the Ohn'ahran Plains endlessly rebel against their rivals. Their leader, Balakar, is a fearsome and relentless opponent who does not easily admit defeat.\n\nOur storytellers in Valdrakken tell tales of thundering hooves and bone-breaking clubs, but that is nothing compared to witnessing centaur battles first-hand. Perhaps you should venture a bit more closely, hmm? You might even bring back a trophy!\n\nMay soaring eagles watch over you, <name>. I await your return.", objectives = "Obtain the Bloodstained Musken-Hide Greatbelt from Balakar Khan in The Nokhud Offensive.", progress = "Back so soon?", completion = "<Theldren inspects the musken-hide belt thoroughly.>\n\nOh, my. Is that fresh blood? I'll be sure to clean it up.\n\nOn second thought, it does add to the piece. Such authenticity! Don't you agree?" }
WordHunterWoW_QuestEN[66864] = { title = "Relic Recovery: Brackenhide Hollow", description = "Ah! I have use of you. The gnolls of Brackenhide Hollow are said to be using decay--a powerful tool, in the right hands. Gnolls do not have the right hands.\n\nWe should be doing our due research on this pressing issue. Go to the Hollow and bring back a bit of their magic so I can... so we can see what kind of powers they've harnessed.\n\nAnd do be careful and take some friends with you. The Brackenhide possess the ability to wither your very bones. \n\nThat would be a pity.", objectives = "Obtain the Decatriarch's Fetish from Decatriarch Wratheye in Brackenhide Hollow.", completion = "What's that you've found? Give it here!\n\nYes... this will do quite nicely...\n\nFor our research, of course. Now go--and thank you." }
WordHunterWoW_QuestEN[66865] = { title = "Relic Recovery: The Azure Vault", description = "The Azure Vault is said to hold some of the oldest and most powerful artifacts and relics in existence. Anything with that much power must be tak... preserved. \n\nGo, delve into the Azure Vault and see what you can recover. And bring some friends--the place is probably crawling with all kinds of dangerous magical nonsense.", objectives = "Obtain the Crystalline Focus from Umbrelskul in the Azure Vault.", progress = "You won't find anything of interest here, unless, of course, you're looking to speak with me.", completion = "What did you find? Hand it over!\n\nOh, oh yes... this is most fascinating. I'm sure I... we'll learn much from it." }
WordHunterWoW_QuestEN[66866] = { title = "Relic Recovery: Halls of Infusion", description = "Apparently Keeper Tyr had a giant facility below Tyrhold. Kemora is all aflutter with the 'possibilities' of what could lie within.\n\nWhat I know is that the keeper had all sorts of secrets and inventions. Useful ones. I am sure if you happened to wander in and take a look around you could get me something... intriguing.\n\nOh yes, some Primalists may have made it there before you. Dispose of them before they destroy all the good titan relics.", objectives = "Obtain the Core of Aqueous Corruption from Primal Tsunami in the Halls of Infusion.", progress = "Hmm? What is it now?", completion = "How kind of you to go into a secret facility, run by one of the most brilliant Keepers in existence, all to bring me back... this.\n\n<Theldren looks distastefully at the object, then starts to stare deeper.>\n\nNevermind. I mean... I suppose I can make this work. Since you went to all the trouble of getting it for me.\n\n<You see him place the object close by him. His eyes dart to it occasionally while a mysterious smile plays over his lips>" }
WordHunterWoW_QuestEN[66867] = { title = "Relic Recovery: Algeth'ar Academy", description = "The hallowed halls of Algeth'ar Academy are legendary to dragonkind. I hear they are even opening up their registrations to more than just dragons as well.\n\nTheir library is spectacular, there are books there that even the archives do not possess. \n\nSay... Since they are looking for new students, why not enroll? And while you are there perhaps obtain a library card and see if you can check out an interesting book for me. \n\nOh... I am sure Kemora will be interested as well.", objectives = "Obtain the Headmaster's Ledger from the Echo of Doragosa in Algeth'ar Academy.", progress = "Yes, yes. How go your studies?", completion = "This... this is all you could bring back? A cover and nothing more?\n\nPerhaps the pages are hidden by magic. Hmmm..." }
WordHunterWoW_QuestEN[66868] = { title = "Preserving the Past: Legacy of Tyr", description = "I have been going through the archives trying to seek information about Keeper Tyr and surprisingly every mention of Uldaman had been stripped away aside from a half page that mentioned something about a secret he kept there.\n\nFascinating stuff, no? I'm sure there are other secrets he hid in there as well. Perhaps you and some of your friends could go in and search. I would treasure anything you could bring back for me.", objectives = "Obtain the Time-Lost Curio from Chrono-Lord Deios in Uldaman.", progress = "Find anything of interest?", completion = "Wonderful! Though not specifically something of Tyr's, this will still make a fascinating addition to the Archives." }
WordHunterWoW_QuestEN[66870] = { title = "Preserving the Past: Ruby Life Pools", description = "Oh dear, Primalist forces have overtaken the Ruby Life Pools. Our young are in grave danger.\n\nI have heard that they are infusing our eggs with their elemental energies. Who knows what could happen?! But perhaps...\n\n$p, please venture into the pools and see if you can obtain me a token from one of the Primalists. I may be able to cross-reference some research and see if there is any help for our already infused eggs.", objectives = "Obtain the Primal-infused Dragon Egg from Kyrakka in the Ruby Life Pools.", progress = "Yes? Have you brought me something?", completion = "I cannot thank you enough. I will begin research immediately, if there is a change to undo what the Primalists have done I must seek it out." }
WordHunterWoW_QuestEN[66871] = { title = "Preserving the Past: The Nokhud Offensive", description = "Wars rage to the west. Plains soaked in blood. Battles and lives enduring the pains of an endless confrontation. This is our legacy, <name>.\n\nBeyond that legacy lies our future. For that future, we must preserve what remains of our histories and culture before it is nothing but a memory.\n\nHead west. Seek out the armies of the Khanam Matra and work with our allies to end the suffering of the Maruuk.\n\nTravel well, <name>. May Ohn'ahra guide your way.", objectives = "Obtain the Plume of the Sky Mother from Balakar Khan in The Nokhud Offensive.", progress = "We must do what we can before it is too late.", completion = "This... Where did you get this, <name>?\n\n\n\nWe'll be sure this is given the attention it deserves." }
WordHunterWoW_QuestEN[66873] = { title = "Preserving the Past: The Azure Vault", description = "The Azure Vault was the repository for an astonishing amount of ancient relics and research. What wonders the blue dragonflight must have discovered! \n\nPlease, venture into the Azure Vault and see what you can recover. I am certain there is much to learn! But do be careful--this was the repository for things too dangerous to be left alone in the world.", objectives = "Obtain Sindragosa's Records from Umbrelskul in The Azure Vault.", progress = "What ancient mysteries shall we unravel today?", completion = "This is... poor Sindragosa. To have to witness the pain of a child... I cannot imagine what she must have gone through. \n\nHeartbreaking, but there is a lesson to be learned from this. Great care must be taken when researching ancient magic. I thank you." }
WordHunterWoW_QuestEN[66874] = { title = "Preserving the Past: Halls of Infusion", description = "Did you know that deep beneath Tyrhold there is a giant facility called... The Halls of Infusion? So mysterious! So intriguing! So full of possibility! \n\nKeeper Tyr held many of his secrets there. I wonder what they are? He truly was the most brilliant of all the Keepers. \n\n<Kemora stares dreamily.>\n\nHowever, the Primalists are making a mess of things. They will surely damage all the wonders of Keeper Tyr if they are not stopped. Please, get rid of them before they cause too much harm.", objectives = "Obtain the Holographic Distributor from Primal Tsunami in the Halls of Infusion.", progress = "Have you brought me a secret? Oh! I am ever so excited.", completion = "Oh. So that was the secret Keeper Tyr was hiding.\n\nWell I am sure he had excellent reasons for what he did. He always was thinking ahead. And at least the Primalists did not destroy everything.\n\nPerhaps if I find the key this object will reveal a... nicer secret. \n\n<She looks at you with hopeful, dreamy eyes.>" }
WordHunterWoW_QuestEN[66875] = { title = "Preserving the Past: Algeth'ar Academy", description = "How wonderful! Algeth'ar Academy is open once again. Headteacher Doragosa must be pleased to be back in her halls of learning.\n\nIt has been quite awhile since I have had a chance to speak with my dear old friend. Perhaps you could you go and see if she is available for tea. It would also give you a chance to enroll in the Academy, I hear it is open to all students now.\n\nI thought that may be of interest to you with how much you visit me and these archives.", objectives = "Obtain the Dreamwisp of Entangled Memories from the Headteacher in Algeth'ar Academy.", progress = "Go! See the Academy and all the wonders it holds.", completion = "Oh Doragosa! I remember this... we shall have to talk it over at tea time.\n\nThank you, <name>. I take it your enrollment went well smoothly?" }
WordHunterWoW_QuestEN[66877] = { title = "Fen Flythrough", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66878] = { title = "Fen Flythrough - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66879] = { title = "Hornstrider Havoc", description = "Hornstriders! They've got bone-breaking beaks, fast legs for getting away from danger, and they can eat anything in the Isles.\n\nThis Calling's the easiest around! It's just me and my favorite big birds spending time together. And if anything comes up, I know how to wrangle all of the Isles' critters.\n\nWould you mind following me to the hornstrider plateaus up north? I wouldn't mind an extra pair of hands while getting set up.", objectives = "Meet Dazakros in the Overflowing Rapids.", completion = "I've read so many books on hornstriders, and I've wrestled the biggest baby thunder lizard you ever did see... but I don't know one thing about water elementals!" }
WordHunterWoW_QuestEN[66880] = { title = "Ravine River Run", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66881] = { title = "Ravine River Run - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66882] = { title = "Lost Battlepack", description = "<Talonstalker Kavia might want this.>", objectives = "Deliver the item to Talonstalker Kavia.\n\nProvided item:", completion = "It's still intact. Hopefully it brings the next owner more luck." }
WordHunterWoW_QuestEN[66883] = { title = "Ancient Horn Ring", description = "<Exadria might want this.>", objectives = "Deliver the item to Exadria.\n\nProvided item:", completion = "An ancient horn ring? It should be worn to honor those that fell in battles before us." }
WordHunterWoW_QuestEN[66884] = { title = "Fireproof Gear", description = "The armor of the djaradin can withstand even the fiercest flames. Such qualities would be of great use in combating them!\n\nSee what you can gather from the djaradin. We can study it, and apply the same enchantments to our own armor.", objectives = "Gather 10 Fireproof Gear from the djaradin of the Dragon Isles for Temnaayu of the Iskaara Tuskarr.", progress = "Were you able to gather any armor?", completion = "These are perfect samples for studying! We should be able to shore up our own armor quite nicely. \n\nYou have our thanks for your aid, friend." }
WordHunterWoW_QuestEN[66885] = { title = "Emerald Gardens Ascent", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66886] = { title = "Emerald Gardens Ascent - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66890] = { title = "Stolen Tools", description = "We have been plagued by gnolls raiding our supply caravans. They appear to be obsessed with the various engineering tools within. We cannot risk these violent raiders figuring out our specialized art! Also, these thefts have set our production schedule back more than I'd like to admit.\n\nIf you can retrieve some of the stolen engineering parts, we can get back on schedule.", objectives = "Gather 20 Stolen Tools from the gnolls of the Dragon Isles for Dothenos of the Valdrakken Accord.", progress = "Have you retrieved the stolen tools?", completion = "These parts will help us get back on track with our engineering projects." }
WordHunterWoW_QuestEN[66891] = { title = "Explosive Ash", description = "The molten phoenixes in the Dragon Isles create an unusual ash substance once they die. It could be used to create some material improvements for some complex, life-changing machinery. Though I would probably use it for explosives.", objectives = "Gather 20 Explosive Ash from the phoenixes of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition.", progress = "Have you found enough ash?", completion = "This ash could provide the essential component in a variety of machines that would improve the lives of people across Azeroth. But who am I kidding? We're going to make explosives with it. BOOM!" }
WordHunterWoW_QuestEN[66892] = { title = "Deluge Dilemma", description = "Elementals are killing the hornstriders! I know how to wrangle large critters, but I never thought I'd have to go toe-to-toe with an elemental! These aren't anything like baby thunder lizards...\n\n<Dazakros sighs, distressed.>\n\nPlease knock down a few of them elementals. Hornstriders have a lot more sense than we give them credit for. They'll fight back if they have the means to!", objectives = "Kill 12 Water Elementals in Overflowing Rapids.", progress = "If fighting elementals is anything like wrangling lizards, just give those soggy good-for-nothing's a solid knock to the nose and they'll fall in line!", completion = "And I thought I'd seen it all. Would you look at how these little ones drop from the spring?\n\nTurns out being a caretaker isn't so easy. Thanks for your help, <name>. I've learned a lot from you!" }
WordHunterWoW_QuestEN[66893] = { title = "Beaky Reclamation", description = "I may not know anything about water elementals, but I do know hornstriders!\n\nI've thrown together a salve that'll keep the 'striders healthy and ready to fight. I've never had a chance to apply it to a real hornstrider, but I've done all the studying I can do.\n\nIt's time to put on a brave face and lather them up!", objectives = "Heal 8 Injured Hornstriders in Overflowing Rapids.", completion = "It's downright uplifting to see the hornstriders take back their home. You brought that to them, <name>. Thank you for your help." }
WordHunterWoW_QuestEN[66894] = { title = "Same as the Old Boss", description = "The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing.\n\nHowever, Deathwing has not returned, and still there is no Twilight.\n\nIt is time for a new leader. You can help bring about the change.", objectives = "Eliminate Aizir the Inflamed.", progress = "Are we ready for a new leader?", completion = "You have done well. Now there is ample room for a new leader to rise and bring the Worldbreakers to a better future." }
WordHunterWoW_QuestEN[66895] = { title = "Same as the Old Boss", description = "The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing.\n\nHowever, Deathwing has not returned, and still there is no Twilight.\n\nIt is time for a new leader. You can help bring about the change.", objectives = "Eliminate Vyzos the Prophet.", progress = "Are we ready for a new leader?", completion = "You have done well. Now there is ample room for a new leader to rise and bring the Worldbreakers to a better future." }
WordHunterWoW_QuestEN[66896] = { title = "Net Income", description = "", objectives = "Collect 10 Warmwater Riverfish and 6 Succulent Snapper Meat." }
WordHunterWoW_QuestEN[66897] = { title = "Fuel for the Forge", description = "To make the best blades, you need the heat that only a Magma Core can provide. We try to keep a few on hand as a fuel source for our forges. Lately, we've been running low on cores and could use a resupply.\n\nMagma Cores are obtainable from most lava creatures in the Dragon Isles.", objectives = "Gather 10 Magma Cores from the lava creatures of the Dragon Isles for Dhurrel of the Maruuk Centaurs.", progress = "Have you gathered the Magma Cores?", completion = "The blacksmiths will be glad to have this resupply for their forges." }
WordHunterWoW_QuestEN[66899] = { title = "Fuzzy Legs", description = "We have received a request for \"Fuzzy Legs\" for tailoring...\n\nDon't look at me, I don't make the requests, I just pass them on. I imagine the legs of tarantulas would fulfill this request.", objectives = "Gather 20 Fuzzy Legs from the tarantulas of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition.", progress = "Have you gathered the Fuzzy Legs?", completion = "I can't imagine what these will be used for, and I don't really want to think about it, but thank you regardless." }
WordHunterWoW_QuestEN[66900] = { title = "Enchanted Relics", description = "Ah, the tides have brought you at just the right time! Gnolls have stolen some of our relics. These are more precious than most--they have been enchanted. We cannot allow the gnolls to learn our magics!\n\nSomeone of your skill should have no issue identifying the stolen relics. Please, will you lend us your aid?", objectives = "Gather 10 Enchanted Relics from the gnolls of the Dragon Isles for Temnaayu of the Iskaara Tuskarr.", progress = "Have you retrieved the relics?", completion = "I worry about what the gnolls may have learned about the relics while they had them in their possession.\n\nThank you for retrieving them." }
WordHunterWoW_QuestEN[66901] = { title = "Breaking the World", description = "", objectives = "" }
WordHunterWoW_QuestEN[66902] = { title = "Bee-Gone", description = "", objectives = "" }
WordHunterWoW_QuestEN[66903] = { title = "Clearing the Vault", description = "", objectives = "" }
WordHunterWoW_QuestEN[66921] = { title = "Maruukai Dash", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66925] = { title = "[DNT] Boar-B-Q", description = "", objectives = "" }
WordHunterWoW_QuestEN[66929] = { title = "Gotta Collect Them All", description = "{class}, do you mind helping me get my cards back? \n\nI told Setogosa I need them to show other students how to play Hearthstone. I want to form a club, but she's not giving them back!\n\nShe's always been rude to me, but this is taking it further than normal.", objectives = "Get Yumadormu's deck back.", progress = "I got a few of the cards out myself, have you gotten the rest yet?", completion = "Thank the aspects! Most of these are still in one piece.\n\nI figured out a way to reverse time on the cards using bronze magic and get them back to mint condition!" }
WordHunterWoW_QuestEN[66931] = { title = "Who Brought the Ruckus?", description = "That was no ordinary quake.", objectives = "Discover the commotion at the Ruby Lifeshrine.", progress = "What could that be?", completion = "I--\n\nAs much as I wish to follow my queen into battle, I must prove worthy of her trust and protect the Lifeshrine." }
WordHunterWoW_QuestEN[66933] = { title = "Mirror of Sky Dash", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66934] = { title = "Break the Breaker", description = "", objectives = "" }
WordHunterWoW_QuestEN[66935] = { title = "Crystal Quill Pens", description = "There are unique creatures in these lands called crystalspines. They are cute little creatures protected by sharp crystal quills.\n\nWhen I was treating one of our researchers for being stuck by one, I noticed that there was a lingering power resonating within. They might make for an excellent source of enchanting crystals.", objectives = "Gather 15 Crystal Quills from the crystalspines of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition.", progress = "Have you found some crystal quills?", completion = "These are a perfect source of magically resonant crystal." }
WordHunterWoW_QuestEN[66937] = { title = "Decaying News", description = "The gnolls and their use of decay magic are concerning. We need to gather as much knowledge as we can, in case the threat escalates. \n\nAs alchemists, we are used to gathering such foul substances safely--plus, we're used to the smell. Will you lend your aid?", objectives = "Gather 10 Rotting Samples from the decay gnolls of the Dragon Isles for Dothenos of the Valdrakken.", progress = "Have you gathered the Rotting Samples?", completion = "We will research these samples and see if we can come up with an alchemical solution to this looming problem." }
WordHunterWoW_QuestEN[66938] = { title = "Mammoth Marrow", description = "Creating new and unusual brews is one of our many specialties. While we do enjoy experimenting with new and fascinating ingredients, we have a few common ingredients that we keep in stock. \n\nOne of these ingredients is the marrow from mammoth tusks. We have run short on marrow and would appreciate your help in collecting more for our alchemists.", objectives = "Gather 20 Tusk Marrow from the mammoths of the Dragon Isles for Dhurrel of the Maruuk Centaur.", progress = "Have you gathered enough Tusk Marrow?", completion = "The alchemists of the Maruuk Clan will be pleased." }
WordHunterWoW_QuestEN[66939] = { title = "Hunting the Huntmaster", description = "I heard from one of the guards in Camp Nowhere that there's a nasty piece of work mutilating the local wildlife. Calls itself a 'huntmaster'.\n\nHunting is one thing, but I can't abide torturing any living thing. \n\nBesides, my wagon could use a good luck charm.\n\n<Nesingwary spits over the side.> \n\nBring me back its paw.", objectives = "Hunt down Huntmaster Krakle around Imbu's Shield.", progress = "How goes the hunt?", completion = "Ah, looks like you were successful. \n\nGood.\n\nHere's hoping the critters around here can rest a bit more easily." }
WordHunterWoW_QuestEN[66940] = { title = "Elixir Experiment", description = "Our alchemists have recently looked into a variety of new ingredients for experimentation. Their most recent interest is... interesting... to say the least.\n\nIt appears that gorloc mucus has some properties that can be beneficial for certain elixirs.", objectives = "Gather 15 Gorloc Mucus from the gorlocs of the Dragon Isles for Dhurrel of the Maruuk Centaurs.", progress = "Have you gathered the mucus from the gorlocs?", completion = "Wonderful. Now we will see what exciting concoctions our alchemists will produce with this." }
WordHunterWoW_QuestEN[66941] = { title = "Tremendous Tools", description = "The djaradin have some mighty large tools and weaponry. We can easily find a use for such tools, even if only to smelt them down into more tools for ourselves.\n\nBring back some djaradin tools for us to study and use.", objectives = "Gather 10 Large Tools from the djaradin of the Dragon Isles for Dhurrel of the Maruuk Centaurs.", progress = "Did you find the djaradin and collect some of their tools?", completion = "The blacksmiths have their work cut out for them. Thank you for collecting these tools." }
WordHunterWoW_QuestEN[66942] = { title = "Enemy Engineering", description = "It may be a bit controversial, but I believe that we can study the rituals of the Primalists to learn new ways to channel elemental power. I'm confident that once we understand the pathways of their magic, we can use it to create all sorts of innovative engineering products.", objectives = "Gather 10 Primal Rituals from the Primalists of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition.", progress = "Did you find some Primal Rituals?", completion = "I've been told that the Primalists reject civilization and seek to bring about its downfall. Ha! The joke is on them. Their rituals will inspire dozens of new gizmos that will bring about the next technological golden age." }
WordHunterWoW_QuestEN[66943] = { title = "Wood for Writing", description = "We've found some unusual information in our studies of the Dragon Isles. For instance, the bark of treants afflicted by decay magic acts similarly to hide parchment. \n\nThis odd parchment is strangely able to hold the magic for more powerful inscriptions. Very useful! Can you help us gather some?", objectives = "Gather 15 Bark Parchment from the decay treants of the Dragon Isles for Dothenos of the Valdrakken Accord.", progress = "Were you able to retrieve any bark?", completion = "It's so strange. The bark feels like a fine vellum. Though... holding the untreated sheaf brings dark thoughts into my mind. This amount will suffice for now." }
WordHunterWoW_QuestEN[66944] = { title = "Peacock Pigments", description = "The peacocks of the Dragon Isles have such colorful feathers! I bet we can make some pigments from them for our scribes to use as ink.", objectives = "Gather 8 Peacock Feathers from the peacocks of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition.", progress = "Have you gathered the Peacock Feathers?", completion = "So colorful! We will make some very nice pigments with these." }
WordHunterWoW_QuestEN[66945] = { title = "Icy Ink", description = "The icy beasts in the frozen biomes excrete a very rare and mysterious liquid. The liquid's properties make it the perfect binding agent for our inks. I'm a southpaw so the prospect of not smudging my page is very exciting to me.", objectives = "Gather 20 Icy Excrement from the ice spiders and ice bears of the Dragon Isles for Dothenos of the Valdrakken Accord.", progress = "Have you gathered the Icy Excrements?", completion = "Thank you for your hard work. We can make fine ink with these." }
WordHunterWoW_QuestEN[66946] = { title = "Azure Span Sprint", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66947] = { title = "Azure Span Sprint - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[66948] = { title = "The Emissary's Arrival", description = "I will admit that I have not left the Emerald Gardens in all my life, and as such, I have never met a centaur, let alone a mortal from the mainland.\n\nHowever, I am not here for a kindly visit, but rather to plead for the centaur's aid in securing our oathstone and protecting our charge.\n\nI am glad to see you are here to help as well. There is much to discuss.", objectives = "Learn about the situation in the Emerald Gardens.", progress = "The Green Dragonflight has lost much over the years. We need the aid of mortals where possible.", completion = "More friendly faces are welcome indeed." }
WordHunterWoW_QuestEN[66949] = { title = "Trinket Bandits", description = "The gnolls have quite a collection of trinkets. Tuskarr trinkets. They have either stolen them from our villages, or worse, from the brave tuskarr that fell in battle against them. These trinkets are our heritage and should reside with us.\n\nIf you bring some back to me, I will teach you the techniques that are used to make them.", objectives = "Gather 10 Stolen Trinkets from the gnolls of the Dragon Isles for Temnaayu of the Iskaara Tuskarr.", progress = "Have you retrieved the Stolen Trinkets from the gnolls?", completion = "I recognize these trinkets. I remember those they originally belonged to. Thank you for returning them to us." }
WordHunterWoW_QuestEN[66950] = { title = "Heart of a Giant", description = "There are various giants within the Dragon Isles that are rumored to contain beautiful gems at their core. We normally don't hunt the creatures of the Isles for treasures, but these giants have caused quite a bit of havoc.\n\nWe may as well collect these gems in the process of clearing out the destructive giants.", objectives = "Gather 5 Giant Cores from the mountain, ice, or molten giants of the Dragon Isles for Temnaayu of the Iskaara Tuskarr.", progress = "Have you found any gems from within the giants?", completion = "These are indeed beautiful treasures." }
WordHunterWoW_QuestEN[66951] = { title = "Population Control", description = "Recently there has been an overpopulation of a few different species on the Dragon Isles. In particular, the rockfang and the bruffalon.\n\nWe don't want to be wasteful, of course. Be sure to collect as much of the hides as you can from the creatures.", objectives = "Gather 25 Salvaged Hides from the rockfang and bruffalon of the Dragon Isles for Temnaayu of the Iskaara Tuskarr.", progress = "Have you dealt with the overpopulation and brought back some hides?", completion = "Thank you for handling the situation and for not wasting the hides." }
WordHunterWoW_QuestEN[66952] = { title = "The Gnoll's Clothes", description = "The gnolls are a constant threat, launching bloody raids and attacks against the expeditions and peoples of the Dragon Isles. So how are their clothes so clean?\n\nAfter your battles with these raiders, could you collect a sample of their worn cloth for me to analyze?", objectives = "Gather 20 Gnoll-Worn Cloth from the gnolls of the Dragon Isles for Dothenos of the Valdrakken Accord.", progress = "Did you bring the Gnoll-Worn Cloth?", completion = "Thank you for these samples. On casual inspection it seems to just be wildercloth stolen from the tuskarr, but I'll have our tailors really examine the stitching to be sure." }
WordHunterWoW_QuestEN[66953] = { title = "All Things Fluffy", description = "The tailors are always anxious to get their hands on that fluffy argali fur. The wool is especially useful for surviving in the freezing cold mountains of the Dragon Isles.", objectives = "Gather 20 Fluffy Fur from the argali of the Dragon Isles for Dothenos of the Valdrakken.", progress = "Did you get some of that Fluffy Fur?", completion = "So fluffy! Yes, this will do." }
WordHunterWoW_QuestEN[66956] = { title = "Dragonhunter Igordan", description = "", objectives = "" }
WordHunterWoW_QuestEN[66957] = { title = "A Shadow In The Ice", description = "I've heard whispers while passing through Camp Antonidas. Talk of mutilated fauna being found across the icy steppes. Some nothing more than bloody splatters. \n\nWhatever it is, it's got the mages scared and made the local wildlife scarce.\n\nPoke around the top of the glacier. If I was a betting dwarf, I'd say that's where any apex predator worth its salt would stake its claim.\n\nBring me a piece of it so we can soothe the Kirin Tor.", objectives = "Investigate the top of the glacier that overlooks Camp Antonidas.", progress = "Be careful. Whatever this thing is, it's strong. And relentless.", completion = "An ice giant? By Magni's bronze beard... And you're in one piece too! Impressive.\n\nI'll show this to the Kirin Tor. Now maybe they'll get off our backs!" }
WordHunterWoW_QuestEN[66958] = { title = "Protect And Herd", description = "I was talking with some hunters out of Iskaara the other day, and they mentioned finding a grisly scene. \n\nApparently, a particularly murderous rhino, Bloodhorn, has been goring the smaller bruffalon in the area. \n\nThe bruffalon have enough competition in Azure Span without worrying about getting their herds thinned out by an invasive brute from out of town!\n\nBring me his horn. I'd like to make a good impression on our Tuskarr friends!", objectives = "Hunt down Bloodhorn east of Iskaara.", progress = "Remember: watch out for his hooves! That's how rhinos get you.", completion = "Excellent job, <name>! This will go a long way in helping the bruffalon prosper and will hopefully show our Tuskarr neighbors we are also good stewards of this land.\n\nWe could learn a lesson from Bloodhorn. Just cause we're stomping through this beautiful place doesn't give us the right to do what we want with it!\n\nAlways leave the world better than you found it." }
WordHunterWoW_QuestEN[66959] = { title = "Tour the Trading Post", description = "<A flyer, carried by the wind, flaps into your hands.>\n\nRare antiquities from every corner of Azeroth! Fine goods fit for any taste!\n\nYou will not find these unique treasures anywhere else, friend.\n\nCome see us at one of our outposts in Orgrimmar or Dornogal and gaze in wonder upon the mysteries in store for you!\n\n--Zen'shiri Trading Post\n\n<You squint to read the fine print.>\n\nBe sure to present this flyer for some extra Trader's Tender!", objectives = "Collect Trader's Tender from the Collector's Cache and tour the Trading Post.", progress = "Welcome to the Trading Post. \n\nWe have goods from all over Azeroth here for your collectin'. Please, take a look.", completion = "Ah, ya brought in one of our flyers! As promised, here's some Trader's Tender ya can use in our shop.\n\nIf ya want to keep earning tender, then check out the Traveler's Log portion of the Adventure Guide to see what activities ya can do. Complete enough activities and we'll reward ya with tender and other amazing items." }
WordHunterWoW_QuestEN[66960] = { title = "Klozicc the Ascended", description = "", objectives = "" }
WordHunterWoW_QuestEN[66961] = { title = "Join the Hunt", description = "", objectives = "" }
WordHunterWoW_QuestEN[66962] = { title = "[DNT] 10.0 Explorers - Ch1 - Fake Quest Requirement (SMART)", description = "", objectives = "" }
WordHunterWoW_QuestEN[66963] = { title = "Out For Delivery", description = "I tried to tell Vevesi that I could pull the wagon out of the mud.\n\nBut, no, he insisted on using magic to get it out... And now look what he's done.\n\n<Hauler Bennet sighs.>\n\nWhile I try to talk sense into Vevesi, can you run up the hill to the Basecamp and let Cataloger Wulferd know that he might need to ship another crate of camera supplies over from Boralus?", objectives = "Tell Cataloger Wulferd in the nearby basecamp that his supplies won't be arriving anytime soon.", completion = "<Cataloger Wulferd laughs.>\n\nNot a problem. I packed plenty of spare film in my carry-on." }
WordHunterWoW_QuestEN[66964] = { title = "Artifacts in the Wrong Hands", description = "We've got a myriad, no, an incalculable number of problems here!\n\nOh man, where to start! \n\nThe Kirin Tor uncovered a Sundered Flame plot. They're after an artifact called \"Valthrux\".\n\nIt's immensely powerful and... sentient? That's an exponential increase in danger if you're keeping track.\n\nOne Alia Sunsoar went south with a pair of tuskarr to investigate the Sundered Flame. She should have been back by now.\n\nPlease find her and stop the Sundered Flame from acquiring the artifact!", objectives = "Locate Alia Sunsoar in the Lost Ruins within Azure Span.", completion = "Finally, a stroke of good luck! We could really use a hand here." }
WordHunterWoW_QuestEN[66968] = { title = "Pruning The Pack", description = "<Nesingwary gestures to the side of the path.>\n\nSee those imprints in the snow? \n\nYeti tracks. \n\nSomething must of riled them up to hunt this close to the road. See if you can't hunt down their pack leader. We don't want them to start ambushing travellers! \n\nIf he's a particularly mean brute, collect his head. That should dissuade the others.", objectives = "Hunt down Yetor near Ronin's Shield.", progress = "Careful, friend. Yeti hunt in packs.", completion = "Whoa! Talk about a mean mug... I'm glad you made it back alive! \n\nAs unsavory as making an example of it is, keeping the yeti off the roads is best for them.\n\nAnd us." }
WordHunterWoW_QuestEN[66969] = { title = "Clans of the Plains", description = "While you wait for the emissary to arrive, Sansok Khan is interested to hear how meeting the clans went. She sent me to find you and tell you to meet her in the center of Maruukai to discuss.", objectives = "Report to Sansok Khan in Maruukai.", progress = "<Sansok Khan smiles at you, welcoming you back.>", completion = "<As Sansok Khan signs, Okir vocalizes for her.>\n\nWhile there are many clans of various sizes throughout the plains, Shikaar, Teerai, Ohn'ir, and Nokhud hold the most power." }
WordHunterWoW_QuestEN[66970] = { title = "Ty'foon the Ascended", description = "", objectives = "" }
WordHunterWoW_QuestEN[66971] = { title = "The Face of Death", description = "Tell me, friend. Have you ever seen the face of death?\n\n<Nesingwary pauses for dramatic effect.>\n\nWhat am I saying? Of course you have.\n\nDeath, after all, has many faces. \n\nI've heard tell from the Imbu tuskarr that one of its faces lives up in these hills. To even say its name is to invite a violent, frigid death:\n\nFrostjaw.\n\n<Nesingwary looks around warily.>\n\nWell, now you have to hunt it--for my sake at least!", objectives = "Hunt down Frostjaw north of Winterpelt Hollow.", progress = "Don't dawdle about. I'm in mortal danger now!", completion = "You're alive!\n\nHa ha! I can't imagine what kind of fight that beastie put up when you cornered him. Azure Span's a little safer thanks to you!\n\nDo me a favor and check on my da..." }
WordHunterWoW_QuestEN[66972] = { title = "Old Stonetusk", description = "I have a grim task for you, {name}. Not every kill is a measure of skill. Some are measures of kindness. \n\nThere's an old bull mammoth wandering the forest east of Camp Antonidas. I saw him from a distance awhile back, and I hear his sad trumpeting every so often. Clearly he's in great pain.\n\nHe's started crashing blindly through the undergrowth, and I'm worried he's becoming a danger to others. \n\nIt'd make my old heart glad if you put a fellow weary soul to rest. Bring me his tusk so we can honor him.", objectives = "Put Old Stonetusk down near Camp Antonidas.", progress = "Is it done?", completion = "This brings me no joy.\n\nBut I'll hang his tusk in a place of honor.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[66987] = { title = "[DNT] 10.0 Explorers - Ch2 - Fake Quest Requirement (SMART)", description = "", objectives = "" }
WordHunterWoW_QuestEN[66989] = { title = "Helpful Harvest", description = "", objectives = "" }
WordHunterWoW_QuestEN[66997] = { title = "Nursery Direction", description = "I'm so grateful that Lasztak has accepted the Calling of a Whelptender! Especially given how many of the precious little things are teething right now.\n\nBeyond that, the nursery gardens are admittedly facing challenges. The whelps are stressed and the tenders are--well, more stressed than usual.\n\nPlease, whenever you have a spare moment, find me in the gardens below. We could use your help as well!", objectives = "Meet Vaeros in the gardens of the Ruby Life Pools.", completion = "Thank goodness you're here! You may have noticed the bees on your way in. We must do something about them!" }
WordHunterWoW_QuestEN[66998] = { title = "Fighting Fire with... Water", description = "In all my years of tending to the lava elementals, I have never seen them act like this! We can barely keep them contained to the cave.\n\nDo you have a minute to spare? We'll hold the exit while you thin their numbers inside.\n\nHere, take this bottled water elemental with you.\n\nI always carry a few spare bottled water elementals when I'm looking after the lava elementals. Natural enemies make for good distractions!", objectives = "Kill lava elementals in the Erupting Cavern.", completion = "Thank you for a moment's respite. A caretaker's work is never done." }
WordHunterWoW_QuestEN[67002] = { title = "Azure Span Slalom", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[67003] = { title = "Azure Span Slalom - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[67004] = { title = "Good Things in Large Boxes", description = "Our efforts have created everything we need to open an Earth-Warder's Vault. There are several beneath the Citadel. Locate one and I will reward you.\n\nI have crafted chains to help move it. If you bring the Vault here, we can share in the riches.\n\nWatch for the Vault being moved, as I have dispatched others to find them as well.", objectives = "Locate an Earth-Warder's Vault for me. If you bring it back, we can share in the loot.", progress = "Have you found the Vault?", completion = "Excellent work, <name>. With any luck we can open additional Vaults soon!" }
WordHunterWoW_QuestEN[67005] = { title = "How to Train a Proto-Drake", description = "", objectives = "" }
WordHunterWoW_QuestEN[67006] = { title = "Quenching the Flame", description = "", objectives = "" }
WordHunterWoW_QuestEN[67007] = { title = "Archival Assistance", description = "<The crisp, clean lettering, written with an elegant touch, fades quickly into the parchment's wet, smudged ink and a smell reminiscent of spilled, fermented beverage.>\n\nADVENTURE SEEKERS, ARCHIVAL ENTHUSIASTS--\n\nThe archives call to those who seek answers, yearn to discover, and those who wish to reveal secrets of the past, and perhaps, the future!\n\nThis request is not for the faint of heart, nor those of wavering will.\n\nOnly curious and brave adventurers need apply.\n\n- Kemora", objectives = "Speak with Kemora at the archives in Valdrakken.", completion = "<Kemora turns gracefully to address you. Before speaking, with a smile upon her face, her eyes follow your being from the ground upon which you walk moving upward, slowly, until your eyes meet in a calming gaze.>\n\nIs it answers you seek as well, <race>?\n\nI am ready to speak if you are up for the challenge." }
WordHunterWoW_QuestEN[67009] = { title = "Hornswog Hogwash", description = "", objectives = "" }
WordHunterWoW_QuestEN[67010] = { title = "Boiling Over", description = "", objectives = "" }
WordHunterWoW_QuestEN[67011] = { title = "Tale of an Adventure: Molten Core", description = "So, you want to tell me a story of your adventure?", objectives = "Tell Elder Poa of your adventures in Molten Core." }
