WordHunterWoW_QuestEN[67014] = { title = "Gorlocs No More-locs", description = "", objectives = "" }
WordHunterWoW_QuestEN[67015] = { title = "Forging the Answer", description = "", objectives = "" }
WordHunterWoW_QuestEN[67024] = { title = "Smoldering Reinforcement", description = "", objectives = "" }
WordHunterWoW_QuestEN[67026] = { title = "Hold the Shrine", description = "", objectives = "" }
WordHunterWoW_QuestEN[67027] = { title = "Death's Shadow", description = "", objectives = "" }
