WordHunterWoW_QuestEN[67032] = { title = "Vakthros Ascent - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[67033] = { title = "Assemble the Defenses", description = "The Primalists have been hunting the Kirin Tor since we arrived in the Azure Span. They detest our practice of arcane magic.\n\nI'll send word to Kalecgos to return from the Azure Archives. In the meantime, we need to hold them off.\n\nIt seems one of our main arcane defenses was destroyed in their initial attack. Bring the pieces back to me and I can reassemble it.", objectives = "Recover 3 pieces of the Arcane Blaster.", progress = "Do you have the pieces? I remember exactly how it was assembled, so repairing it should not be a problem.", completion = "Excellent. I'll begin the ritual to fix this in a moment." }
WordHunterWoW_QuestEN[67034] = { title = "Of Wind and Water", description = "To the east is a great dragonspring which serves as a nesting area for wild eagles. The feathers they shed still contain their magic for quite some time and are used in many rituals.\n\nThe area also hosts raging spirits of the elements, and their cores are of some use as well.\n\nBring a collection of both back to me - and remember that the eagles are sacred, I will not accept feathers that are gathered from their harm.", objectives = "Collect reagents from the Roaring Dragonsprings.", progress = "Have you found everything?", completion = "These reagents will be used to initiate new members into our tribe. I will repay this debt." }
WordHunterWoW_QuestEN[67035] = { title = "Preservation of Knowledge", description = "Greetings, {race}. I am Althanus. I wish we could have met in a less... chaotic time.\n\nWe were helping the Kirin Tor study the history of this place just a few moments before the Primalists attacked.\n\nI fear several tomes may still be out there, at risk of being destroyed in this dreadful assault.\n\nPlease, you must recover these tomes! If they're destroyed, the history of this place will be lost.", objectives = "Find 4 Ancient Tomes scattered around Camp Antonidas.", progress = "Do you have the tomes?", completion = "What a relief! To lose all that knowledge... I could not bear the thought." }
WordHunterWoW_QuestEN[67036] = { title = "Wrath of the Kirin Tor", description = "I've assembled the pieces of the device you recovered. \n\nPlace it near Khadgar and use it to repel the Primalists! \n\nWe just need to hold out a little longer until Kalecgos arrives.", objectives = "Use the Arcane Blaster to help Khadgar defeat the primalists.", progress = "Just hold out a little longer...", completion = "I am relieved that the attack was repelled... but it seems we will need to figure out a plan to help Kalecgos in the Azure Archives." }
WordHunterWoW_QuestEN[67039] = { title = "An Amazing Journey", description = "A few of the clan's pets ended up getting lost along the last journey between camps. They're not hunting animals so I doubt they can take care of themselves properly out there!\n\nDo you think you could go search for them? They may not be hunting partners, but they're important members of the clan regardless!", objectives = "Find the missing animals.", progress = "Did you find them? Their partners are becoming increasingly concerned.", completion = "They all returned before you. Thank the winds!" }
WordHunterWoW_QuestEN[67044] = { title = "Tale of a Hero: Yanikk", description = "Let me tell you the tale of Yanikk.", objectives = "Listen to the tale of Yanikk." }
WordHunterWoW_QuestEN[67047] = { title = "Warm Away These Shivers", description = "I believe the plant you're looking for has a fine, narrow stem and red leaves all about it.\n\nYou'll be hard-pressed not to run into any of those dastardly crawlers while you're collecting flowers though. I'd advise you steer clear when you can, or ready a sharp weapon when you can't.\n\nAnd let your dragon friend know they can repay me in a cup or two of the stuff next time I'm in the city.", objectives = "Collect 12 Coldsnap Sagittate leaves.", progress = "Steeped just right, coldsnap fills the drinker with warmth for hours to come.", completion = "Ah! This is most certainly the Coldsnap Sagittate! My nostrils are exhilarated! \n\nExcellent work, <name>! I am positive our venerable guests will be gargling your praises with each sip of warmth imbibed. Let us not forget to do so with some of these delicious little cakes Morsel and Flemthroat made as well!" }
WordHunterWoW_QuestEN[67050] = { title = "Frostbite: Causes and Symptoms", description = "Elements live in the totems, {race}. Release them and break the ice. Free your tuskarr friends!", objectives = "Place the totems to release the trapped tuskarr hunters in the Azure Span.", completion = "You did WHAT!? Bah... doesn't matter for now. This isn't over just yet." }
WordHunterWoW_QuestEN[67051] = { title = "Dragon Eyes", description = "We know the djaradin will attack us directly, but I'm worried about other dangers out there as well. Ones that aren't so obvious.\n\nI have dispatched three dragons to survey the surrounding area and pinpoint any potential threats.\n\nMeet with each of them. Collect their reports for me. Once you have gathered this information, return to me so we can best prepare for what the djaradin are planning.", objectives = "Speak with Baskilan, Vazallia, and Zepharian in the nearby areas.", progress = "What have you discovered?", completion = "Thanks to you, we will be better prepared for anything the djaradin plan to throw at us.\n\nWe will always keep our eyes open." }
WordHunterWoW_QuestEN[67053] = { title = "Give Peace a Chance", description = "Light be with you, {name}.\n\nThis expedition is under the protection of both the Horde and Alliance. Our orders are clear: give aid to any members of the expedition, regardless of their other allegiances.\n\nThe Horde's representatives, Warlord Grimaxe and her daughter Shuja, stand guard on the other side of camp.\n\nI fought with Warlord Grimaxe against the scourge. She is noble and will serve this expedition well.\n\nGo offer her your assistance. Show her that the Alliance honors its commitments.", objectives = "Introduce yourself to the Horde representatives.", completion = "<Warlord Breka Grimaxe salutes your approach.>\n\nCaptain Garrick proves her honor once more by sending you to me." }
WordHunterWoW_QuestEN[67062] = { title = "Cascading Conflict", description = "", objectives = "" }
WordHunterWoW_QuestEN[67063] = { title = "10,000 Years of Roasting", description = "Spices? Oh! Ya must be with da big 'ol dragon cook. Da one with a little duck chef on her head.\n\nDjaradin collect up a powder, Spicy Lava Spices, off da fiery elementals down below. \n\nDon' you look at me like dat! It's what da Djaradin be calling dem, not me!\n\nGood luck down there. I wouldn't go alone if was you.", objectives = "Collect 30 Spicy Lava Spices.", progress = "I wish I could talk with one the Djaradin cooks. They must have their own rich culinary history! If only it did not include eating my fellow kin...", completion = "Do those not smell absolutely marvelous!\n\nLet us give these meats the Aspect treatment! We will have premium cuts marinated, roasted, skewered, and served straight to your mouth. You'll swear your taste buds were never satisfied before!" }
WordHunterWoW_QuestEN[67064] = { title = "Rambling Delight", description = "Oh, Rumiastrasza! Myself and the dryad sisters, Celina and Felina, had a lovely evening cooking for her.\n\nThe kelp we ate is a unique strain called Glimmering Ramblekelp. Swarms of frillfish devour them all along the coast. I wouldn't be surprised if they attack you while you're plucking their food from the sea floor.\n\nPlease give the chefs my best when you see them. They're always welcome here in our sanctuary.", objectives = "Collect 10 Glimmering Ramblekelp Bulbs.", progress = "I have been tantalized by the smell of fresh berries all day. It has been a most incredible afternoon, <name>.", completion = "Yes! Glimmering Ramblekelp! The delicious, vegetal taste from the Shady Sanctuary.\n\nI must say, the aroma of it brings me back to my youth. I became friends with a most humble guard of an Emerald Dream portal, and was enchanted by the variety of strange ingredients growing near his post. This kelp gives off the same, sweet hints of that glorious realm I remember from back then!\n\nThank you, <name>. You have gifted this old chef a side of nostalgia with her meal today." }
WordHunterWoW_QuestEN[67065] = { title = "Future-Fresh Fungi", description = "A delicious mushroom? Alternate futures are not pantries to be raided for midmorning snacks.\n\nBut still... I would be lying if I said I had never dreamed of eating Rumi and Morsel's cooking again.\n\nVery well! You have my permission to pass through the portal, though I advise you to find others to travel with.\n\nMy wardens have mentioned these dark mushrooms to me before. Apparently, they never stay in the same place for very long. Make of that what you will.", objectives = "Capture 7 Time-Blasted Trufflettes from the Primalist Future.", progress = "Morsel went so long with telling me about this amazing fungi!\n\nWhat else are you keeping from me, you wonderful little chef, you!", completion = "These... are... MAGNIFICENT!!\n\nNever have I seen such incredible fungi! I must be sparing in my use of these. Or not! Who knows!\n\nI am also glad to hear that the good Captain Sinjoirmi is faring well. It would please me beyond measure to cook for her again in the future." }
WordHunterWoW_QuestEN[67066] = { title = "Delights to Delve For", description = "Rumi and Morsel?\n\nGosh, that was quite a long time ago now. Eating a fish with a dragon and duck chef duo sounds like the beginning of a tale Elder Poa might tell for the younglings. We'd be hard-pressed to forget such a happening!\n\nThe fish was a Savory Deviant Dealfish, a top Tuskarr favorite! They're rare, but found just off the coast here.\n\nFair warning - it's azuretooth mating season. Those bloodthirsty fiends will take a chunk out of you for messing with their favorite snack.", objectives = "Collect a Savory Deviant Dealfish.", progress = "Morsel is an incredible angler. He does not even require a fishing rod!", completion = "Oooh hoo! You smell that? Nothing fresher than fresh-caught right from the sea!\n\nMorsel and I simply must spend another summer with the Iskarra. There is simply no better way to learn more about an ingredient than with the artisans that source them." }
WordHunterWoW_QuestEN[67067] = { title = "Navigating the Leapmaize", description = "There's a dragon chef in Valdrakken? Truly? I'll have to ask her to try my arclight bisque! It's an old family recipe.\n\nI know the plant you speak of. It grows around streams here, but it's caused some problems.\n\nThe stalks of leapmaize seem to be a natural feeding ground for beetles and small salamanthars, which are, in turn, natural prey of the hornswogs. That's fine if you can spot them out in the open, but there's a few here that are incredibly stealthy.\n\nI'd watch my back if I were you.", objectives = "Collect 15 stalks of Wild Leapmaize.", progress = "I met Morsel while he was roasting an enormous hornswog over an open pit of coals. The mangy leaper had followed him from the Hollows all the way to the Life Pools before he and a few guards worked together to defeat it.\n\nOf course, he shared the scrumptious meal with all of them in return!", completion = "I tell you, <name>, the flavors produced by this leapmaize are truly revolutionary! Morsel says it has something to do with the active lava throughout the Shores and the unique soils it creates. \n\nI have found it best to believe in him in most all matters, culinary and beyond." }
WordHunterWoW_QuestEN[67068] = { title = "Anything But a Breeze", description = "Breezehunters?! Oh, those falcons have been a problem. Just the other day, our stable master, Marren, almost fell to her death trying to tame one.\n\nShe's pretty proud, so she blamed it on the breezehunter itself. Told me that if it didn't think her eggs were being attacked, it wouldn't have been so aggressive as to bully her off the cliff's edge.\n\nI guess that means that you might find the eggs you're looking for out there? It was to the east, just around the mountainside here.", objectives = "Collect a Breezehunter Egg.", progress = "Looks like you made it back with a few scrapes as well as the egg!\n\nWorry not about your pride or anything of the like! Even a dragon of my size wouldn not want to take on a nest of them alone.", completion = "Glorious!\n\nMorsel and I will whip up a cake so divine your palette will swear it was in the afterlife. Imagine an experience that is lighter than air, tangy like a sunfruit, but with a crisp texture.\n\nPrepare to feel like a breezehunter yourself!" }
WordHunterWoW_QuestEN[67071] = { title = "What a Long, Sweet Trip It's Been", description = "{name}! Just who Morsel and I were looking for!\n\nFrom the bottom of both of our winged-hearts, we thank you dearly.\n\nWe started The Ruby Feast to share the Isles' culinary culture with all of Azeroth's races, and to learn from them too. We had you running from one end of our beloved continent to another, but you helped bring our dream vision of these gatherings to each honored visitor and guest here.\n\nAs friends, we would like to give you a gift. Grab the top journal from our hoard behind the cauldron.", objectives = "Speak with Rumiastrasza.", progress = "Our hoard is just behind the cauldron.\n\nNot to worry though, we lowered the sealing enchantment and deathly magical traps for you!", completion = "Catch a fish for a mortal, they will eat for a day.\n\nTeach a mortal to cook, they will eat for a lifetime.\n\nGive a mortal your most prized recipe, they will think of you each time they make it. At least we hope you do.\n\n<Morsel and Rumi smile at you like only good friends can.>\n\nCome back any time, <name>! The meal is on us!" }
WordHunterWoW_QuestEN[67073] = { title = "Red Dawn", description = "We've come so close to recovering our powers... should Raszageth succeed before our powers return, I fear that the timeways will bend to a dark future for all of Azeroth.\n\nWe must not allow this to occur, {name}!\n\nHurry, you must find and aid Alexstrasza before all is lost!", objectives = "Locate Alexstrasza.", completion = "Razageth and her allies must be stopped!" }
WordHunterWoW_QuestEN[67074] = { title = "The Gift of Silver", description = "Shortly before his passing, Keeper Tyr gifted us with a dragon scale forged of purest silver. We kept it in the vaults of Valdrakken during our absence, but I believe it is time to share it once more.\n\nThough we have no idea the purpose for this memento, it has always been a symbol of unity and friendship to us. As a true ally to dragonkind, we would like to share it with you. Speak to me when you are ready, {name}.", objectives = "Speak to Alexstrasza to reveal Tyr's gift.", progress = "What do you make of this, <name>?", completion = "I thank you, <name>, for being an ally we can trust with a matter this important." }
WordHunterWoW_QuestEN[67075] = { title = "The Magic Within", description = "Intriguing. There are many mysteries living within this citadel that no one, save Keeper Tyr himself, understand. If we are to unlock this further we shall have to explore more of Tyrhold. \n\nI believe that the scale will draw out secrets stored within this place.\n\nHowever. there is one complication. The guardians of Tyrhold are still... unstable. They may take your exploration as disruption and try to interfere. Take this conduit. It will help you should the guardians prove troublesome.", objectives = "Draw out hidden magic from consoles around Tyrhold to uncover the mystery of the Silver Scale.", progress = "What have you discovered?", completion = "This spark feels familiar. I was not aware of anything like it here in Tyrhold.\n\nMost curious." }
WordHunterWoW_QuestEN[67076] = { title = "A Spark of Discovery", description = "Though this spark is of peculiar origin, I sense it is familiar. I am not sure of its purpose, but I believe it may lead to your next step in unraveling this mystery.\n\nFollow it and see if you can learn more of its purpose, while I see what else I can discover in the meantime.", objectives = "Investigate the Titan Spark in Tyrhold.", completion = "I sensed a great surge of magic emanating from Tyrhold all the way from Valdrakken. Its source must be this spark you have found. \n\nI wonder what it could mean..." }
WordHunterWoW_QuestEN[67077] = { title = "Memories of the Past", description = "This place is where we last saw our friend, Tyr.\n\nWe did not understand the circumstances by which he had to leave, only that it was for something important.\n\nThough it may be difficult for our hearts to bear, I believe this spark called us here to witness that time once more. With Nozdormu's aid we may relive that moment and see if there was some other clue Tyr left behind for us.", objectives = "Speak to Nozdormu to witness the memory of the past.", progress = "Forgive me, <name>. This is still emotional for me.", completion = "Though it is a sad memory, I am grateful for the chance to hear his voice again... if only through time.\n\nThank you for bringing us here, <name>." }
WordHunterWoW_QuestEN[67078] = { title = "Parting Instructions", description = "<The echo speaks with an ancient voice.>\n\nTo my dear friends, I apologize for my sudden departure.\n\nBut, I promise that you are not without my aid. I know that you have come upon the time of great need, but to ensure this gift does not get misused I must ask you to perform a series of tasks.\n\nThe first is simple: reactivate the forge within Tyrhold. The Silver Scale is the key.", objectives = "Place the Silver Scale at the forge in Tyrhold.", progress = "You have a means to activate the forge?", completion = "It appears activating the forge is not so simple as you were led to believe." }
WordHunterWoW_QuestEN[67079] = { title = "Hard Lock Life", description = "The security in the forge is stricter than in any other area of Tyrhold. This will be quite a challenge for us, {class}.\n\nOnly certain units around the citadel have the capability to bypass this security, and the protocols to unlock require more than one code in case of corruption.\n\nThese units will not want to relinquish their overrides, you may have to take them by force. Be careful, {name}.", objectives = "Retrieve the Primary Security Disc and Secondary Security Disc within Tyrhold.", progress = "I hope we have not disrupted Tyrhold greatly. May the Keeper forgive us.", completion = "Excellent, <name>. With these we can override the lockdown and complete the task Tyr left behind." }
WordHunterWoW_QuestEN[67080] = { title = "Artisan's Supply: Dragon's Alchemical Solution", description = "Are you looking for work, alchemist?\n\nThe Artisan's Consortium has reached out to me with a \"crafting order\" for my alchemical solutions. I am as curious as the next dragonkin to find out more about these business practices, but I am simply too busy.\n\nPerhaps this is an opportunity for you, my apprentice. Create some alchemical solution by reclaiming your earlier concoctions, and bring it to Haephesta, just down the path.", objectives = "Use the Reclaim Concoctions recipe to create 2 bottles of Dragon's Alchemical Solution for Haephesta at the Ruby Lifeshrine.", progress = "How can the Artisan's Consortium help you today?", completion = "A delivery! Excellent. Good doing business with you, <name>." }
WordHunterWoW_QuestEN[67081] = { title = "Halls of Infusion: An Infusion of Materials", description = "<The image of Tyr speaks again.>\n\nYou have reactivated the forge. The next task will not be as simple.\n\nTranscribed within the scale are schematics for something I require you to forge. I have entrusted one of my watchers, Irideus, with the necessary materials for this task. They are of special origin, and only few of them are left in existence.\n\nSeek Irideus within the Halls of Infusion, where I hope his careful watch has kept the facility operating in an orderly fashion.", objectives = "Retrieve 10 Ancient Titansteel Ingots and defeat the Primal Tsunami in the Halls of Infusion.", progress = "Once you have retrieved the required materials you will be able to proceed.", completion = "I trust everything was in order within the Halls of Infusion and that Irideus is doing well.\n\nNow for the next task." }
WordHunterWoW_QuestEN[67084] = { title = "The Silver Purpose", description = "<The echo of Tyr activates to your presence.>\n\nYour task is at hand, my friends.\n\nCast the ingots into the fire and activate the forge. I have prepared the necessary procedures for you already.\n\nThe Silver Scale holds the schematic. Its purpose shall reveal itself to you.", objectives = "Place the Ancient Titansteel Ingots into the forge and finish the task Tyr has left behind.", completion = "I cannot find the words to describe our gratitude to you, <name>! You have returned our long-lost friend to us!\n\nIn the absence of any further instructions he left, perhaps we can eventually find out what we must do next to restore his true self.\n\nIf we can..." }
WordHunterWoW_QuestEN[67093] = { title = "An Anomalous Shrine", description = "My research team located a strange sanctum nearby. We were able to make out some writing on the outside of it--titan runes, to be exact--which we believe reference Aman'Thul the Highfather, leader of the titans, in several places.\n\nWe tried to inspect more closely but must have triggered the sanctum's defenses. A massive sand amalgam blocked us off and we narrowly made it out alive.\n\nWe aren't certain what it's protecting, but it must be important. Can you investigate?", objectives = "Find a way to collect the relic hidden inside the Sand-Lost Sanctum, then return it to Nozdormu at the Seat of the Aspects in Valdrakken.", progress = "This land is a sleeping giant. We ought to wake it with requisite caution.", completion = "<Nozdormu peers searchingly at the sphere as you hand it over. The sands inside brighten and swirl under his touch.>\n\nI had thought this to be lost in this timeline. Nothing ever remains so, it seems." }
WordHunterWoW_QuestEN[67094] = { title = "A Dryad's Work Is Never Done", description = "It is wonderful to see Valdrakken so lively again, but there are so many things that have wilted under thousands of years of neglect - not the least of which are all of the adorable little city critters! Alas, we don't have enough dryads to go around tending to them all. \n\nSay, how would you like to be appointed Honorary Valdrakken Dryad? Some of the city's cutest little friends have gone far too long without their preferred snacks. Won't you help me tend to them?", objectives = "Help Thalendra feed the many small animals of Valdrakken.", progress = "Tut tut, Junior Dryad! Those critters won't feed themselves!\n\n...Or, well, they could I suppose. But where's the fun in that?", completion = "Oh, how wonderful! I bet they all have smiles on their cute little faces, beaks, snouts and whatnot. \n\nThere is one more critter that needs our help, though, and I fear the situation is rather dire." }
WordHunterWoW_QuestEN[67095] = { title = "Flowing Forest Flight", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[67096] = { title = "Flowing Forest Flight - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[67099] = { title = "Dragon Eyes", description = "We know the djaradin will attack us directly, but I'm worried about other dangers out there as well. Ones that aren't so obvious.\n\nI have dispatched three dragons to survey the surrounding area and pinpoint any potential threats.\n\nMeet with each of them. Collect their reports for me. Once you have gathered this information, return to me so we can best prepare for what the djaradin are planning.", objectives = "Speak with Myridian, Zepharion, and Evorian in the nearby areas.", progress = "What have you discovered?", completion = "Thanks to you, we will be better prepared for anything the djaradin plan to throw at us.\n\nWe will always keep our eyes open." }
WordHunterWoW_QuestEN[67100] = { title = "A Gift for Miguel", description = "{name}, could you do me a favor?\n\nI want to get a gift for my husband, Miguel.\n\nHe means so much to me, but I've been so busy lately that I haven't had time to make him anything. \n\nCould you help me make him something high quality?", objectives = "Talk to Thomas about quality, then gather 3 Fiery Spirits near Hornswog Hollow for Miguel's gift.", progress = "Miguel will love this!", completion = "Fantastic! You're so swell!\n\nHere, take this reagent bag as thanks. You can hook it into that extra spot on your belt. Oh, and if you need even more space, a skilled tailor can make you an even larger one." }
WordHunterWoW_QuestEN[67111] = { title = "The Ailing Apprentice", description = "This mission was a mistake from the beginning. Alia Sunsoar enlisted our aid to keep the Sundered Flame from acquiring a dangerous artifact. We had tracked it down to these ruins.\n\nBut the Sundered Flame beat us here and the area is infested with ice spiders. Alia was badly poisoned, and I fear she will not last long without the antidote.\n\nI can make it, but I need venom glands from the nearby spiders. I'm afraid to leave her. Will you find some for me?", objectives = "Collect 5 Frozen Venom Glands.", progress = "Do you have the venom glands I asked for?", completion = "Ah, wonderful! With these venom glands, I can brew an antidote for Alia. She'll be feeling better in no time at all." }
WordHunterWoW_QuestEN[67113] = { title = "Excavation Emergency", description = "", objectives = "" }
WordHunterWoW_QuestEN[67137] = { title = "Professionally Equipped", description = "Say, I heard from Haephesta that you're a working artisan as well.\n\nWe'd like to get you set up with some professional equipment. Free of charge. That's what business partners are for, right?\n\nTalk to our tailor, Mahra Treebender, to get fitted.", objectives = "Speak with Mahra Treebender.", progress = "Now, let us get you equipped.", completion = "Here is your new equipment! Try it on!\n\nYou can equip this above your profession recipes.\n\nOh, and if you want more, look to your fellow crafters if you don't know how to make equipment yourself." }
WordHunterWoW_QuestEN[67142] = { title = "Wyrm Food", description = "It's hungry work, defending and fighting for the Obsidian Citadel, and dragons can eat a great deal. We need to replenish our stores.\n\nLurking beneath the hardened lava, squirming through the magma, are some very tasty worms. This may not appeal to you, but to a hungry dragon, they are delicious.\n\nTake our servant Gulchak and use his pointer to direct him towards disturbances in the lava. He will attract the worms for you to harvest.", objectives = "Collect Lava-Charred Flesh from Crust Lurkers in the Emberflow.", progress = "Have you found anything good to eat?", completion = "<Voraxian taps his teeth together approvingly.>\n\nThank you. This will go a long way toward keeping our kin fed and healthy. We do not fight for our future on an empty stomach." }
WordHunterWoW_QuestEN[67143] = { title = "To Give One's Heart", description = "Now that we have the elemental essence gathered, do you think you could put them in this bottle?\n\nIt's a simple recipe that you can craft the same way as any other recipe.\n\nIf you lost, or use up the high-quality reagents, you can always get more from the elementals at Hornswog Hollow.", objectives = "Craft a Heart in a Bottle |A:Professions-Icon-Quality-Tier3-Small:20:20|a with any crafting profession.", progress = "Hello, can I help you?", completion = "Wow, this is so sweet! Oh, Thomas is just a darling.\n\nLook at this. So well-crafted. Did you help with this? If so, thank you, a thousand times thank you.\n\nGive Thomas my sincerest thanks, would you?" }
WordHunterWoW_QuestEN[67154] = { title = "Entropic Remnants", description = "When an entity passes through the timeways, the sands of time can sometimes accumulate on their body. \n\nTypically, this sand dissipates in short order--but sometimes, the entropic fluctuations inherent in time travel can cause that sand to vitrify. In these cases, it becomes rather difficult to remove. I've ruined several good pairs of shoes this way.\n\nVitrified sand can be quite powerful for our purposes. It would be in best interest to reclaim as much of it as we can.", objectives = "Collect 8 Vitrified Sand from creatures in the Shifting Sands.", progress = "Have you had any luck? It's usually somewhat rare, but we've been seeing more of it lately.", completion = "An unexpectedly large haul. Perhaps those rifts are causing more trouble than we calculated." }
WordHunterWoW_QuestEN[67167] = { title = "It's Time To Duel!", description = "With my deck back, I can focus on recruiting new members to my club! I was thinking about asking the dracthyr...\n\nOh, that is another thing you can help me out with, {name}! \n\nI am going to be a bit busy trying to get other dragons to join and I really want to get the dracthyr involved.\n\nDo you mind talking to them for me? Be warned; many of them have never played before.", objectives = "Challenge 8 dracthyr to a game of Hearthstone.", progress = "How is the recruiting going?", completion = "Wonderful! Thanks so much for all your help <name>! With the new interest in Hearthstone I am sure we will get approval for the club!" }
WordHunterWoW_QuestEN[67173] = { title = "Thieving Gnolls", description = "", objectives = "" }
WordHunterWoW_QuestEN[67174] = { title = "Arcane Detection", description = "Greetings! I am Miva Star-Eye, and I am conducting arcane investigations in this area. \n\nThe Azure Span has magic all around it. Some of it is benign... while some can be quite dangerous. \n\nI've been tasked with ensuring no arcane energies reside in anything the tuskarr possess. \n\nWe already had one incident in Camp Antonidas of a fishing box spontaneously combusting! \n\nCan you take my detector and examine a few objects here? I need to continue speaking with Julk over here.", objectives = "Investigate tuskarr objects in Khuri's Fishing Spot for signs of arcane magic.", progress = "Let's hope there's nothing out of the ordinary here.", completion = "A toy boat that's a magical time bomb?\n\nOh boy." }
WordHunterWoW_QuestEN[67175] = { title = "How To Stop An Exploding Toy Boat", description = "I am loathe to part a child from their toy, but it would be a great value to the Kirin Tor to study how it absorbed so much arcana.\n\nThen again... I do not want to slight our new tuskarr allies. I do have a wand that could dispel the magic...\n\nLet's speak with Toolk's mother, then decide what to do.", objectives = "Speak with Toolk's mother, then recover the toy boat.", progress = "The wand should handle any dispelling if we're not too late.", completion = "We did the right thing today. There will be more magical oddities to research, but this girl will not get more gifts from her lost father." }
WordHunterWoW_QuestEN[67177] = { title = "WANTED: Gorger", description = "If you are going to be amongst the tuskarr, you would do well to lend a hand! \n\nAs of late, a beast we call Gorger has been making its home nearby. \n\nMore of its kind seem to be migrating to this area. This is something we can take advantage of.\n\nKill the Gorger and bring me its horns. We'll need them for building supplies to expand this outpost.", objectives = "Slay Gorger and recover its horns.", progress = "Do you have the horns?", completion = "Fine work! We'll put this aside for our future building plans. \n\nIt is concerning Gorger and its kind have migrated down here, but we will make the best of it." }
WordHunterWoW_QuestEN[67178] = { title = "White Eyes, Blue Dragon", description = "{class} can you make sure the match happens as fairly as possible?\n\nSetogosa is known for bending the rules to suit her whims. \n\nI would not wish to see Yumadormu lose due to cheating.", objectives = "Help Yumodormu defeat Setogosa.", completion = "Thanks for helping me out back there! If it weren't for you I don't think I'd have been able to beat Setogosa.\n\nSetogosa will be fine, I'm just going to wait for her to cool down a bit before I reverse the reversal." }
WordHunterWoW_QuestEN[67220] = { title = "10.0 [DNT] [GAMEPLAY TEST] - [SPAWNTRACKING] (JSS)", description = "", objectives = "" }
WordHunterWoW_QuestEN[67221] = { title = "A Head for Metal", description = "To fully utilize the potential of the Earth-Warder's forge, you must learn the basics of creating Obsidian Seared Alloy. Only then can you follow in the footsteps of Neltharion's greatest smiths.\n\nBring me a piece of Crystallized Draconium found deep within the Cindershard Seam. Then I shall gift you the knowledge you desire.", objectives = "Collect 1 Crystallized Draconium inside the Cindershard Seam.", progress = "Have you gathered what I require?", completion = "Your success has earned you this knowledge." }
WordHunterWoW_QuestEN[67222] = { title = "Darkened Clouds", description = "The Primalists have infected Windsong Rise with their nonsense teachings. Our kin there are foolish to entertain their ideas.\n\nIf we assist with clearing this sacred ground of their presence, perhaps the other clans will come to our aid in time of need. Do you think you could assist?", objectives = "Clear out the Primalist presence from Windsong Rise.", completion = "Thank you." }
WordHunterWoW_QuestEN[67295] = { title = "That's My Specialty", description = "So, you've started taking up a specialization, eh? 'Tis a glorious thing to have an exclusive skill you can call your own.\n\nAs a member of the Artisan's Consortium, I would be delighted to help you on your journey to honing your specialization.\n\nHave you a minute to listen to my words of wisdom, and perhaps learn something to help you on your adventures?", objectives = "Talk to Miguel Bright about a professional specialization.", progress = "Aye, that's the gist of it, anyhow.", completion = "Excellent. If you ever have questions about specializations, you can always talk to me again.\n\nNow go out and hone your talents! Oh, and take this with you. I found it on my travels.\n\nThere is something mysterious about it. Perhaps the knowledge contained within can further your specialization training.\n\nThomas was telling me he met a master artisan the other day. Perhaps this master could help you unlock the secrets within?" }
WordHunterWoW_QuestEN[67296] = { title = "Iskaara Tour", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[67297] = { title = "Iskaara Tour - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[67298] = { title = "The Wonders of the World", description = "My husband Thomas has gained many insights from exploring these primal lands.\n\nPerhaps following in his footsteps would similarly inspire you?", objectives = "Find out how Thomas gains his artisan's insight.", progress = "I could relax here forever.", completion = "Huh, this is really interesting! I guess you never know where you'll find knowledge.\n\nKeep an eye out for any treasures like this. Maybe there will be more wisdom to find in the world.\n\nAnd thanks for seeing this vista with me. It's really spectacular, isn't it?" }
WordHunterWoW_QuestEN[67299] = { title = "Drakes be Gone", description = "The primalists have been ceaselessly attacking our camp with their drakes!\n\nWe've been able to keep them at bay with our shields, but we could use more aid in taking them out of the sky.\n\nUse one of our blasters to take those drakes down!", objectives = "Use an Arcane Blaster to defeat 5 proto-drakes.", completion = "Thank you, adventurer. Any reprieve we can get from these attacks is a welcome one." }
WordHunterWoW_QuestEN[67564] = { title = "Artisan's Courier", description = "Adventurer, are you headed into the Lifeshrine?\n\nWould you mind taking this invoice to Thomas Bright? He ordered a few custom-made bottles and our glassblower has finally returned with the price of materials required.\n\nHe should be just down the path there, likely gushing to some poor soul about how great his husband is...\n\nI am sure he will pay you for your time.", objectives = "Deliver the Artisan's Consortium Invoice to Thomas Bright.\n\nProvided item:", completion = "Oh, excellent! I've been meaning to fetch this from Haephesta. Thanks, <name>." }
WordHunterWoW_QuestEN[67565] = { title = "Frostland Flyover", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[67566] = { title = "Frostland Flyover - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[67605] = { title = "Thundering Plains", description = "There is a great storm beast which wanders this ridge. Many a Shikaar hunter has attempted to take it down, only to fall to its ferocity.\n\nIf you wish for some hunting glory, you may attempt to bring down the beast. Bring back its horn as tribute.", objectives = "Claim Ayanga's horn.", progress = "So, have you seen the beast?", completion = "Excellent work. Yours will be a tale to be told to our next generation of hunters." }
WordHunterWoW_QuestEN[67606] = { title = "A Dryadic Remedy", description = "While you were gone, I heard from a dreamhare that one of the local ducklings is feeling rather down in the dumps. Luckily, I know exactly how to fix that!\n\nWhenever I'm feeling moody, I snack on something sweet and tasty! As an expert in cute, lovable creatures, I know that the same principle will surely apply here.\n\nThis particular duckling is fond of a local dessert known as a Tasty Hatchling's Treat. Won't you find one and bring it to the poor dear? It's the dryadic thing to do, after all!", objectives = "Acquire a Tasty Hatchling's Treat and administer it to the Despondent Duckling.", progress = "Well, friend? How fares our ailing avian ally?", completion = "Oh, thank you, <name>! We dryads are stretched so thin that it can be hard to see to every little bird or beast that roams these streets.\n\nWith your help, though, everything turned out splendidly! You make quite the useful dryad in a pinch! In fact, I may ask for your aid again some other time. There are always more adorable little creatures to attend to, after all!" }
WordHunterWoW_QuestEN[67700] = { title = "To the Dragon Isles!", description = "Great news, {name}! The spearhead of our expedition has made landfall in the Dragon Isles.\n\nThanks to the efforts of yerself and other Dragonscale Expedition members, we've established a protected landing site and made contact with the dragonflight's embassy.\n\nAre ye prepared to accompany us on our next voyage to the Dragon Isles?", objectives = "Ride the Rugged Dragonscale to the Dragon Isles from Stormwind Harbor.", completion = "Welcome to the Dragon Isles!" }
WordHunterWoW_QuestEN[67717] = { title = "Web-Queen Ashkaz", description = "", objectives = "" }
WordHunterWoW_QuestEN[67722] = { title = "Break on Through", description = "Toddy and Naleidea are preparing to head out. Meet at the Sealed Titan Facility in Thaldraszus. Apparently they've made a breakthrough.\n\nBe sure to bring any pertinent information back for cataloging!", objectives = "Meet Toddy and Naleidea outside the Sealed Titan Facility in Thaldraszus.", completion = "Ye made it! Just in time, too." }
WordHunterWoW_QuestEN[67724] = { title = "The Fending Flames", description = "Kattigat and I came here to prove ourselves by stopping the Sundered Flame and recovering the Valthrux.\n\nNow we're stuck watching over this elf after she takes a few ice spider bites. We haven't even fought the Sundered Flame yet, and the spiders may do us in before we can!\n\nWe need to keep them at bay. \n\nThankfully, there's a natural way to repel them. Burning silk from their cocoons creates an aroma that repulses the spiders.\n\nGrab some silk and I'll throw it on the fire. It'll keep them away!", objectives = "Collect 4 Shiverweb Silk.", progress = "Were you able to find any spider silk?", completion = "Great! This spider silk will burn for a long time." }
WordHunterWoW_QuestEN[67741] = { title = "Archive Ambit", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[67742] = { title = "Archive Ambit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[67744] = { title = "Shezra", description = "", objectives = "" }
WordHunterWoW_QuestEN[67772] = { title = "The Trouble with Taivan", description = "Hello, friend. Welcome back to Maruukai. I am Selbekh, healer of Clan Teerai.\n\nAre you good with animals, {name}? Perhaps the influence of a newcomer is just what I need.\n\nTaivan here, while a very good companion, has become something of a burden on my clan. I'm afraid if we can't find a good use for him, I may have to send him away. Will you help me?", objectives = "Help Healer Selbekh prepare Taivan for training.", completion = "What brings you to the Shikaar hunting grounds, stranger?\n\nThe Teerai would like us to train your bakar as a hunter? We do not usually accept such requests from other clans, but I will consider it. Her gift is quite generous, and a fully-trained beast of his size would be a sight to behold. I bet he could take down a bull mammoth all on his own!\n\nHmm... I will have to see him in action before I make my decision." }
WordHunterWoW_QuestEN[67921] = { title = "The Hunting Hound", description = "Go and hunt the nearby beasts with your giant bakar. The bigger, the better. I will observe from here, and decide if he is worthy of Shikaar training. \n\nBe warned, I will only accept the best.", objectives = "Hunt dangerous beasts with Taivan to prove he is worthy of training.", progress = "Go and hunt the nearby beasts with your bakar. I will be watching.", completion = "Your bakar, while massive and strong, does not seem to have the will to do what needs to be done in the hunt. He is too soft!\n\nI will give him one more chance, but this is it!" }
WordHunterWoW_QuestEN[68083] = { title = "Try Again, Taivan!", description = "Return to the Teerai and tell them that not even I can train Taivan to be a hunter. He simply does not have it in him.\n\nHe is the most un-ferocious bakar I have ever seen, and I bet he would even try to make friends with the wild game if we let him! Hah!", objectives = "Return to Healer Selbekh in Maruukai and deliver the bad news.", completion = "Taivan just returned. They could not have trained him so quickly could they? No... I suppose not.\n\n<She sighs deeply and looks at Taivan.>\n\nHe doesn't seem to be taking it well, either. I have one more idea, and if this doesn't work, we will have to make some difficult decisions." }
WordHunterWoW_QuestEN[68084] = { title = "The Gentle Giant", description = "If Taivan is really as \"un-ferocious\" as Jadar says he is, perhaps he'll be better suited as a herding bakar! \n\nThe Aylaag are expert argali shepherds, and aren't so proud that they require lavish gifts to help another clan. \n\nPlease send Taivan to Shepherd Tevatei at the Mallakh, a spot between two hills in the south-west where they train their bakar.\n\nOhn'ahra, please let this work. If it doesn't, I'm all out of ideas.", objectives = "Send Taivan to Shepherd Tevatei at the Mallakh to be trained.", completion = "Well hello there, newcomer. What can I do for you and your very large friend?" }
WordHunterWoW_QuestEN[68085] = { title = "Shaping a Shepherd", description = "You want me to train your bakar in shepherding? Well, that's certainly what we do here, but I've never trained one quite so BIG before...\n\nThe argali don't seem to be bothered by his presence, though, and they're very good judges of character. Trust me. \n\nI'm willing to give him a shot, but a herding bakar needs to not only be gentle, but smart, too. And if they aren't able to take charge of the herd, the argali won't obey them. It's harder than it looks! Go on and give it a try, I'll watch.", objectives = "Teach Taivan to herd argali at the Mallakh.", progress = "Go on and try to command Taivan to herd the argali. I'll be able to tell if he has the potential for it or not.", completion = "Hmm... Taivan still seems confused. He just doesn't seem to be grasping this.\n\nYou did great, though! Are you in the market for a new career?" }
WordHunterWoW_QuestEN[68087] = { title = "Danger in Daruukhan", description = "I guess there's nothing to be done but send you and Taivan back to Maruukai. \n\nWait... who is that approaching? Not another stranger with a giant bakar, I hope!", objectives = "Talk to the Teerai Messenger to hear Selbekh's urgent request.", completion = "Oh, <name>! Thank Ohn'ahra the messenger found you. We have our hands full here!" }
WordHunterWoW_QuestEN[68639] = { title = "Prowling Polar Predators", description = "The species we've been sent to study is the frigidpelts.\n\nTheir hunting grounds have been tainted by ley lines. Arcane energies leech into the water and into the plants... and into prey species like the slyvern.\n\nBut unlike other organisms, the frigidpelts survive the process and gain power from it.\n\nThey also become aggressive--which is a problem. Engage a few, and I will take notes on their strength and aggression. \n\nMy report will help the Kirin Tor decide what to do for them.", objectives = "Slay 6 Infected Frigidpelts.", completion = "<She scribbles notes down in her journal.>\n\nYes... Yes, this is all very helpful. Hopefully the Kirin Tor will be able to use this information to help others afflicted by the arcane sickness." }
WordHunterWoW_QuestEN[68640] = { title = "Sudden Isolation", description = "We used to trade frequently with the Uktulut tribe in the Waking Shores, but they haven't been sending or accepting shipments for months now. Our letters have gone unanswered. Naturally, we suspect the worst.\n\nTheir chieftain, Tutaqan, has always been the reasonable sort. Somewhat prone to strong emotions, but I can't imagine anything terrible could have happened under his leadership.\n\nCould you please check on them? If they need help, we'll happily provide.", objectives = "Attempt to make contact with the Uktulut tuskarr.", completion = "You're checking on us? A likely story." }
WordHunterWoW_QuestEN[68641] = { title = "Mossing the Mark", description = "Poor girl...\n\nShe must have gotten sick after eating something tainted.\n\nLuckily, my grandfather was a druid and taught me how to treat arcane-based illnesses.\n\nI don't have all the components on me, but we can make do with what's around.\n\nFirst, I will need some drakmoss. It is a rare lichen that only grows on dragon bones.", objectives = "Collect 5 Drakmoss Clumps.", progress = "Have you gathered the moss?", completion = "Oh! Thank you so much, <name>!\n\nI may be a mage, but sometimes natural solutions are the most effective." }
WordHunterWoW_QuestEN[68642] = { title = "Needles to Say", description = "I want to help Sylvie, but I don't want to delay Cally any longer.\n\nTo give Sylvie the medicine, I need arcane-infused quills from the crystalpine. I'm sure they won't mind if you pluck a few off! \n\nAnd mind the bakar! They eat crystalpine and might get mad at you touching it. If you do have to defend yourself, you can collect some spines from them as well.\n\nBut... try not to do that, please.", objectives = "Collect 15 Arcane-Infused Quills.", progress = "Be careful handling the quills! They are VERY sharp. Ask me how I know!\n\n<Steria sighs>", completion = "Thank you, <name>. You didn't hurt yourself on the crystalpine, right?" }
WordHunterWoW_QuestEN[68643] = { title = "Vitamins and Minerals", description = "I suppose I should have expected that Steria would be upset at me asking you to fight animals...\n\nThere are of course alternative research methods.\n\nTake these vials and collect some water from the nearby ice crystals. \n\nI theorize that they contain minerals infused with ley crystal energy--and may be fueling the outbreak here.", objectives = "Collect 4 Mineral Water Vials.", progress = "Have you filled all the vials?", completion = "Excellent, <name>. \n\nThese samples should give us a more complete picture of how the outbreak is spreading." }
WordHunterWoW_QuestEN[68644] = { title = "Sugar, Spice, and Everything Nice", description = "There! Now I have all I need for Sylvie!\n\nAnd just in time. I doubt she would have lasted much longer like this.\n\nBut... I need someone to help me. I'd ask Cally but... would you mind assisting me again?\n\nLet me know when or if you're ready, {name}.", objectives = "Help treat Sylvie.", completion = "I've healed her, but she is clearly still in distress.\n\nHm, I wonder if..." }
WordHunterWoW_QuestEN[68794] = { title = "Ally of Dragons", description = "Your aid to the Dragon Isles has not gone unnoticed, {name}.\n\nThe Life-Binder herself wishes to show you something as a reward for your service to dragonkind.\n\nGo and speak to her at the top of the tower. All the Aspects await you.", objectives = "Speak to Alexstrasza at the Seat of the Aspects in Valdrakken.", completion = "Thank you for joining us here, <name>. There is something we wish to show you." }
WordHunterWoW_QuestEN[68795] = { title = "Skyriding", description = "One thing you may have already discovered about this place: the Dragon Isles are vast. \n\nSome of the drakes have an intense interest in exploring every corner and secret hiding place in this renewed land, even those places that are not readily reached from the ground. They are eager for a second set of eyes to aid them in their journey, and in trade will gladly bear a rider across the lands.\n\nSpeak with Lord Andestrasz, here in the Ruby Lifeshrine. He will explain more of what they intend.", objectives = "Speak with Lord Andestrasz in the Ruby Lifeshrine.", progress = "All things come with practice.", completion = "Let us get started.\n\nDo not worry, the fancy maneuvers will come later." }
WordHunterWoW_QuestEN[68796] = { title = "The Skytop Observatory", description = "Those are the basics of riding a drake! You are doing quite well.\n\nNow, I would like to introduce you to some of the others involved in this adventure. We have made a home for ourselves over at the Skytop Observatory.\n\nCelormu will be able to help guide you there. Speak to him when you feel ready to take to the skies!\n\nSee you there!", objectives = "Travel to the Skytop Observatory in Waking Shores.", progress = "Are you ready for adventure today?", completion = "I suppose I was so eager to show you our foundation here, I may have flown a bit too fast. My apologies!\n\nThere is not much to look at for the moment as it has been a long time since someone inhabited these terraces. However, we will make them our home once again.\n\nNow, let us introduce you to everyone!" }
WordHunterWoW_QuestEN[68797] = { title = "A New Set of Horns", description = "Just as mortals do, dragons care very much about their appearance. Your drake is able to change as well, according to what you find and experience.\n\nSpeak to Glensera at the Rostrum of Transformation, and see for yourself!", objectives = "Meet Glensera and use the Rostrum of Transformation to customize your drake.", progress = "Sometimes I wonder what I would look like with red hair. What do you think?", completion = "As you explore the Dragon Isles, you will discover even more varied and unique appearances for your dragonriding companion. \n\nBoth of you shall be able to travel in style! As one must, when exploring a new land. How else do you make the best first impression?" }
WordHunterWoW_QuestEN[68798] = { title = "Skyriding Talents and You", description = "Obviously, it is not just Glensera and myself that are invested in these adventurers. Lithragosa is also excited to help you hone your dragonriding skills, and you have already met Celormu which is excellent.\n\nYour next stop is to speak to Lithragosa, who can show you what skills you can learn!", objectives = "Speak to Lithragosa to see your Skyriding skills.", progress = "Have you found the dragon glyph?", completion = "As you can see, those of us from the different flights have all come together to aid our drakes and yourself. We are all ready for adventure!\n\nOf course, we have not yet convinced... or found... a member of the black dragonflight to join us. But some day they may!" }
WordHunterWoW_QuestEN[68799] = { title = "Return to the Ruby Lifeshrine", description = "And this is just the beginning of your dragonriding journey! \n\nKeep your eyes open for new adventures and experiences throughout the Dragon Isles, and be sure to visit us in any of our outposts.\n\nFor now, return to Alexstrasza to continue your exploration in these lands.", objectives = "Return to the Ruby Lifeshrine.", completion = "Welcome back.\n\nThere is much more to do here, but know that you do not take to the skies alone." }
WordHunterWoW_QuestEN[68863] = { title = "A Lost Tribe", description = "Hi, {name}!\n\nMurik wanted to talk to you about something real important back in Iskaara. You should go see what it is.", objectives = "Speak with Murik in Iskaara.", completion = "If you have a moment, <name>, I would be grateful for your help." }
WordHunterWoW_QuestEN[69093] = { title = "A New Mystery", description = "<Doc Nanners looks out of breath as he hands you a letter inviting you back to the Dragonscale Expedition Basecamp. He eagerly tries to explain.>\n\nSealed door. Titan secrets. Yes?\n\n<Doc Nanners nods excitedly, awaiting your response.>", objectives = "Speak with Naleidea Rivergleam in the Dragonscale Basecamp.", completion = "Might I intrigue you with tale of a mysterious sealed door?" }
WordHunterWoW_QuestEN[69094] = { title = "Saving Centaur", description = "The treachery of the Nokhud knows no limits! Only craftsmen live in the village of Daruukhan. They stood no chance against the raiders.\n\nWe desperately need your help, {name}. The Nokhud are still nearby, and we must tend to the wounded!\n\nSearch the village, and carry any survivors you find to me. We will triage and stabilize who we can!", objectives = "Rescue injured centaurs in the village of Daruukhan.", progress = "We're overwhelmed here! Please, save anyone you can!", completion = "That... that seems to be everyone!\n\nTaivan! That was incredible! I had no idea he had this in him!" }
WordHunterWoW_QuestEN[69095] = { title = "Homeward Hound", description = "We have everyone stabilized, thanks to you and Taivan, but many of these villagers will need to heal for a while longer in Maruukai.\n\nWhy don't the two of you lead our train back? You are both the heroes of the day, after all!", objectives = "Ride Taivan back to Maruukai.", progress = "We're ready to depart. Go ahead and mount Taivan when you're ready.", completion = "And here we are. Home again, safe and sound.\n\nI can't begin to express how grateful I am that you and Taivan arrived when you did. You saved many lives today!" }
WordHunterWoW_QuestEN[69096] = { title = "Taivan's Purpose", description = "Do you see that young one, sitting by themselves over on the bank of the stream?\n\n<She points to the northeast, where you see a young-looking Centaur staring at the water.>\n\nChimei lost both of their parents in the Nokhud attack. I have healed all of their physical wounds, but they have not eaten or said a word to anyone since we found them. They just sit and stare. \n\nThis is beyond my skills, and I am at a loss. Will you try to talk to them, {name}?", objectives = "Try to comfort the centaur orphan Chimei.", progress = "Any luck?", completion = "<Selbekh's eyes still glisten with tears.>\n\nTaivan... So this is his true gift. \n\nHow could I have been so blind? He is different from other bakar, yes, but he has proven himself a valuable member of Clan Teerai. He will stay by my side for the rest of his days, rescuing who he can, and healing who I cannot.\n\nPlease, come and visit us anytime you'd like! We are both truly grateful for all you have done for us!" }
WordHunterWoW_QuestEN[69097] = { title = "A Vault Unsealed", description = "<Doc Nanners looks out of breath as he hands you a letter inviting you back to the Dragonscale Expedition Basecamp. He eagerly tries to explain.>\n\nLoud dwarf. Serious elf. Ready for you. Yes?\n\n<Doc Nanners nods excitedly, awaiting your response.>", objectives = "Speak with Cataloger Jakes in the Dragonscale Basecamp.", completion = "It's great to have Toddy and Naleidea back. Now if I could only enjoy some peace and quiet in this tent..." }
WordHunterWoW_QuestEN[69667] = { title = "Steamgill", description = "", objectives = "" }
