WordHunterWoW_QuestEN[69852] = { title = "Territorial Coastling", description = "", objectives = "" }
WordHunterWoW_QuestEN[69854] = { title = "Solethus' Gravestone", description = "", objectives = "" }
WordHunterWoW_QuestEN[69855] = { title = "A Climber's Calling", description = "<Doc Nanners looks out of breath as he hands you a letter inviting you back to the Dragonscale Expedition Basecamp for training. He eagerly tries to explain.>\n\nFrom Big Jeb. Good friend. Climb now. Yes?\n\n<Doc Nanners nods excitedly, awaiting your response.>", objectives = "Speak with Pathfinder Jeb in the Dragonscale Basecamp.", completion = "You look like you've got the strength, but I wonder if you've got the gumption..." }
WordHunterWoW_QuestEN[69856] = { title = "Fulgurb", description = "", objectives = "" }
WordHunterWoW_QuestEN[69857] = { title = "Mikrin of the Raging Winds", description = "", objectives = "" }
WordHunterWoW_QuestEN[69858] = { title = "Blightfur", description = "", objectives = "" }
WordHunterWoW_QuestEN[69859] = { title = "Sandana the Tempest", description = "", objectives = "" }
WordHunterWoW_QuestEN[69861] = { title = "Trilvarus Loreweaver", description = "", objectives = "" }
WordHunterWoW_QuestEN[69862] = { title = "Save a Slyvern", description = "Now that she's healed, I think Sylvie wants to show us something. \n\nOur work isn't done yet, {name}! Let's see what's upsetting her.", objectives = "Find out what Sylvie is upset about.", progress = "A cave? Wait, I can hear something inside!", completion = "It's faint, but I can hear what sounds like kits in the cave!\n\nThis is bad..." }
WordHunterWoW_QuestEN[69864] = { title = "Forgotten Creation", description = "", objectives = "" }
