WordHunterWoW_QuestEN[69888] = { title = "Unusual Suspects", description = "{name}, you're here. Good. Don't react, but our findings on the titan discs have just been stolen! Other than us, only the Sundered Flame know what we were up to in that facility.\n\nI need ye to take this device and scan some of the suspicious members that have joined us recently. Reveal the spy and recover the data if you can. We cannae allow it to fall into their hands!", objectives = "Scan Suspicious Explorers to reveal the spy.", progress = "Be quick and be casual. Got it?", completion = "They escaped? That's not good. The Sundered Flame have been one step ahead of us this whole time, and our one advantage has been lost!\n\nFortunately, I created a copy of these findings. I'm a betting gal, but even I've learned to hedge my bets." }
WordHunterWoW_QuestEN[69891] = { title = "Lepidoralia the Resplendent", description = "", objectives = "" }
WordHunterWoW_QuestEN[69892] = { title = "Grumbletrunk", description = "", objectives = "" }
WordHunterWoW_QuestEN[69895] = { title = "Summoned Destroyer", description = "", objectives = "" }
WordHunterWoW_QuestEN[69896] = { title = "Disastrous Detour", description = "I knew joining the Dragonscale Expedition meant venturing into dangerous territory. But I was not expecting to fight off elementals!\n\nOur dig site at the Life Vault Ruins is in complete disarray! Stone monstrosities are rising up out of the ground! We called in an elementalist to consult, but I believe she will need all the help she can get.\n\nPerhaps you can help her? Our camp is just across the river.", objectives = "Meet Elementalist Taiyang in the Life Vault Ruins.", completion = "Thank you for coming! The Expedition is in desperate need of your help!" }
WordHunterWoW_QuestEN[69897] = { title = "Behavior Analysis \"Homework\"", description = "I need to talk to someone who knows proto-whelps. Like the ones that live in the Wild Preserve! \n\nAre they as angry as the big ones? Do they bite or breathe fire at you?\n\nWhat if I... er... you petted a proto-whelp? Would they know that you're nice and trying to help them?\n\nI'm asking for science, of course. Tyrgon always tells us to test our hippa... no... hypo... hmph! Hyppotatotoast... ugh! THEORIES!\n\nI think they would like petting and it would make them feel good. Could you test that for me?", objectives = "Pet 3 Sleeping Whelps and report back to Iyali.", progress = "Do you think a whelp would feel better if I petted them? I always feel better when I get hurt and mom takes care of me.\n\n<Iyali looks around, avoiding eye contact.>\n\nI know I'm not supposed to touch the animals. It's for my homework on, uh, proto-whelp behavior. And it's due, uh, soon. So...", completion = "So, some proto-whelps like to be petted, but some don't? \n\nThat's not good. What if this one calls its friends? Or what if it's mean? \n\nI mean, this lesson, uh, makes no sense! This, uh, homework is very difficult. \n\nThank you for helping me. I'm sorry if you got hurt..." }
WordHunterWoW_QuestEN[69898] = { title = "Scientific Meat-thod", description = "So, I have, uh, more homework... Professor Tyrgon's lessons are super tough! He wants us to find out what proto-whelps, uh, eat! Yeah...\n\nI already know the answer! It's riverbeast meat! \n\nCan you bring me a piece of riverbeast meat? Some riverbeast meat would be a great \"visual aid\" for my project.\n\nBut it has to be a REALLY good piece, ok? Like... the ones from Pudgy Riverbeasts. One like a momma proto-drake would give their whelp to make them strong because, uh, it will make Mister Tyrgon happy.", objectives = "Collect 1 piece of Extra-Delicious Riverbeast Meat.", progress = "Mom says food makes everyone happy.\n\nMaybe it will be friends with me then...\n\nI mean, we'll all be friends! And Professor Tyrgon won't give me a bad grade if I make Riverbeast meat part of my project!", completion = "Oh, wow! That's the most delicious-looking meat I've EVER seen! My project will get the BEST grade. The proto-whelp will definitely want this!\n\n<Iyali's expression is suddenly filled with concern.>\n\nOh no! \n\nI mean, uh, everyone will lwant to copy me... for the project!\n\n<Iyali smiles unconvincingly.>" }
WordHunterWoW_QuestEN[69899] = { title = "Secret Research", description = "I know.. I am acting weird. I'm sorry!\n\nYou probably guessed I am not being truthful.\n\nI can tell you my secret... if you like. But you will have to promise not to tell the adults!", objectives = "Help Iyali and their friends.", progress = "We found this Injured Proto-Whelp in the Wild Preserve.\n\nThere was an evil Primalist attacking Proto-Dragons and... they hurt this poor little whelpling!\n\nPlease don't yell at us... We just wanted to help!", completion = "They did what? Oh, these younglings... When will they learn? They could have gotten hurt--or captured!\n\nThis is very serious indeed..." }
WordHunterWoW_QuestEN[69900] = { title = "Identifying the Source", description = "Judging by what the children have said, we might have a primalist prowling the Wild Preserve.\n\nThis calls for immediate investigation.\n\nAccording to what other researchers have observed, Primalists like to steal eggs and whelps to infuse them with power and corrupt them. Those that don't acclimate to the process suffer a slow death... not that the primalists seem to care...\n\nWe need them out of the Preserve. Attend to that, and I will try to distract the children. They must not know of this.", objectives = "Slay the experimenting primalist in the Wild Preserve.", progress = "Keep your voice down! Have you done what I asked?", completion = "Thank you, <name>! I'm certain that was... unpleasant.\n\nI'm sure you would prefer to limit your tasks to exploring and researching, but, unfortunately, we sometimes have to get our hands dirty protecting wildlife from those who endanger it." }
WordHunterWoW_QuestEN[69901] = { title = "Bring In the Expert", description = "Did Iyali say how long this creature has been suffering? If it's too injured to eat, we need to treat it quickly.\n\nNormally a Dragonscale Expedition camp would have everything I need to help this whelp, but getting supplies to the \"frontier\" here on the Dragon Isles has proven tricky. There have been significant delays in our supply routes.\n\nBut, fear not. The land itself will provide! If you bring me Sunlight Flowers, I can craft a soothing balm that will calm the drake so I can heal it.", objectives = "Collect 5 Sunlight Flowers.", progress = "Sunlight Flowers are very useful resource.\n\nTheir petals and stalks have sedative properties which will ease the whelp's suffering while we heal it.", completion = "Terrific, <name>. \n\nI hope these kids were able to learn something from you. \n\nWhere did they get the idea we wouldn't help them? Helping wildlife is part of our mission. Maybe our pedagogy needs a review..." }
WordHunterWoW_QuestEN[69902] = { title = "Theory in Practice", description = "{name}, I require your assistance...\n\nI hope no one was expecting me to craft, subdue the whelp, heal, and teach these children all at once! Multitasking like that is certainly overrated. \n\nNow, you can start by using those flowers. I'll need a couple minutes to prepare myself to heal the proto-whelp. \n\nHopefully, the children will find this incident... instructional.", objectives = "Assist Tyrgon to heal the creature.", progress = "Where on earth did they get the idea we wouldn't help them? I need to investigate this further...", completion = "Great work, <name>! I hope the younglings learned a valuable lesson... or a memorable one at least. \n\nWe will keep the whelpling here for a while as I need to ascertain the best occasion for returning it to Preserve.\n\nI shall also make you an honorary Brave Researcher. Your commitment was essential for this creature's survival. I'll just advise you to tell me sooner if you see the children plotting something reckless again.\n\nNow, if you excuse me, I must reevaluate my pedagogy. It's clearly not working." }
WordHunterWoW_QuestEN[69904] = { title = "Suspiciously Quiet", description = "Can you spare a minute, {name}? I haven't heard from my two apprentices, Scrumpy and Tucky, in some time. \n\nThis is concerning. \n\nI sent them to fetch us supplies for the inn. They couldn't have strayed too far...\n\nPlease find them, but I warn you... They're... quite the handful.", objectives = "Find Noriko's apprentices in Camp Antonidas.", completion = "<The young vulpera nervously puts his hands behind his back.>\n\nDo we know you? Noriko said not to talk to strangers..." }
WordHunterWoW_QuestEN[69910] = { title = "Where is Wrathion?", description = "How unusual.\n\nEbyssian told us that Wrathion would be awaiting our arrival along with an ambassador for Alexstrasza the Life-Binder, Queen of the Dragons.\n\nIt isn't like a dragon to break a promise.\n\nAt least this eager drakonid is here to greet us. Would you kindly inquire into when the others shall arrive?", objectives = "Ask Sendrax when the dragons are expected to arrive.", progress = "Welcome to the Dragon Isles, friend!\n\n... I think I may have already said that. No matter! I am just excited you are here!", completion = "I do not know! As I said, this is my first assignment... Let me think on what to do." }
WordHunterWoW_QuestEN[69911] = { title = "Excuse the Mess", description = "I wish I knew more about how to welcome you to the Dragon Isles, but I'm only the sentry.\n\n<Sendrax motions to the tower behind her.>\n\nYou could try talking with Ambassador Fastrasz in the visitor center. He might be able to answer more of your questions before the dragons arrive.\n\nMind your step in there. He was clearing out rubble last I saw.", objectives = "Help Ambassador Fastrasz restore the embassy.", progress = "Ambassador Fastrasz will be eager to meet you.", completion = "The embassy is looking better already!\n\nIs every <race> as helpful as you are? I can't wait to meet more." }
WordHunterWoW_QuestEN[69912] = { title = "My First Real Emergency!", description = "<Sendrax looks puzzled.>\n\nI have never known the majordomo to be late to anything, much less THIS late to something THIS important.\n\nMost unusual...\n\n<Sendrax perks up at a thought.>\n\nI could use my emergency signal flare to alert them to your arrival. Then they would come rushing to greet you immediately!\n\nI've never fired my emergency signal flare before, though...", objectives = "Convince Sendrax to fire her emergency signal flare to alert the dragons of your arrival.", completion = "Well then, <name>. What do you say? Do you fancy a fight alongside your newfound dragon acquaintances?\n\nI assure you, there is no quicker way to earn their trust." }
WordHunterWoW_QuestEN[69913] = { title = "Towers of Earthen Power", description = "", objectives = "" }
WordHunterWoW_QuestEN[69914] = { title = "The Djaradin Have Awoken", description = "I wish we'd time for more pleasant introductions, but we can't all be Chronormu, can we?\n\nI am Selistra, majordomo to Alexstrasza the Life-Binder, Queen of the Dragons.\n\nQueen Alexstrasza asked me to convey her kindest regards and escort you to her at the Life Pools.\n\nBut I'm afraid I must ask for your assistance before we go meet her.\n\nOur ancient rivals, the djaradin, have awoken from their slumber under the earth and have already assaulted a nearby outpost!", objectives = "Receive your orders from Majordomo Selistra.", progress = "We must do whatever the majordomo asks of us.", completion = "The djaradin have awoken? This is not good, <name>..." }
WordHunterWoW_QuestEN[69915] = { title = "Targeted Ads", description = "Hi, hi, hi! You looking for a gig?\n\nWe're doing a BIG opening sale for our new Crafting Order service, and we need to draw attention! But the wind took my flyers and I think some of the local goats ran off with them.\n\nCould you get my flyers back?", objectives = "Recover flyers from Forkriver and Meddlesome Goats.", progress = "Whoo! Setting up a business is busy, busy, busy!", completion = "Thank you, thank you, thank you! You're the best <name>!" }
WordHunterWoW_QuestEN[69916] = { title = "Famous Frogs", description = "", objectives = "" }
WordHunterWoW_QuestEN[69918] = { title = "Shaking Our Foundations", description = "Djaradin stonebinders are threatening to break the very foundations of the Citadel! They have to be stopped!\n\nWe haven't even had a chance to reclaim the Citadel as our own and yet it might crumble beneath us. We can't let that happen.\n\nDo what you can, {name}... by that I mean kill them!", objectives = "Slay Stonewrecker Tokara, Molka the Grinder, and the elementals they have unleashed.", progress = "Have you saved the foundation of this Citadel?", completion = "I knew you could be counted on. I feel better knowing that the Citadel isn't about to collapse beneath our feet." }
WordHunterWoW_QuestEN[69919] = { title = "A Craft in Need", description = "You seem like a skilled crafter. Would you like to fill some crafting orders for fellow adventurers and get rich, rich, rich?\n\nI'll tell you the rules of working with the Artisan's Consortium, then you can pick up Crafting Orders at any crafting station on the Dragon Isles!", objectives = "Speak with Azley to learn about filling Crafting Orders.", progress = "Business is busy, busy, busy!", completion = "Great, great, great! Keep it up. There's always more orders to fill!" }
WordHunterWoW_QuestEN[69923] = { title = "A Primal Threat", description = "Raszageth has wasted no time building up her Primalist forces.\n\nThe Kirin Tor have detected massive storms being unleashed at key points across Kalimdor and the Eastern Kingdoms.\n\nThe Primalists are unleashing the elements to add to their strength. It seems they plan to cause chaos not only in the Dragon Isles, but in the lands of the Alliance and Horde as well.\n\nSeek out the enemy and study their methods. We have to stop them before it's too late.", objectives = "Gather 10 Motes of Primal Energy from enemies in active primal storm locations throughout Kalimdor and the Eastern Kingdoms.", progress = "I'm afraid this is only the beginning.", completion = "It is good you thwarted their attack, at least for now.\n\n<Khadgar examines the motes you brought him.>\n\nHmm, primal elemental energy. I will take this for further study." }
WordHunterWoW_QuestEN[69924] = { title = "Towers of Flaming Power", description = "", objectives = "" }
WordHunterWoW_QuestEN[69925] = { title = "Calming the Storms", description = "These Primalists are relentless, unleashing elemental devastation across the Eastern Kingdoms and Kalimdor.\n\nYou must show the same determination, {name}. It is the only way to stop them.\n\nFind their next incursion, remove the enemies within the primal storm area before it is too late and foil their efforts.\n\nWe must protect Azeroth!", objectives = "Gather 10 Motes of Primal Energy from enemies in active primal storm locations throughout Kalimdor and the Eastern Kingdoms.", progress = "Our effort continues.", completion = "Well done. Let us hope that buys us time before their next incursion." }
WordHunterWoW_QuestEN[69926] = { title = "Becca Black and the Seven Gnomes", description = "The djaradin have ransacked the Obsidian Citadel and stolen a number of valuable artifacts.\n\nWrathion has tasked us to recover every item taken from the Citadel. My team has located several in the area, but we could use your help.", objectives = "Recover the missing artifacts.", progress = "Have you found everything on the list?", completion = "Excellent work, <name>. Once we've located more of the stolen artifacts, we'll be sure to call for your help again." }
WordHunterWoW_QuestEN[69927] = { title = "Bazual", description = "", objectives = "" }
WordHunterWoW_QuestEN[69928] = { title = "Liskanoth", description = "", objectives = "" }
WordHunterWoW_QuestEN[69929] = { title = "Strunraan", description = "", objectives = "" }
WordHunterWoW_QuestEN[69930] = { title = "Basrikron", description = "", objectives = "" }
WordHunterWoW_QuestEN[69931] = { title = "Swoop And Grab", description = "", objectives = "" }
WordHunterWoW_QuestEN[69932] = { title = "Every Life Counts", description = "Making potions for Gelikyr means that I don't have time for my other duties.\n\nA duck landed in my garden with a broken rib. I've tended to the wound, but her dressing needs replacing. And since you're so eager to help...\n\n<Szareth shoves a list of ingredients into your hand.>\n\nThis is what you'll need. Bring the rest to me.", objectives = "Collect ingredients to replace Little Jetstream's dressings.", progress = "Well?", completion = "<Szareth takes the extra pollen and linens, then looks toward their hut.>\n\nDucks have to contend with harpies further up the cliffside. The wounded land here, and I aid them how I can.\n\nI hope this one will make it." }
WordHunterWoW_QuestEN[69933] = { title = "Curiosity's Price", description = "Look across the ravine, {race}. Primalists attacked Gelikyr Post days ago, and the battle still rages.\n\nThose people need salves and stitching. I can make it for them, but my ingredients are running low. Since you've chosen to intrude upon my home, consider yourself volunteered.\n\nGo to my garden and find the largest vine you can. Snap it from the root, then bring it to me.", objectives = "Take a cutting from the Stubborn Vine.", progress = "Be quick. A fresh ingredient is a potent ingredient.", completion = "The lasher attacked you?\n\n<Szareth frowns, sniffing at your clothes. Their snout wrinkles in disgust.>\n\nNo wonder--you reek of blood. And not yours, I assume.\n\nWar truly engulfs the Isles." }
WordHunterWoW_QuestEN[69934] = { title = "Bleeding Hearts", description = "The potions are ready--now to deliver them.\n\nTake one crate to a small cave in the ravine below us. No one will be there to accept it, but you can trust it will be used well.\n\nTake another crate to the infirmary in Gelikyr Post. An old friend tends to the patients there.\n\nI... realize this is not your duty. Nor is it really mine. But you've been surprisingly helpful, and this medicine could save lives.", objectives = "Deliver the Medical Supplies.", progress = "Excuse me, I don't have time to chat.", completion = "Szareth wants to heal everyone, no matter the consequences. Rebels, Scalesworn, wildlife: each deserves equal care.\n\nAnd while I might find Szareth's idealism galling, Gelikyr depends on their expertise.\n\nSo my thanks to Szareth--and you as well. These potions will be invaluable." }
WordHunterWoW_QuestEN[69936] = { title = "Zambul, Head Vandal", description = "Good work. Those desecrators cannot force any more of my ancestors to fight for them. But the brute yelling out their orders must be handled.\n\nThat is their overseer, Zambul. He must be stopped.\n\nTake him down.", objectives = "Defeat Overseer Zambul.", progress = "Did you give Zambul the end he deserves?", completion = "An initiate must not take pleasure in the death of another Maruuk. But Zambul makes that a challenge." }
WordHunterWoW_QuestEN[69937] = { title = "Sylvan Succor", description = "Ah, <name>, there you are! I've been looking all over for you.\n\nAnother of our local critters has been suffering from a distinct lack of affectionate treat-feeding of late. Won't you go and find them something sweet to snack on?", objectives = "Acquire a Tasty Hatchling's Treat and administer it to the Despondent Duckling.", progress = "Well, <name>? Did you tend to the poor, hungry critter?", completion = "Another day, another delighted little friend! Excellent work, my Sylvan apprentice!" }
WordHunterWoW_QuestEN[69938] = { title = "Fishing Frenzy!", description = "", objectives = "" }
WordHunterWoW_QuestEN[69939] = { title = "Sylvan Succor", description = "Ah, <name>, there you are! I've been looking all over for you.\n\nAnother of our local critters has been suffering from a distinct lack of affectionate treat-feeding of late. Won't you go and find them something sweet to snack on?", objectives = "Acquire a Snow in a Cone and administer it to the Overwrought Otter.", progress = "Well, <name>? Did you tend to the poor, hungry critter?", completion = "Another day, another delighted little friend! Excellent work, my Sylvan apprentice!" }
