WordHunterWoW_QuestEN[69942] = { title = "Brackenhide Mysteries", description = "", objectives = "" }
WordHunterWoW_QuestEN[69944] = { title = "Chasing Storms", description = "Well, that wizard certainly knows how to make an entrance, doesn't he?\n\nWe won't be able to set sail until someone gets those elemental storms under control.\n\nCheck-in with Storm Huntress Suhrakka. She's leading the expedition efforts to investigate the storms and can help outfit you with whatever gear you need.\n\nWhile you handle that, I'll coordinate the rest of the preparations. At least it'll give me some time to read a few more volumes on dragon history before we set sail.", objectives = "Speak with Storm Huntress Suhrakka at the zeppelin tower.", completion = "These storms are wild, dangerous things. If you wish to confront them, you'll want extra protection.\n\nIn my years of hunting, I've gathered many things that helped ward against the wrath of the elements. Perhaps some of them may be of use to you as well." }
WordHunterWoW_QuestEN[69946] = { title = "The Master of Their Craft", description = "While I was traveling through these plains, I met an old centaur in a cave up north. They had clearly mastered their craft and had wisdom to spare.\n\nThey helped me understand the knowledge I had gained from the Dragon Isles.\n\nIf you're curious about specializing in your profession, seek out the wisdom of this master. Khadin was their name, of Clan Teerai.", objectives = "Seek out Master Khadin to learn their professional wisdom.", progress = "Patience, young one. Rest in knowing that there is much to learn, and that is acceptable.", completion = "If you truly seek my knowledge, you must prove yourself worthy of it." }
WordHunterWoW_QuestEN[69949] = { title = "Extermination", description = "", objectives = "" }
