WordHunterWoW_QuestEN[70074] = { title = "Plunder the Sundered", description = "", objectives = "" }
WordHunterWoW_QuestEN[70075] = { title = "Cataloging the Waking Shores", description = "", objectives = "" }
WordHunterWoW_QuestEN[70079] = { title = "Cataloging the Ohn'ahran Plains", description = "", objectives = "" }
WordHunterWoW_QuestEN[70100] = { title = "Cataloging the Azure Span", description = "", objectives = "" }
WordHunterWoW_QuestEN[70110] = { title = "Cataloging Thaldraszus", description = "", objectives = "" }
WordHunterWoW_QuestEN[70111] = { title = "Temple Treasures", description = "", objectives = "" }
WordHunterWoW_QuestEN[70112] = { title = "Furbolg Threat", description = "", objectives = "" }
WordHunterWoW_QuestEN[70122] = { title = "Explorers in Peril", description = "Don't mistake the expedition's scholarly pursuits as timidness, {name}.\n\nWe are not recluses studying books in far-off towers.\n\nWe are adventurers, hunting down knowledge first-hand in every corner of Azeroth!\n\nThat same passion for adventure often leads us into the path of perils and hazards, and a few expedition members have bitten off a little more than they could chew...\n\nBut, hey, the danger makes it more fun!", objectives = "Rescue 3 Dragonscale Expedition members in the Wild Coast.", progress = "Are the expedition members safe?", completion = "The dragons are nae here to meet us like Wrathion said they would..." }
WordHunterWoW_QuestEN[70123] = { title = "Primal Pests", description = "<Azurathel glances suspiciously at the proto-dragons lurking on the ridge behind him.>\n\nI'd swear that those proto-dragons edge closer to camp every time I turn my back...\n\nThose are not the dragons Wrathion invited us here to meet.\n\nProto-dragons are ruthless predators who cannot be reasoned with. We must be ruthless in return.\n\nCull their numbers to keep their ambitions in check, or this expedition will be over before it begins.", objectives = "Kill 8 Primal Proto-drakes on the Wild Coast.", completion = "That may dissuade them from attacking the expedition camps for a time.\n\nIt's eat or be eaten in the Dragon Isles, <name>. You'd do well to remember that." }
WordHunterWoW_QuestEN[70124] = { title = "Practice Materials", description = "The proto-drakes here are unlike any I've seen before.\n\nTheir scales appear to be naturally flame-resistant, stronger than steel, and don't lose flexibility in the process. Incredible.\n\nThe artisans are clamoring to get their hands on some to work with.\n\nStart with the whelps. The smaller scales should be more pliable until we've mastered our techniques with 'em.", objectives = "Collect 12 Primal Proto-Whelp Scales.", progress = "You got those scales yet?", completion = "<Thaelin carefully studies the scales.>\n\nBrilliant. Our artisans'll have no problem puttin' these to good use!" }
WordHunterWoW_QuestEN[70125] = { title = "Where is Wrathion?", description = "Hm, wonder where Wrathion is?\n\nHe said he'd be here waitin' for us with an ambassador for Alexstrasza the Life-Binder, Queen of the Dragons.\n\nIt does nae seem like a dragon to break a promise.\n\nWell! At least this eager wee drakonid is here to welcome us. Can you talk to 'em and find out when the others are gonna arrive?", objectives = "Ask Sendrax when the dragons are expected to arrive.", progress = "Welcome to the Dragon Isles, friend!\n\n... I think I may have already said that. No matter! I am just excited you are here!", completion = "I do not know! As I said, this is my first assignment... Let me think on what to do." }
WordHunterWoW_QuestEN[70126] = { title = "A Finishing Touch", description = "Ah, {name}, good to see you. \n\nYou've been an exceptional help for the Artisan's Consortium, and to Thomas and myself personally. Thank you.\n\nThere is one more thing you should know as a crafter, and that's building a rapport with your clients.\n\nI filled a crafting order for a customer today. Could you talk to him for me? Try to convince him to come to me for his future crafting needs. Remind him that he needs to come to me personally if he wants high-quality goods.", objectives = "Convince Miguel's customer to entrust him with future crafting orders.", progress = "That's the secret, <name>: it's the little acts of kindness that add up in a relationship.", completion = "Take these finishing reagents. Use them to increase your crafting skill when you really need something high quality.\n\nBe kind and respectful to your customers and they will honor you with their business, <name>." }
WordHunterWoW_QuestEN[70129] = { title = "Toejam the Terrible", description = "You're right, I'm not strong enough to take on this yeti... not alone! \n\nBut you're here!\n\nThe lair of the evil yeti, Toejam the Terrible, is just ahead. This cave is... big. Not scary! Maybe a little scary. \n\nCould you go in there and soften him up a bit? I'll... I'll be right behind you!", objectives = "Help Rowie slay Toejam the Terrible.", completion = "Goodness, what did you tell him? I've never seen Rowie so spirited!\n\nThank you for bringing him home. I will do my best to take care of him in Kaqiata's place." }
WordHunterWoW_QuestEN[70132] = { title = "Stay a While", description = "<The old dwarf doesn't react to your presence as you approach. As he gazes over the landscape, a deep frown is set in his face. It's a pleasant view. It might be nice to take a break and watch the landscape.>", objectives = "Sit for a while. Look at the landscape.", progress = "<The Dwarf continues to look off into the distance, you notice water welling up in his eyes>", completion = "Thank you for listening to me Young One, I appreciated it more than you can know." }
WordHunterWoW_QuestEN[70134] = { title = "Memories", description = "Thank you for listening to me, young one. I have a favor to ask. \n\nDon't worry. No more stories.\n\nWhen we left this place, I left a... time capsule of sorts. Would you... would you be able to retrieve it for me? We left it at the bottom of the Ruby Life Shrine, hidden behind one of the pillars.\n\nI hid it with a sigil. If you activate it, you should see my time capsule.", objectives = "Retrieve Veritistrasz's time capsule.", progress = "I find myself oddly... excited? \n\nApparently I am looking forward to looking through the time capsule, how... Unexpected.", completion = "Thank you, young one, you have given me a lot to think about. \n\nIt seems like I put this in the time capsule. I don't think I have much use for it anymore, maybe it's useful to you?" }
WordHunterWoW_QuestEN[70135] = { title = "Encroaching Elementals", description = "The crafters, artisans, and explorers of the Dragonscale Expedition are ill-suited to the vigors of battle.\n\nBut not you and I, {name}.\n\nHere in the Dragon Isles, let us use that strength to protect those who can't protect themselves.\n\nClear out the elementals encroaching from the north, so that the expedition can focus on their noble pursuits.", objectives = "Kill 15 primal elementals in Wingrest Embassy.", progress = "These elementals are unlike any I've seen before...", completion = "For the Dragonscale Expedition!\n\n<Warlord Grimaxe salutes you.>" }
WordHunterWoW_QuestEN[70136] = { title = "Haven't Got Time For the Pain", description = "Ugh... One moment...\n\nMy first assignment... Unstable temporal energy seeping into the forest... Affecting the wildlife... Need to assess the impact and collect that magic for the Timewalkers...\n\n<Zera shakes her head a moment.>\n\nI was examining a pack of vorquin when I was attacked by a crazed bear overflowing with time magic. It caught me off guard. I barely escaped.\n\nCould you find my missing gear for me, {class}? Uh, you might also have to deal with that bear.", objectives = "Retrieve the Timewalker Staff, Timewalker Notes, and slay the Crazed Alpha in the Flowing Forest of Thaldraszus.", progress = "Were you able to find the them?", completion = "Thank you, for recovering all that valuable equipment <class>." }
WordHunterWoW_QuestEN[70139] = { title = "Where There's a Ward, There's a Way", description = "This reservoir used to be protected by three warding stones placed by Tyr. \n\nThey were meant to stabilize the elemental magic that is prevalent in the Dragon Isles. \n\nWhen you woke me, I sensed damage done to the west ward. I fear the Primalists may have done this to all of them. \n\nStill, we must assess the damage done in order to figure out what we should do next.", objectives = "Assess the damage done to the ward stones in Tyrhold Reservoir.", progress = "We must find out the extent of the damage done to the warding stones. I can already feel the elemental energy growing out of control.", completion = "As I suspected. It is imperative that we find the missing keystones.\n\nOtherwise the losses that Zuttiki and I have suffered would be for nothing." }
WordHunterWoW_QuestEN[70146] = { title = "Highlands Rebuttal", description = "", objectives = "" }
WordHunterWoW_QuestEN[70148] = { title = "Without Purpose", description = "Could I have a moment of your time? \n\nI'm worried about another dracthyr that passed through here. He asked my associates and me all kinds of questions, but seemed... disappointed with our answers.\n\nHe called himself \"Talon Ethrethi\". I believe that makes him quite junior amongst your ranks?\n\nI got the sense that he could use a hand. Mind helping me keep the peace?\n\nI saw him talking with Kholmar over there.", objectives = "Search for Talon Ethrethi in Wingrest Embassy.", progress = "Any news on this Ethrethi fellow?", completion = "You've raised the spirits of not just Talon Ethrethi, but the entire camp! It's not every day someone finds a new lease on life..." }
WordHunterWoW_QuestEN[70149] = { title = "Hope for the Highlands", description = "", objectives = "" }
WordHunterWoW_QuestEN[70150] = { title = "Many Whelps, Handle It", description = "", objectives = "" }
WordHunterWoW_QuestEN[70152] = { title = "Fishing Frenzy!", description = "", objectives = "" }
WordHunterWoW_QuestEN[70154] = { title = "A Gateway to Somewhere", description = "The enchantment will protect us from the unstable energy contained within.\n\nI will open the way to the nearest stone. \n\nOnce you pass through, stay close. I shall need your assistance when we arrive to power up the device.", objectives = "Follow Warpcaster Delandra to the Waygate's location.", completion = "Not quite what I expected, but we have arrived in one piece.\n\nI must admit, with all that has happened I am even more curious about the potency of the vessel's contents now more than ever." }
WordHunterWoW_QuestEN[70155] = { title = "Look, Listen, and Breathe", description = "Hail, {race}. Few stop to say hello, let alone stay for a time. Most are in a rush to their next destination.\n\nWould you like to fish with me?", objectives = "Fish with Threshrak.", progress = "If I could tell my younger self one thing, I'd say: try fishing.", completion = "Return whenever you like, young one." }
WordHunterWoW_QuestEN[70156] = { title = "An Ancient Awakening", description = "The waygate sits just behind me. There is no way to tell how long we have until the waning enchantment on this vessel fades, or even worse, breaks.\n\nThat amount of unstable energy being released could be catastrophic. \n\nShall we continue?", objectives = "Empower the Waygate.", completion = "Now that we, and by we I mean you, have figured out what these things are fer there's no tellin' how many more are out there!\n\nKeep yer eyes open, <name>. No tellin' what we might find around the Isles." }
WordHunterWoW_QuestEN[70157] = { title = "Garden Gallivant", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[70158] = { title = "Garden Gallivant - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[70159] = { title = "A Taste of Home", description = "Oh, finally! Another dracthyr to lend a hand.\n\nMy brother and I have been trying to cook up some rations to eat, but...\n\n<Scaralesh gestures to his surroundings.>\n\nEverything is so different around here. It's hard to find the same ingredients we used to cook with.\n\nBut we can adapt. Go ask the Horde if they have anything we can substitute for vegetable matter, protein, and emulsifying fluid. Then we'll really have a meal.", objectives = "Ask around members of the Horde at Dragonscale Basecamp to see if they can loan you the ingredients you need.", progress = "Any luck, <name>?", completion = "They don't look much like they did back home, but we <race> are resourceful. We'll give it a try.\n\nWho knows, maybe it'll end up being even better." }
WordHunterWoW_QuestEN[70160] = { title = "Alchemical Thesis Defense", description = "", objectives = "" }
WordHunterWoW_QuestEN[70161] = { title = "Caverns Criss-Cross", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[70163] = { title = "Caverns Criss-Cross - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[70164] = { title = "A Tinker's Chance", description = "If you have a moment, {name}, I am close to a breakthrough!\n\nAfter the creche collapsed, I lost more than my ability to fight. I lost my identity as a dracthyr. Perhaps you can understand.\n\nI have always enjoyed putting things together and taking them apart, so Expedition seemed like a good fit for me. But this artifact is giving me some trouble.\n\nWould you ask Phosildral and Sibrit to review my notes? I want to prove I am a capable tinker... to them and to myself.", objectives = "Speak with Chronomancer Phosildral and Sibrit Clacketpage in the Life Vault Ruins.", progress = "I almost have the orb where I want it, but I need just a little more time.", completion = "Our history is complicated, <name>, but I am eager all the same to unravel what we were meant to be... and what we will become. It is in our talons now!" }
WordHunterWoW_QuestEN[70166] = { title = "The Joy of Painting", description = "Do you like my collection? These are all the work of the greatest painter that ever lived, Hudson.\n\nThey're rare and probably valuable--he's a recluse and hasn't painted anything in awhile. Oh, but I'd love to meet him... Or to learn from him!\n\nYou... seem like the bold type. Would you find him for me? H-here! Take some of my work with you. Maybe he'll be impressed!\n\nOr maybe he'll think I'm terrible... oh dear.", objectives = "Deliver Rauvros' Painting of Introduction to Hudson.\n\nProvided item:", completion = "What's this? A painting?" }
WordHunterWoW_QuestEN[70168] = { title = "Sad Little Accidents", description = "You came all this way... I'm sorry.\n\nMy dear Hudson used to love painting. It was his life! I don't know what's caused this block. \n\nA few weeks ago on his way back from a painting trip, he took all his unfinished paintings and threw each away in a fit of rage. \n\nPlease, traveler, if you don't mind... could you find them? They may just give him back the spark he needs. \n\nHudson does not shy away from dangerous places to find the best vistas. I hope you are prepared.", objectives = "Recover Hudson's Lost Paintings from the final bosses of the Ruby Life Pools, Nokhud Offensive, and Brackenhide Hollow dungeons.", progress = "Go away.", completion = "What? What have you done?\n\nWhy would you bring me this garbage?!" }
WordHunterWoW_QuestEN[70169] = { title = "Even Trees Need Friends", description = "I know you and Ran are simply trying to be helpful. \n\nI don't think there's any helping me. My spark--my will to paint--is simply... gone. \n\nBut Ran is right. I owe you at least to try.\n\nBring this budding artist friend of yours to me.", objectives = "Speak with Rauvros.", progress = "All I need is a chance to prove myself.", completion = "I cannot believe it! A chance to learn from the master himself!\n\nOh, goodness... I do hope he likes my work." }
WordHunterWoW_QuestEN[70170] = { title = "Beat the Demons Out of It", description = "He can be very stubborn, I'm afraid.\n\nBut I can't just give up on him. We'll just have to try again! \n\nThere are more paintings still out there he threw out. These were in even more dangerous locations, so I hope you are up for the challenge!", objectives = "Recover Hudson's Lost Paintings from the final bosses of the Halls of Infusion, Algeth'ar Academy, Azure Vault, and Neltharus dungeons.", progress = "What now?", completion = "Again? Why must you keep bringing me these crimes against art?" }
WordHunterWoW_QuestEN[70171] = { title = "Happy Little Accidents", description = "<Ranpiata's eyes look damp.>\n\nIs it me? Am I the reason he has lost his spark?\n\nHe says he loves me, but... you heard how not painting makes him feel.\n\nI want what is best for him. If he is better off... I will go. \n\nThere is one last piece he threw away. The last thing he tried to draw before giving up. \n\nI could not bear to see it go. I hid it away in our home. Please... bring it to him... as a memento.", objectives = "Find Hudson's last piece.", progress = "What a strange tuskarr. How does one get so stuck in their own head? \n\nIs this just what being an artist is like? Will that happen to me too? Oh dear.", completion = "This all seems a bit much for me. I just wanted to learn to paint from a master!\n\nBut... it has made me think about what my art means to me a bit more. \n\nI think... maybe I'm done with painting. \n\nI'm just going to leave my paints here... maybe try something new..." }
WordHunterWoW_QuestEN[70172] = { title = "Mountain Mysteries", description = "", objectives = "" }
WordHunterWoW_QuestEN[70174] = { title = "The Shikaar", description = "Sansok Khan is the most skilled hunter in our clan. Though she cannot hear, she proved her capabilities time and time again as both a hunter and a leader.\n\nShe is a mentor to us all, a trusted leader, and a fierce defender of the Maruuk.\n\nIt is an honor for you to speak with her.", objectives = "Meet Sansok Khan.", progress = "<Sansok Khan regards you steadily.>", completion = "<Sansok Khan gives you a slight nod.>" }
WordHunterWoW_QuestEN[70175] = { title = "Broken Banding", description = "<This might be something Emila Bellocq is looking for.>", objectives = "Deliver the item to Emilia Bellocq.\n\nProvided item:", completion = "Soft metals just don't withstand the elements.\n\n<Emila shakes her head as she takes the band from you.>\n\n I will be sure this band is put away somewhere safe." }
WordHunterWoW_QuestEN[70176] = { title = "Web Victims", description = "", objectives = "" }
WordHunterWoW_QuestEN[70178] = { title = "Expedition Supply Kit", description = "Explorer, your discoveries have been invaluable.\n\nThere is even more out there to uncover and we have the tools to help you do it.\n\nCome back to the Dragonscale Basecamp and gear up using the Expedition Supply Kit.", objectives = "Examine the new tools available in the Expedition Supply Kit at the Dragonscale Basecamp." }
WordHunterWoW_QuestEN[70179] = { title = "A Two for One Deal", description = "Greetings, adventurer! Say, you look like a capable person. Could you give me a hand?\n\nAzkra and I are charged with watching over this tower, which is in what I like to call \"an exciting state of pre-renovation.\" My problem is as we started repairs, the local earth elementals attacked us! \n\nSo I thought \"Zefren, why not take care of the earth elementals and get some building materials at the same time?\" Which is where you come in! Could you help?", objectives = "Obtain Building Materials from the local Earth Elementals.", progress = "I have to say, I'm quite looking forward to being able to work on this tower once again, I might even put in a little plaque commemorating your help! You are still planning to help, right?", completion = "Oh bother, these are quite a bit more crumbly than I was expecting. They look quite a lot more solid when they are launched at your head! \n\nWell. I'm sure I can use these for building regardless, thank you for your help! \n\nMaybe there are some mud elementals around here somewhere I can use to glue it together...." }
WordHunterWoW_QuestEN[70180] = { title = "Jump-Start? Jump-Starting!", description = "Some folks in the city claim this here device was created by the legendary Titan Watcher Tyr. \n\nProblem is we can't get it to work! We tried all the usual tricks, dissemblin', gyroscopin', a little mild electrocution. None of it sides the electrocution worked. Actually... I just had a great idea.\n\nSee that gyrocopter over there? Hop in and let's see if we can give this titan thing a little more... juice.", objectives = "Help Greyzik power-up the mysterious device.", completion = "What power do you seek?" }
WordHunterWoW_QuestEN[70181] = { title = "First Challenge of Tyr: Finesse", description = "<As you approach, the inscription on the statue emits a faint glow.>\n\n\"Wield the Keeper's power and carry its light to a better future for us all.\"", objectives = "Complete the first Challenge of Tyr in the Azure Span.", completion = "Admirably done. You have earned your reward." }
WordHunterWoW_QuestEN[70182] = { title = "The Sweet Taste of Victory", description = "There is great potential in small things. The Bottled Essence may feel light as a feather, but it holds immense power. \n\nTake it to the Engine of Innovation.", objectives = "Return to the Engine of Innovation in Valdrakken.", completion = "Can you feel the potential emanating from the bottle?" }
WordHunterWoW_QuestEN[70183] = { title = "Specialized Secrets: Alchemy", description = "", objectives = "What wisdom do you seek?", progress = "What wisdom do you seek?", completion = "Patience, young one. There is still much to learn.\n\nBut you may celebrate today, for you understand more than you did before." }
WordHunterWoW_QuestEN[70184] = { title = "Specialized Secrets: Blacksmithing", description = "", objectives = "What wisdom do you seek?", progress = "What wisdom do you seek?", completion = "Patience, young one. There is still much to learn.\n\nBut you may celebrate today, for you understand more than you did before." }
WordHunterWoW_QuestEN[70185] = { title = "Mysterious Beast", description = "<You find a large pawprint sunk into the dirt. Looking around, none of the nearby creatures have paws, let alone of that size.\n\nPerhaps the centaur will be impressed if you hunt this great beast.>", objectives = "Find and slay the beast, then bring back proof to Scout Tomul.", progress = "Do you return from your hunt?", completion = "<Tomul looks the pelt over before offering a small nod.>\n\nYou defeated Konkhular, then. Not bad, two foot. He has evaded our hunters for many moons. His pelt always blended in well with his surroundings. Perhaps now our hunters can use his camouflage to their own advantage." }
WordHunterWoW_QuestEN[70186] = { title = "Specialized Secrets: Enchanting", description = "", objectives = "What wisdom do you seek?", progress = "What wisdom do you seek?", completion = "Patience, young one. There is still much to learn.\n\nBut you may celebrate today, for you understand more than you did before." }
