WordHunterWoW_QuestEN[70414] = { title = "Shaky Grounds", description = "In the name of Khaz'goroth, what goes on here? \n\nThis magma works with a mind of its own, consuming these elemental cavestones from below. Tis more than chance causin' this... I aim to figure it out!\n\nPlace these Shattering Totems next to each trapped elemental to free them!", objectives = "Place the Shattering Totems to free the trapped cavestones.", progress = "Have ye freed them all?", completion = "Good work, we will need elemental allies if we wish to solve the mystery of what is happening here!" }
