WordHunterWoW_QuestEN[70437] = { title = "To Tyrhold", description = "Centuries have passed since the flights last visited Tyrhold. \n\nNevertheless, we must travel there and investigate if the Mother Oathstone still functions.\n\nCome, speak with me at the Seat of the Aspects. We must learn about the dangers we may face at Tyr's former stronghold.", objectives = "Meet Alexstrasza at the Seat of the Aspects.", progress = "It is good to see you, <name>.", completion = "This space seems clear enough." }
WordHunterWoW_QuestEN[70438] = { title = "Flying Fish", description = "The fish could be biting better, don't you think?\n\nYou know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it?\n\nMaybe you and your drake could give it a try?", objectives = "Collect fish to restock the fishing hole and mount your drake to drop them from above.", progress = "Have you dropped those fish yet?", completion = "Ha! The legends are true, how fantastic!" }
WordHunterWoW_QuestEN[70439] = { title = "Wild Arcana", description = "", objectives = "" }
WordHunterWoW_QuestEN[70440] = { title = "Dead Eyes", description = "", objectives = "" }
WordHunterWoW_QuestEN[70442] = { title = "Banquet Battle", description = "", objectives = "" }
WordHunterWoW_QuestEN[70444] = { title = "The Fields of Ferocity", description = "To the bravest Shikaar! \n\nGather your best and head on over to the Fields of Ferocity. You could be crowned the fiercest of them all!\n\nProve your might. Show us your best fight!\n\nTerms and conditions apply.", objectives = "Meet Gurgthock at the Fields of Ferocity.", completion = "Hey, you're no centaur.\n\nEhh. You'll do." }
WordHunterWoW_QuestEN[70446] = { title = "A Personal History", description = "In delving into the archives here, I've found threads that point towards the Obsidian Observatory as a place of personal importance to the Earth-Warder. I can only guess what knowledge it may contain about the history of our flight.\n\nGiven Emberthal's interest in the subject, I informed her of my discovery. I pray that wasn't a mistake.\n\nShe has gone ahead to scout. Please, keep an eye on her. She is a competent soldier, but this subject is... troubling. Who knows what truths you may uncover.", objectives = "Meet Emberthal at the Obsidian Observatory.", completion = "I am confident I will be able to handle anything we encounter. Still, given the matter at hand... it was wise of Edress to send you to accompany me." }
WordHunterWoW_QuestEN[70450] = { title = "Otter Devastation", description = "Hey there, friend. These here ottuks keep stealin' my catch!\n\nPersonally, I'd blow 'em up, but our Tuskarr friends don't seem too keen on that action. I made this here Ottuk Deterent Device MK-SH4RK, but... I aint a great swimmer.\n\nYou seem like you got the goods, why don't ya do us all a favor, activate the device, swimmy-swim around over there, and scare 'em off?", objectives = "Scare off the Pesky Ottuks.\n\nYou may unlock only one extra fishing net per day.", progress = "You get rid of them pesky ottuks yet?", completion = "'Ey! Great job, buddy. Now let's chum these waters good!" }
WordHunterWoW_QuestEN[70501] = { title = "License to Hunt", description = "Ah, finally ready to prove yourself as a hunter? Keep in mind this is not as simple as running around and hunting everything that moves. The Shikaar hunt with purpose. We hunt to feed and clothe the clan, to prove our strength against mighty foes, and to balance nature.\n\nWe do not hunt the land barren, we sow the seeds for future Grand Hunts as we go. Prove yourself capable of following these instructions and you may join us.\n\nHowever I do not have confidence in your friend there succeeding.", objectives = "Complete the Grand Hunt training tasks.", progress = "Have you completed your training?", completion = "Excellent! You are ready to join the Grand Hunts! \n\nPlease inform this Nesingwary Jr. that there is more to hunting than mindless killing and that he is unwelcome to join us." }
WordHunterWoW_QuestEN[70502] = { title = "Clearing the Skies", description = "", objectives = "" }
WordHunterWoW_QuestEN[70503] = { title = "The Vigilance of Tyr", description = "Bodies, broken gear, uncontrolled titan energy. What a disregard for safety, and... and protocol! It looks like they found the stone and it was unstable, bursting into pieces.\n\nFortunately, I'm particularly adept at repairing magical devices.\n\nBut before I can reform the stone we need to collect each and every piece.", objectives = "Recover the fragments of the stone.", progress = "I can't believe it. It's all here! Well done.", completion = "I'll head back to basecamp and have my people reconstruct this stone. Don't worry <name>, artifact restoration is our specialty." }
WordHunterWoW_QuestEN[70507] = { title = "The Insight of Tyr", description = "Did ya see Szar Skeleth on your way in? It's that ruined tower to the northeast.\n\nWe've got a bit of a good news, bad news situation there. The good news is the stone's already been found. Bad news is it was found by the Sundered Flame, specifically a magic-using dracthyr named Makko. And they're using it to control gorlocs.\n\nDid I mention the dracthyr's misuse of the stone drove them mad?\n\nWell, good luck!", objectives = "Recover the Insight of Tyr.", progress = "Turns out gorlocs don't make for good bodyguards, eh? I wonder how dangerous she could've been if she held on to her sanity.", completion = "You've got it! Don't worry about me. We should be safe to handle it unless we try to do something crazy. Like mind-controlling little fish monsters." }
WordHunterWoW_QuestEN[70509] = { title = "Third Challenge of Tyr: Persistence", description = "<It seems those who have reawakened with the Isles have not been kind to Keeper Tyr's creations. Perhaps finding the missing pieces of the statue would help.>", objectives = "Retrieve missing parts and repair the broken statue.", progress = "<As you approach, you can feel the warmth of Titan's energy flowing through the statue once more.>", completion = "Excellent work as always. I feel that Tyr's faith in the future was not unfounded." }
WordHunterWoW_QuestEN[70510] = { title = "Victorious", description = "Once again I ask you to bring this essence to the Engine of Innovation.", objectives = "Return to the Engine of Innovation in Valdrakken.", completion = "Have you noticed that each bottle is brighter when you bring it here? It shows that you are meant to walk this path." }
WordHunterWoW_QuestEN[70526] = { title = "Ohn'ahran Plains Rally", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[70529] = { title = "Bring Them Home", description = "", objectives = "" }
WordHunterWoW_QuestEN[70530] = { title = "Examination Week", description = "The students at Algeth'ar Academy ran out of solutions... again. Forgive me for asking, but could you gather more Dragon's Alchemical Solution so they can continue their studies?", objectives = "Craft 5 Dragon's Alchemical Solution using the Reclaim Concoctions recipe for Conflago in Valdrakken.", progress = "The students are getting impatient.", completion = "Excellent. We will not have to cancel the exams. After all, you can't take an exam without solutions!\n\nHere, study this. Even as a skilled alchemist, there is more for you to learn." }
WordHunterWoW_QuestEN[70531] = { title = "Mana Markets", description = "Demand for mana potions has increased dramatically this week, {name}. I will need your assistance filling customers' orders. Surely as a skilled alchemist you can spare a few, yes?", objectives = "Craft 10 Aerated Mana Potions for Conflago in Valdrakken.", progress = "Our customers are waiting.", completion = "Thank you <name>. My alchemy is brilliant but my customer service leaves something to be desired. I am glad you were here to help me fill these orders.\n\nHere, study this. Even as a skilled alchemist, there is more for you to learn." }
WordHunterWoW_QuestEN[70532] = { title = "Aiding the Raiding", description = "Oh {name}, I am glad to see you. Several champions have been injured in the latest assault against the Primalists. We are greatly in need of healing potions. As an adventurer yourself, I imagine you have several on hand already. We will need many.", objectives = "Craft 10 Refreshing Healing Potions for Conflago in Valdrakken.", progress = "Every moment you waste, the Primalists grow stronger.", completion = "Thank you, <name>. This will revitalize the health of our injured champions and keep the Primalists at bay for another week.\n\nHere, study this. Even as a skilled alchemist, there is more for you to learn." }
WordHunterWoW_QuestEN[70533] = { title = "Draught, Oiled Again", description = "Did you know that Writhefire Oil is an excellent reagent for finishing your draughts? I did. And now I am out of it. I cannot work without a plentiful stock of oils. Please {name}, help me restock my laboratory.", objectives = "Craft 6 Writhefire Oils for Conflago in Valdrakken.", progress = "A craft without Writhefire Oil is like a dish without salt.", completion = "Wonderful, thank you. Always use a finishing reagent like Writhefire Oil for excellent craftsmanship.\n\nHere, study this. Even as a skilled alchemist, there is more for you to learn." }
WordHunterWoW_QuestEN[70539] = { title = "And You Thought They Did Nothing", description = "Hey sparky, you know what everyone forgets they need when they're flying around on dragons? Goggles.\n\nYou know what we sold out of today? Goggles.\n\nYou know what I need from you right now? You guessed it!", objectives = "Craft 2 Milestone Magnifiers for Clinkyclick Shatterboom in Valdrakken.", progress = "<Clinkyclick is muttering to herself as she looks for something.>", completion = "Oh, great! These look perfect. Thanks!\n\nHere, take these schematics. I bet there's something in there you didn't know." }
WordHunterWoW_QuestEN[70540] = { title = "An Engineer's Best Friend", description = "Hey sparky, have you seen my...\n\nErr... maybe hand me the...\n\nThat's it--I think it's time we start keeping a few more tools around this shop, you know what I'm saying?", objectives = "Craft 2 Draconium Encased Samophlanges for Clinkyclick Shatterboom in Valdrakken.", progress = "<Clinkyclick is muttering to herself as she looks for something.>", completion = "Finally! It's like trying to craft with two hands tied behind my back without those things.\n\nHere, take these schematics. I bet there's something in there you didn't know." }
WordHunterWoW_QuestEN[70541] = { title = "Hunting Tactics: Companion", description = "Your renown with the Maruuk grows. You may now hunt alongside a tenacious bakar or swift ohuna companion.", objectives = "Choose to fight alongside a bakar or ohuna during the Grand Hunt.", completion = "Treat your hunting companion with loyalty and respect and they will protect your life with their own.\n\nReturn when your renown grows and I will train you further." }
WordHunterWoW_QuestEN[70542] = { title = "Azure Span Rally", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[70545] = { title = "Blingtron 8000...?", description = "Hey sparky, I've got a secret project going on. People are going to go wild! But I've run out of the basics.... You wanna be a pal and get me some bolts?", objectives = "Craft 10 Handfuls of Serevite Bolts for Clinkyclick Shatterboom in Valdrakken.", progress = "<Clinkyclick is muttering to herself as she looks for something.>", completion = "Oooohhh...! <Clinkyclick begins laughing to herself, seemingly thinking about how she'll use these.>\n\nHere, take these schematics. I bet there's something in there you didn't know." }
WordHunterWoW_QuestEN[70549] = { title = "Low Hanging Fruit", description = "", objectives = "" }
WordHunterWoW_QuestEN[70550] = { title = "Welcome to the Assembly", description = "We could use your aid.\n\nThe Sundered Flame have taken control over most of the Cobalt Assembly. \n\nPlease help us in this fight against them. Our numbers are small, but there are a few things we can do to aid you.", objectives = "Speak with Xavin within the Cobalt Assembly to see what abilities are available within the area.", progress = "We can use all the help we can get.", completion = "Once we have more control over the Cobalt Assembly, we'll be able to better support our allies in the fight against the Sundered Flame." }
WordHunterWoW_QuestEN[70557] = { title = "No Scopes", description = "Great gadgets, sparky, do I have a big one for you today!\n\nApparently, some firework fad caught on with the hunters. They try setting them off to scare the ducks into the air. Bet the ducks are way to smart for that, but it won't stop us from profiting! Think you're up to the task?", objectives = "Craft 15 Bronze Fireflight for Clinkyclick Shatterboom in Valdrakken.", progress = "<Clinkyclick is muttering to herself as she looks for something.>", completion = "Thanks, sparky! That should take care of this until they come up with some new hare-brained scheme.\n\nHere, take these schematics. I bet there's something in there you didn't know." }
WordHunterWoW_QuestEN[70558] = { title = "Disillusioned Illusions", description = "My scribe apprentice, you could not have chosen better timing.\n\nThere has been a terrible accident! All of the Illusion Parchment I ordered turned out to be real! Can you believe it! Do they think this is some game? Someone might get hurt!\n\nDo you think you could rectify this situation and create some real illusions?", objectives = "Craft 5 Illusion Parchment: Spell Shield for Talendara in Valdrakken.", progress = "Have you inscribed what I need?", completion = "Thank you a thousand times, my scribe apprentice.\n\nPlease take these glyphs as a token of my thanks. Perhaps you can study them to further your practices." }
WordHunterWoW_QuestEN[70559] = { title = "Quill You Help?", description = "My scribe apprentice, I am delighted to see you.\n\nEarlier today I had a few novices come in to try their hand at inscription. They all wrote with too much force and snapped their quill nibs right off!\n\nI hate to ask, but could you craft a few more quills to keep in stock?", objectives = "Craft 2 Scribe's Fastened Quill for Talendara in Valdrakken.", progress = "Have you fresh quills for my apprentices?", completion = "Thank you, my scribe apprentice. I do not know what I would do without you.\n\nPlease take these glyphs as a token of my thanks. Perhaps you can study them to further your practices." }
WordHunterWoW_QuestEN[70560] = { title = "The Most Powerful Tool: Good Documentation", description = "My scribe apprentice, do you feel ready for writing today? The Dragonscale Expedition has brought copious notes from their adventures, and they have asked that we compile their chicken-scratch penmanship into a suitable compendium for field-ready review. And oh, my hand is simply not up for the task today. Could I rely on you once more?", objectives = "Craft 2 Core Explorer's Compendiums for Talendara in Valdrakken.", progress = "Have you inscribed the compendiums?", completion = "Thank you, my scribe apprentice, thank you.\n\nPlease take these glyphs as a token of my thanks. Perhaps you can study them to further your practices." }
WordHunterWoW_QuestEN[70561] = { title = "A Scribe's Tragedy", description = "My scribe apprentice! It is awful, just terrible! I cannot fathom how I am to go on in my life!\n\n<Talendara begins weeping.>\n\n...I have run out of ink! Could you please bottle some more?", objectives = "Craft 5 Blazing Ink for Talendara in Valdrakken.", progress = "Have you bottled the ink?", completion = "Thank you, my scribe apprentice. If only a mage would duplicate you...\n\nPlease take these glyphs as a token of my thanks. Perhaps you can study them to further your practices." }
WordHunterWoW_QuestEN[70562] = { title = "The Plumbers, Mason", description = "Jewelcrafter, how would you feel about a chance to practice your prospecting techniques?\n\nThe architects and plumbers of the Dragonscale Expedition have requested that we acquire some stones for the construction of a new bath house. I think you will find this a suitable task to occupy you and practice your masonry.", objectives = "Craft 15 Crumbled Stones for Tuluradormi in Valdrakken.", progress = "Do you have the stones?", completion = "Nice work, <name>.\n\nHere, I made these cuts. You can study them to learn how to be a better jewelcrafter like me." }
WordHunterWoW_QuestEN[70563] = { title = "The Exhibition", description = "Oh jewelcrafter, how would you feel about a chance to practice your gemcutting?\n\nI was going to put on a display of various cuts, and I suppose I could exhibit your gems as well, so long as you hurry. Submit nothing less than the highest quality for this demonstration.", objectives = "Craft a variety of gems for Tuluradormi in Valdrakken.", progress = "Are your gems worthy of display?", completion = "Very well, I suppose these will do.\n\nHere, I made these cuts. You can study them to learn how to be a better jewelcrafter like me." }
WordHunterWoW_QuestEN[70564] = { title = "Spectacular", description = "Jewelcrafter, there is an exhibition coming up, and I am concerned that the clients will not be able to see the beauty of each cut without the proper lenses.\n\nYou do not need anything fancy. Just make a few loupes so our customers can see clearly.", objectives = "Craft 2 Sundered Onyx Loupes for Tuluradormi in Valdrakken.", progress = "Do you have the loupes?", completion = "Your work is appreciated... By someone, I would imagine. Probably.\n\nHere, I made these cuts. You can study them to learn how to be a better jewelcrafter like me." }
WordHunterWoW_QuestEN[70565] = { title = "Separation by Saturation", description = "Oh jewelcrafter, do you like my necklace?\n\nOf course you do. But I cannot show it off properly unless it stands out.\n\nI know! Why don't you make a few simple pendants and we shall flood the market. Once everyone is wearing your designs, my necklace will be a sparkling cut above the rest!", objectives = "Craft 2 Pendants of Impending Perils for Tuluradormi in Valdrakken.", progress = "Do you have the pendants?", completion = "All in the name of fashion, <name>.\n\nHere, I made these cuts. You can study them to learn how to be a better jewelcrafter like me." }
WordHunterWoW_QuestEN[70567] = { title = "When You Give Bakar a Bone", description = "I had some of the most beautiful bonewrought bows, but our bakar got to them before they could be put to use. Bakar love to chew bones, whether bow or not, and now they are ruined!\n\nCan you aid me in crafting replacements?", objectives = "Craft 2 Bonewrought Crossbows for Hideshaper Koruz in Valdrakken.", progress = "I will be far more wary of the bakar when next I carry these.", completion = "Thank you <name>.\n\nHere, take these designs. You can study them to improve your leatherworking." }
WordHunterWoW_QuestEN[70568] = { title = "Tipping the Scales", description = "Our scale bracers are finely crafted and highly in demand. I am finding it difficult to keep up with all of the orders! Would you lend your skill in replenishing my supply?", objectives = "Craft 2 Trailblazer's Scale Bracers for Hideshaper Koruz in Valdrakken.", progress = "Our goods are of the finest quality and craftsmanship. I am not surprised they sell so quickly.", completion = "Well done, <name>. \n\nHere, take these designs in return for your aid. You can study them to improve your leatherworking." }
WordHunterWoW_QuestEN[70569] = { title = "For Trisket, a Task Kit", description = "I have many valued customers, but Trisket is one of my favorites. Most recently he came to me because his herbalist's pouch has worn out. \n\nI offered to make him a selection of baskets to replace his old pouch. \n\nWould you help me with these tasks, {name}? Trisket would be appreciative.", objectives = "Craft 2 Herbalist's Floral Baskets for Hideshaper Koruz in Valdrakken.", progress = "I think Trisket will be far happier with these sturdy baskets.", completion = "Thank you for the aid, <name>.\n\nIn return, take these designs. You can study them to improve your leatherworking." }
WordHunterWoW_QuestEN[70571] = { title = "Drums Here!", description = "We are known far and wide for our drums--the centaur have been honing these skills for generations. Unfortunately this means that our drums are in short supply these days.\n\nYou have skills of your own, I see. Perhaps you could help me craft a few drums for our stores?", objectives = "Craft 2 Feral Hide Drums for Hideshaper Koruz in Valdrakken.", progress = "Your skills are quite impressive--where did you learn to craft?", completion = "Ohn'ahra bless you, <name>.\n\nHere, have these designs. You can study them to improve your leatherworking." }
WordHunterWoW_QuestEN[70572] = { title = "The Cold Does Bother Them, Actually", description = "If there is one thing I have learned in my years as a seamstress, {name}, it is that adventurers will always underestimate the cold.\n\nI have explorers in the Azure Span begging me for warmer robes.\n\nWould you take pity on them and craft a few?", objectives = "Craft 2 Surveyor's Cloth Robes for Fulafong in Valdrakken.", progress = "Do you have the robes?", completion = "Thank you, <name>.\n\nPlease, learn from these examples. Study them to improve your tailoring.\n\nAnd stay warm." }
WordHunterWoW_QuestEN[70582] = { title = "Weave Well Enough Alone", description = "If there is one thing I have learned in my years as a seamstress, {name}, it is the importance of practice.\n\nAlways be practicing your craft, even when you believe you have mastered everything. I want you to be able to weave with excellence without my supervision.\n\nWhy don't you practice this week? Make a few Wildercloth Bolts at the highest quality.", objectives = "Craft 3 Wildercloth Bolts for Fulafong in Valdrakken.", progress = "Do you have the bolts?", completion = "You have done well with these, <name>.\n\nPlease, learn from these examples. Study them to improve your tailoring.\n\nAnd stay sharp." }
WordHunterWoW_QuestEN[70586] = { title = "Sew Many Cooks", description = "If there is one thing I have learned in my years as a seamstress, {name}, it is that too many cooks spoil everything.\n\nIn this case, I was going to go out for a drink and an order came in last minute for an entire wardrobe of chef's uniforms.\n\nIf you could sew the hats, I will take care of everything else.", objectives = "Craft 2 Wildercloth Chef's Hats for Fulafong in Valdrakken.", progress = "Do you have the chef's hats?", completion = "Thank you, <name>. You are hungry as ever for a good challenge.\n\nPlease, learn from these examples. Study them to improve your tailoring.\n\nAnd stay hungry." }
WordHunterWoW_QuestEN[70587] = { title = "A Knapsack Problem", description = "If there is one thing I have learned in my years as a seamstress, {name}, it is that you can never have enough space for your reagents. In fact, we could use a few more bags around here to hold everything. Would you mind stitching another?", objectives = "Craft 1 Simply Stitched Reagent Bag for Fulafong in Valdrakken.", progress = "Do you have the bag?", completion = "Thank you, <name>. This will do just fine.\n\nPlease, learn from these examples. Study them to improve your tailoring.\n\nAnd stay away from anyone offering you infinite storage space. You do not want to know what lies down that road." }
WordHunterWoW_QuestEN[70589] = { title = "Blacksmithing Services Requested", description = "Hi, hi, hi {name}! Crafting orders are coming in left and right!\n\nIf you're looking for work, the Artisan's Consortium always has orders to fill!\n\nYou can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!", objectives = "Fill Blacksmithing Crafting Orders for the Artisan's Consortium.", progress = "Busy, busy, busy!", completion = "Thanks for your business! Keep on crafting, crafting, crafting!" }
WordHunterWoW_QuestEN[70591] = { title = "Engineering Services Requested", description = "Hi, hi, hi {name}! Crafting orders are coming in left and right!\n\nIf you're looking for work, the Artisan's Consortium always has orders to fill!\n\nYou can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!", objectives = "Fill Engineering Crafting Orders for the Artisan's Consortium.", progress = "Busy, busy, busy!", completion = "Thanks for your business! Keep on crafting, crafting, crafting!" }
WordHunterWoW_QuestEN[70592] = { title = "Inscription Services Requested", description = "Hi, hi, hi {name}! Crafting orders are coming in left and right!\n\nIf you're looking for work, the Artisan's Consortium always has orders to fill!\n\nYou can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!", objectives = "Fill Inscription Crafting Orders for the Artisan's Consortium.", progress = "Busy, busy, busy!", completion = "Thanks for your business! Keep on crafting, crafting, crafting!" }
WordHunterWoW_QuestEN[70593] = { title = "Jewelcrafting Services Requested", description = "Hi, hi, hi {name}! Crafting orders are coming in left and right!\n\nIf you're looking for work, the Artisan's Consortium always has orders to fill!\n\nYou can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!", objectives = "Fill Jewelcrafting Crafting Orders for the Artisan's Consortium.", progress = "Busy, busy, busy!", completion = "Thanks for your business! Keep on crafting, crafting, crafting!" }
WordHunterWoW_QuestEN[70594] = { title = "Leatherworking Services Requested", description = "Hi, hi, hi {name}! Crafting orders are coming in left and right!\n\nIf you're looking for work, the Artisan's Consortium always has orders to fill!\n\nYou can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!", objectives = "Fill Leatherworking Crafting Orders for the Artisan's Consortium.", progress = "Busy, busy, busy!", completion = "Thanks for your business! Keep on crafting, crafting, crafting!" }
WordHunterWoW_QuestEN[70595] = { title = "Tailoring Services Requested", description = "Hi, hi, hi {name}! Crafting orders are coming in left and right!\n\nIf you're looking for work, the Artisan's Consortium always has orders to fill!\n\nYou can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!", objectives = "Fill Tailoring Crafting Orders for the Artisan's Consortium.", progress = "Busy, busy, busy!", completion = "Thanks for your business! Keep on crafting, crafting, crafting!" }
WordHunterWoW_QuestEN[70602] = { title = "History Lesson: War of the Shifting Sands", description = "", objectives = "" }
WordHunterWoW_QuestEN[70612] = { title = "Feed Three-Falls", description = "", objectives = "" }
WordHunterWoW_QuestEN[70613] = { title = "Get Their Bark Before They Bite", description = "{name}, you are a skilled herbalist, are you not? I have alchemists nearly begging at my door... well, if I had a door... for more Writhebark. We have nearly sold out! \n\nWill you help me gather more? I fear if the alchemists cannot create the phials they need, they will begin experimenting with my belongings.", objectives = "Gather 8 Writhebark for Agrikus in Valdrakken.", progress = "Have you found enough Writhebark?", completion = "Thank you, <name>.\n\nPlease, take my field notes. Study them to improve your herbalism." }
WordHunterWoW_QuestEN[70614] = { title = "Bubble Craze", description = "<Agrikus shouts at you.> I have no more poppy tea!\n\n...Oh, you're not one of them. Praise the Titans. Someone made \"Bubble Poppy Tea\" the most fashionable drink on the market this week and I've sold out of the herb completely. Please, could you bring more poppies before they return in droves?", objectives = "Gather 8 Bubble Poppies for Agrikus in Valdrakken.", progress = "<Agrikus is trying to calm himself down.>", completion = "Thank you, <name>, thank you.\n\nPlease, take my field notes. Study them to improve your herbalism.\n\nI need to... make some tea..." }
WordHunterWoW_QuestEN[70615] = { title = "The Case of the Missing Herbs", description = "Aah, {name}! There you are!\n\nThey took it! They took my Saxifrage!\n\nI left for barely two hours, and when I returned, someone had taken my Saxifrage! All they left to show for their crimes was this heavy sack of gold coins. As if you could put a price on herbs!\n\n...Please {name}, I need more Saxifrage to replenish what that criminal took from me.", objectives = "Gather 8 Saxifrage for Agrikus in Valdrakken.", progress = "Have you found my herbs?", completion = "Thank you, <name>. What a week this has been...\n\nPlease, take my field notes. Study them to improve your herbalism." }
WordHunterWoW_QuestEN[70616] = { title = "How Many??", description = "<Agrikus is crying as you approach.>\n\nThey did it... I cannot believe they did it...\n\nSomeone has come here and asked for the delivery of ONE THOUSAND herbs!\n\nI cannot even fathom this! It is preposterous. Ridiculous! Ludicrous!!\n\n...Please help.", objectives = "Gather 20 Hochenblume for Agrikus in Valdrakken.", progress = "Five hundred sixty one... five hundred sixty two...\n\n<Agrikus begins sobbing again.>", completion = "Oh, good. This will help. Thank for your assistance.\n\nPlease, take my field notes. Study them to improve your herbalism.\n\nI have herbs to count." }
WordHunterWoW_QuestEN[70617] = { title = "All Mine, Mine, Mine", description = "There is nothing as useful as Draconium ore. So much can be done with it! It is the perfect ore, pure in every way.\n\nBring me Draconium. I must have it. You are a miner, yes? Then go mine!", objectives = "Gather 7 Draconium Ore for Sekita the Burrower in Valdrakken.", progress = "Well? Have you brought me my ore?", completion = "Yes, yes, yes! This is exactly what I needed.\n\nTake my field notes when you go--I've written down some useful information about the mining process here in the Isles." }
WordHunterWoW_QuestEN[70618] = { title = "The Call of the Forge", description = "The forge... she calls to me. And she asks for Serevite. You there! Bring me Serevite! Yes, lots of Serevite! <Sekita begins laughing zealously.>", objectives = "Gather 16 Serevite Ore for Sekita the Burrower in Valdrakken.", progress = "More for the forge, more, more!\n\n<Sekita begins laughing zealously.>", completion = "Yes, yes!\n\nThe forge is satisfied with this.\n\nTake my field notes when you go. There must be something in there that will teach you about mining." }
WordHunterWoW_QuestEN[70619] = { title = "A Study of Leather", description = "You there! Perhaps you can help me with my studies of this leather. Some of it is soft and pliable, yet other pieces have a more firm temper--the better for crafting armor, I suspect.\n\nBring me more leathers to investigate. I wish to continue my studies.", objectives = "Gather 40 Resilient Leather for Ralathor the Rugged in Valdrakken.", progress = "Were you able to find any leather to study?", completion = "Thank you <name>. This should help me hone my craft.\n\nHere, have my field notes. They will teach you about the beasts of this land and to better procure their hides." }
WordHunterWoW_QuestEN[70620] = { title = "Scaling Up", description = "Many people ask me how I became so good at skinning. To them I say: it is all in the scales. \n\nAre you curious to learn more? Bring me some scales, and I will show you what I mean.", objectives = "Gather 40 Adamant Scales for Ralathor the Rugged in Valdrakken.", progress = "Have you found any worthy scales?", completion = "Excellent--with all that practice, now you have become better at skinning! You see? All in the scales.\n\nHere, have my field notes. They will teach you about the beasts of this land and how to better procure their hides." }
WordHunterWoW_QuestEN[70621] = { title = "Third Challenge of Tyr: Persistence Embodied", description = "Your third challenge was meant to have you overcome unfavorable odds. It was to help show me your persistence in all matters.\n\nI believe fighting djaradin and fixing my statue with the expectation that I would issue you a challenge is more than sufficient to fulfill your victory condition. \n\n<You think you catch a small smile play across her lips.>", objectives = "Accept the Bottled Essence from Maiden of Inspiration.", completion = "Your third challenge was meant to have you overcome unfavorable odds. It was to help show me your persistence in all matters.\n\nI believe fighting djaradin and fixing my statue with the expectation that I would issue you a challenge is more than sufficient to fulfill your victory condition. \n\n<You think you catch a small smile play across her lips.>" }
WordHunterWoW_QuestEN[70622] = { title = "Resupply Three-Falls", description = "", objectives = "" }
WordHunterWoW_QuestEN[70623] = { title = "Clearing the Skies", description = "", objectives = "" }
WordHunterWoW_QuestEN[70625] = { title = "Spellforged Creations", description = "", objectives = "" }
WordHunterWoW_QuestEN[70627] = { title = "What of the Winterpelt Clan?", description = "We could join another clan... if we knew it to be safe.\n\nI worry the Primalists tempted other clans as they did ours. \n\nThis \"Dragonscale Expedition\" tells me they have a clawhold near the Winterpelt clan.\n\nThey may be tainted. Or they may heed our warning. With either truth, they need us.\n\nThere is a \"furbolg expert,\" Sonova Snowden, in Theron's Watch. Please go to him and learn what he knows.", objectives = "Meet Sonova Snowden at Theron's Watch.", completion = "Regretfully, friend... I've got bad news for ya about the Winterpelt furbolg." }
WordHunterWoW_QuestEN[70629] = { title = "Assaulting the Shore", description = "", objectives = "" }
WordHunterWoW_QuestEN[70631] = { title = "Clearing the Skies", description = "", objectives = "" }
