WordHunterWoW_QuestEN[70697] = { title = "An Expert Opinion", description = "Lubbins' wounds may have healed, but I am afraid his confidence may still be injured. I believe it is time to call on others for help.\n\nFar to the southwest in a remote section of the Azure Span there is a pet trainer named Patchu. She is one of the world's foremost experts on these matters.\n\nPlease visit her, I am sure she can help Lubbins!", objectives = "Talk to Patchu in The Azure Span.", completion = "Jyhanna sent you to the right Tuskarr, <name>. We'll get Lubbins back to his old self in no time!" }
WordHunterWoW_QuestEN[70698] = { title = "Researcher Sneakwing", description = "", objectives = "" }
WordHunterWoW_QuestEN[70699] = { title = "Cataloging Thaldraszus", description = "", objectives = "" }
WordHunterWoW_QuestEN[70701] = { title = "Bakar Dream of Lost Argali", description = "Some of the clan's argali have wandered away from our flock again.\n\nThe ridge around us is too dangerous for our shepherds to search for them. It would be a great boon if you could take one of our bakar and bring back the argali. Our shepherds can point you in the right direction.", objectives = "Herd the lost argali back to Clan Aylaag.", completion = "We must be vigilant about our livestock. We are limited in resources to begin with. To lose an argali is a setback we would much like to avoid." }
WordHunterWoW_QuestEN[70702] = { title = "Continued Waygate Exploration", description = "<The little messenger's loud, screeching call captures your attention. They hand you a note before running off.\n\nThe note is a request from Thaelin Darkanvil, seeking your assistance.>", objectives = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores.\n\nProvided item:", completion = "I see ye found me letter. Glad tae see ye again!" }
WordHunterWoW_QuestEN[70703] = { title = "The Legacy of Tyrhold", description = "Keeper Tyr did love his mysteries. Clearly, there is deeper meaning to the gift he gave us. As he most likely forged this scale at his former citadel, perhaps it will be the key to helping unlock its secrets.\n\nGo with Koranos to Tyrhold, {name}. As a trusted advisor and watcher of this land, I am sure he will have insight into this matter.", objectives = "Investigate the Silver Scale with Koranos at Tyrhold.", progress = "Have you discovered something?", completion = "That magic... You have awakened something within Tyrhold." }
WordHunterWoW_QuestEN[70706] = { title = "Waygate: Shady Sanctuary", description = "Our expedition reports a dormant stone out in the lush hillsides to the southwest. It's quite a journey, but worth sendin' someone with yer knowledge tae investigate.", objectives = "Locate the Dormant Waygate at the Shady Sanctuary in the Ohn'ahran Plains." }
WordHunterWoW_QuestEN[70707] = { title = "The Next Waygate", description = "I've been keepin' this here vessel from yer nightborne friend safe.\n\nWhat do ye say 'bout us puttin' it tae good use and pursuin' another of those old stones?", objectives = "Choose the next waygate location to pursue." }
WordHunterWoW_QuestEN[70708] = { title = "Hollow", description = "Feels like it's been years. Also feels like it's been minutes. \n\nI could use someone to talk to, if you have time. \n\nYou wanna grab us a round of drinks? Get whatever you want. I'm paying.", objectives = "Have a drink with Kolgar.", progress = "I know I owe you more than a drink, but I hope this will do for now.", completion = "It's time to go, I guess." }
WordHunterWoW_QuestEN[70710] = { title = "River Rapids Route", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[70711] = { title = "River Rapids Route - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
