WordHunterWoW_QuestEN[70720] = { title = "Can't Have These", description = "", objectives = "" }
WordHunterWoW_QuestEN[70721] = { title = "After My Ohn Heart", description = "There is a small pond by the Mirror of the Sky where Narman and I first met during my initiate training.\n\nInitiates travel up there to be closer to Ohn'ahra so they may feel the wind. I first saw him in the reflection of the water when a sudden breeze opened my eyes. It is the most beautiful sight in all of the plains.\n\nIt will be the perfect place for our proposal.", objectives = "Help Windsage Dawa and Hunter Narman with their proposals.", completion = "Thank you, <name>.\n\nDawa and I will always remember what you have done for us." }
WordHunterWoW_QuestEN[70722] = { title = "What Lubbins Needs", description = "I think that I know what we gotta do, {name}. \n\nBut first, let's talk about it!\n\nI even have a gift to give you after we're done! Fun, right?", objectives = "Speak with Patchu in Iskaara.", progress = "Let's talk!", completion = "Make sure to summon Lubbins, then use this battle-stone on him. It'll permanently make him stronger." }
WordHunterWoW_QuestEN[70723] = { title = "Shattering the Earth Primalists", description = "Rethelshi in Valdrakken will be grateful to get this to aid his research on the Primalists.", objectives = "Bring the primal core to Rethelshi.\n\nProvided item:", completion = "This will help further our research on the Primalists. Thank you." }
WordHunterWoW_QuestEN[70730] = { title = "Shikaar Giver", description = "Oh, {name}.\n\nDo you feel comfort under the sun? Do you feel safe under its bright caress? Does each new day represent hope for the future and a chance to live your life as you've always dreamt it?\n\nThen you know love as I do.\n\nNarman of Clan Shikaar is my sun. He is my warmth. He is my light. He is my hope.\n\nA man like him deserves a proposal worthy of stature.\n\nWe must seek guidance from an Ohn.", objectives = "Help Windsage Dawa prepare for the perfect proposal.", progress = "Narman deserves a gesture as great as he is.", completion = "Arbhog's horns? They'll do just fine.\n\nArbhog was once the mightiest musken on the plains. These are a fitting gift for the mightiest hunter. I am sure Narman will appreciate them.\n\nPerhaps one day he will teach me to hunt. An Ohn'ir huntsman. Ha! Imagine that." }
WordHunterWoW_QuestEN[70732] = { title = "A Practice Bout", description = "All right! Now that you used that stone on Lubbins, let's have a practice bout to test out his skills! \n\nThere's a big ole Hornswog named Gwosh that lives on the shore to the north of here. Gwosh loves to fight! Well, play really. He's super good with other pets, too! \n\nIt'll be a perfect playtime... I mean fight... for Lubbins.", objectives = "Defeat Gwosh in a pet battle.", progress = "Gwosh is real gentle, but still fierce. I think he and Lubbins will have a fun bout! \n\nJust head up north of here and you'll find him.", completion = "Wow! That went great! Good job Lubbins!\n\nDon't worry about Gwosh, he's a big ol' softie. He'll be just fine." }
WordHunterWoW_QuestEN[70738] = { title = "The You-ga Class", description = "Everything was going so well, but now? Elementals are causing some, um, mild challenges.\n\nOur guests were enjoying the facilities when suddenly, all these elementals appeared! Those nasty fiends have disrupted everything. Probably even the new you-ga instructor. \n\nOh yes, you-ga is a new type of stretching that helps you meditate at the same time. I am sure both teacher and students are so relaxed they do not even notice the elementals.\n\nStill, better to be safe than sorry. Please, look for them.", objectives = "Find the instructor and 6 you-ga students.", completion = "Hopefully this experience won't tarnish their reviews!" }
WordHunterWoW_QuestEN[70739] = { title = "Bloodlines, Sweets, and Teerai", description = "I have hunted with khans, outrun our fastest bakar, and wrestled a full grown bruffalon bull bare-handed. As a hunter, I've nothing left to prove.\n\nHowever, as a partner, I still have much to learn. \n\nWindsage Dawa of Clan Ohn'ir is my heart and my joy. I wish only to prove worthy of his love, but I know nothing of traditions and rituals. I require the wisdom of the elders in Maruukai.", objectives = "Help Hunter Narman earn a traditional blessing for his marriage proposal.", progress = "What if I am not good enough for Dawa's love?", completion = "I would sooner ask all the stars of the night sky to admire me back than claim to be wholly worthy of Dawa's love.\n\nNonetheless, I will find the courage to proceed. When the time comes, will you assist me with a grand proposal?" }
WordHunterWoW_QuestEN[70740] = { title = "Steam Cleaning", description = "Xijan seems to think the elemental invasion on our beautiful spa is only a minor problem, but this surge of flame and steam needs to be brought under control immediately.\n\nWe had booked musical acts to play in the lower area, but the elementals destroyed their gear. As we have never had such levels of elemental destruction in this area before, I suspect Primalist influences.\n\nIf you want to help, clear the elementals on the east side of the lower spa. That is where the first events are scheduled.", objectives = "Kill 12 elementals in the lower spa.", completion = "A good start, but there are still far too many for my liking..." }
WordHunterWoW_QuestEN[70741] = { title = "Some Favorite Things", description = "<It looks like the you-ga class was interrupted, and the students' belongings are scattered everywhere. \n\nCollecting these items will certainly aid the Serene Dreams Spa.>", objectives = "Collect 6 missing belongings.", completion = "It is very kind of you to gather these items. We will return them to their owners right away!" }
WordHunterWoW_QuestEN[70742] = { title = "Runs in the Family", description = "From the air, I scouted one of the artifacts Edress uncovered by the entrance of the ruins. Doubtless there are more inside.\n\nThey are warded somehow, though I will need to get closer before I can examine them. The magic here is very old.\n\nThe grounds appear deserted, but I wouldn't trust that to last long once we start meddling. Keep an eye out. We will uncover all we can.", objectives = "Search the Obsidian Observatory for clues about the dracthyr's past.", completion = "This has given me... much to ponder. I would prefer some time alone, if it's all the same." }
WordHunterWoW_QuestEN[70743] = { title = "Precious Baby", description = "You there, {race}! Are you semi-competent?\n\nDo you have your priorities in check?\n\nGood!\n\nMy precious Baby is missing. Save her immediately. Be quick about it, she can't fend for herself in these horrible conditions.", objectives = "Find Elzara's Baby.", completion = "<Elzara ignores you and looks at Baby.>\n\nAre you safe, my precious cuddlemuffin?\n\nDid the Primalists bleed on you? How dare they!\n\n<Elzara notices you.>\n\nI shall definitely be rating this spa at one star. I expect a blood-free experience." }
WordHunterWoW_QuestEN[70744] = { title = "Look at the Bones!", description = "<Surely the spa manager would appreciate if there wasn't blood everywhere...>", objectives = "Clean up 10 bits of mess.", completion = "I do not want to know, do I?" }
WordHunterWoW_QuestEN[70745] = { title = "Enforced Relaxation", description = "Those Primalists that you saw certainly do not seem like the leadership type to me. Who would be afraid of a little dog? Hah!\n\nSo, if they mentioned Vadne, that sounds like their leader. She must be the one bringing in these elementals. We need to get rid of the summoner. They must be close by to be causing such trouble. Check the cave directly under us. I know it is where some of the less diligent employees like to take an extended break.", objectives = "Kill the elemental summoner.", completion = "I am glad this will finally start to get better! We all deserve a little bit of downtime.\n\nI hope you find a short respite here as well: you have earned it, <name>." }
WordHunterWoW_QuestEN[70746] = { title = "Shades of Blue", description = "You there, {name}!\nIt's good to see a friendly face in these parts. Telash and I were just discussing reports we've heard of... newcomers, in the area.\n\n<Emberthal lowers her voice.>\n\nBlue dragons. \n\nGiven our... history, with the blues, Telash and I thought it necessary to assess the situation ourselves. \n\nPlease, join us.", objectives = "Accompany Emberthal and Telash to Camp Antonidas.", progress = "Keep your head clear and your wings ready, my friend.", completion = "No sign of blue dragons yet, but plenty of their underlings." }
WordHunterWoW_QuestEN[70747] = { title = "The Azure Wizard", description = "I do not have time to quibble with sorcerers. \n\nGo and treat with this \"Archmage\", {name}. Learn what you may, and be on your guard always. They might be allies still or enemies yet...\n\nOur reports indicate there's a large archival complex to the south of here. \n\nThat is where I'm going.", objectives = "Talk to Archmage Khadgar in Camp Antonidas.", progress = "You appear uneasy, friend.", completion = "On behalf of the Kirin Tor, I'm deeply concerned to hear what Malygos did to your people. \n\nThis demands an immediate investigation.\n\n... Where are your companions?" }
WordHunterWoW_QuestEN[70748] = { title = "For Blue Eyes Only", description = "It is no wonder your companions have yet to find anything. \n\nThese books were meant for blue eyes only. \n\nHowever, my presence should suffice in allowing for some of the more pertinent tomes to divulge their secrets.", objectives = "Search the Azure Archive for Malygos's notes.", progress = "Have you found that which you seek?", completion = "You have the answers you seek, yet you do not look content...\n\nI am sorry." }
WordHunterWoW_QuestEN[70750] = { title = "Aiding the Accord", description = "You there! Yes, I'm speaking to you. Who else do you see around here?\n\n<Therazal glances quickly at quite a few passers by.>\n\nIgnore them. They are not part of this request. It is you I've heard of, and you I wish to speak with!\n\nThe Valdrakken Accord has asked me to seek out those who have shown they are making a name for themselves across the Isles, and those who seek to ensure our allies and their safety remain the highest priority.\n\nDo what you do best, friend. You shall be rewarded handsomely.", objectives = "Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", progress = "The tales of your exploits ring true, but what is it you bring me? Information, news? Get on with it.", completion = "Yes, indeed I am impressed, friend. As a representative of the Accord I can assure you your work has not gone unnoticed!\n\nPlease, accept this on behalf of our allies." }
WordHunterWoW_QuestEN[70751] = { title = "Terillod the Devout", description = "", objectives = "" }
WordHunterWoW_QuestEN[70752] = { title = "Vaporizing the Water Primalists", description = "Rethelshi in Valdrakken will be grateful to get this to aid his research on the Primalists.", objectives = "Bring the primal core to Rethelshi.\n\nProvided item:", completion = "This will help further our research on the Primalists. Thank you." }
WordHunterWoW_QuestEN[70753] = { title = "Dissipating the Air Primalists", description = "Rethelshi in Valdrakken will be grateful to get this to aid his research on the Primalists.", objectives = "Bring the primal core to Rethelshi.\n\nProvided item:", completion = "This will help further our research on the Primalists. Thank you." }
WordHunterWoW_QuestEN[70754] = { title = "Extinguishing the Fire Primalists", description = "Rethelshi in Valdrakken will be grateful to get this to aid his research on the Primalists.", objectives = "Bring the primal core to Rethelshi.\n\nProvided item:", completion = "This will help further our research on the Primalists. Thank you." }
WordHunterWoW_QuestEN[70763] = { title = "Worldcarver A'tir", description = "", objectives = "" }
WordHunterWoW_QuestEN[70766] = { title = "The Fractured Flame", description = "The gorloc clutches a journal, its cover marred by moisture and lack of care. The faded symbol of the Sundered Flame peeks proudly from behind the tears and discoloration.\n\nIf you find the missing pages, perhaps you can gain insight into Reclaimer Makko and the madness that has fractured her mind.", objectives = "Collect the pages of Makko's Journal from gorlocs in Szar Skeleth.", progress = "A journal? Written by who?", completion = "Thanks, but you can keep it. \n\n<Toddy rolls her eyes.>\n\nAnd I thought the Sundered Flame were crazy before..." }
WordHunterWoW_QuestEN[70779] = { title = "Tarjin's Tales", description = "<Tarjin continues facing the distant island while he speaks to you.>\n\nYou think yourself worthy of the incredible legends and histories of the djaradin?\n\nYou, who are hardly the size of one of our weapons? Pfft.\n\nI doubt you have the stomach to carry the legacy of my people.\n\nProve me wrong, if you can. Seek out dragons, the only worthy rival on these isles.\n\nBring me trophies of your victory over their strongest.", objectives = "Collect 5 Impressive Dragon Skulls from powerful dragons and proto-dragons in the Dragon Isles.", progress = "If you haven't the stomach to fight your precious dragonflights, you may seek out the proto-dragons. They still give quite a fight.", completion = "<Tarjin tosses the skulls over his shoulder into the lava pit behind him.>\n\nImpressive, for a weakling." }
WordHunterWoW_QuestEN[70780] = { title = "Ohn'ahran Banners", description = "", objectives = "" }
WordHunterWoW_QuestEN[70781] = { title = "Out of the Blue", description = "Did you see that?!\n\nThis winged creature just fell from the sky! I don't know what sort of being it is, but it certainly isn't native to the Isles.\n\nWait... I do remember a punchy little goblin asking for directions to the Bluefeather Cliffs just above us. You think she would know anything about it?", objectives = "Locate Harleen Chirpsnide in the Bluefeather Cliffs.", completion = "Some guard in Gelikyr told you I'd be here? Did they say I own 'em any money?" }
WordHunterWoW_QuestEN[70782] = { title = "Canopy Banners", description = "", objectives = "" }
WordHunterWoW_QuestEN[70783] = { title = "Skaara", description = "", objectives = "" }
WordHunterWoW_QuestEN[70784] = { title = "The Abandoned Outpost", description = "From what you mentioned, it appears the stone of Vigilance can be found at an abandoned station northeast of the Azure Archives. That must be Zelthrak Outpost.\n\nMeet up with me when you arrive, {name}, and we can find the stone together.", objectives = "Meet up with Naleidea near Zelthrak Outpost in the Azure Span.", completion = "I know this place is abandoned, but I didn't think it would be so... messy." }
WordHunterWoW_QuestEN[70785] = { title = "The City of the Dead", description = "An ancient city of the dead can only mean one thing. The Veiled Ossuary off the coast of northern Thaldraszus.\n\nIt's extensive, remote, and hard to approach. The perfect place to hide something. I'm not sure what we'll find there, {name}. But you can bet that it won't appreciate our presence.", objectives = "Meet up with Naleidea at the Veiled Ossuary in Thaldraszus.", completion = "Good, you're here! The sooner we begin the sooner we can leave." }
WordHunterWoW_QuestEN[70787] = { title = "Caught In a Dusk Storm", description = "", objectives = "" }
WordHunterWoW_QuestEN[70788] = { title = "Wrapped Gold Band", description = "<This might be something Emila Bellocq is looking for.>", objectives = "Deliver the item to Emilia Bellocq.\n\nProvided item:", completion = "Beautiful. I will put this away so it's safe." }
WordHunterWoW_QuestEN[70789] = { title = "Finely Carved Wing", description = "<This might be something Emila Bellocq is looking for.>", objectives = "Deliver the item to Emilia Bellocq.\n\nProvided item:", completion = "It's so delicately carved... We have really lost some fine techniques over the ages. I'll take this and make sure its safeguarded." }
WordHunterWoW_QuestEN[70790] = { title = "Stone Dragontooth", description = "<This might be something Emila Bellocq is looking for.>", objectives = "Deliver the item to Emilia Bellocq.\n\nProvided item:", completion = "It's very old, but you can still tell what it is... I will make sure this is filed away safely." }
WordHunterWoW_QuestEN[70791] = { title = "Coldwashed Dragonclaw", description = "<This might be something Emila Bellocq is looking for.>", objectives = "Deliver the item to Emilia Bellocq.\n\nProvided item:", completion = "What a colossal statue this must have been! And now we only have... this. But at least we have something! I'll make sure we get it logged." }
WordHunterWoW_QuestEN[70805] = { title = "Precious Stone Fragments", description = "<This might be something Emila Bellocq is looking for.>", objectives = "Deliver the item to Emilia Bellocq.\n\nProvided item:", completion = "I wonder what it would have looked like when it was new? Awe inspiring, I'll bet. For now, it's going into a box under lock and key!" }
WordHunterWoW_QuestEN[70806] = { title = "Chunk of Sculpture", description = "<This might be something Emila Bellocq is looking for.>", objectives = "Deliver the item to Emilia Bellocq.\n\nProvided item:", completion = "Hm.\n\n<Emila turns the piece over, looking at it from different angles.>\n\nPerhaps? No, I can't tell what it is. It's old though and undoubtedly important. In the collection it goes!" }
WordHunterWoW_QuestEN[70807] = { title = "Advanced Excavation Tools", description = "", objectives = "We appreciate your continued help with the expedition! As a reward for your efforts, I want to offer you one of my advanced tools. I have all of these tools available for trade, so come and see me again if you'd like another.\n\nThank you, adventurer!" }
WordHunterWoW_QuestEN[70808] = { title = "Initial Mysteries of the Dragon Isles Drakes", description = "", objectives = "Dragons have long fascinated me. Being here is a dream come true! I have already learned much about the renewed proto-drakes of the Waking Shores. Would you like to see one of the manuscripts I have put together? I have made many observations, and would be willing to trade for others as well!" }
WordHunterWoW_QuestEN[70809] = { title = "Deeper Mysteries of the Dragon Isles Drakes", description = "", objectives = "I have made great progress since we last spoke, adventurer! Please, choose another manuscript to help your renewed proto-drake learn another trait. Do not forget, you may always speak with me if you would like to trade for others!" }
WordHunterWoW_QuestEN[70810] = { title = "Broader Mysteries of the Dragon Isles Drakes", description = "", objectives = "I was able to expand my studies to the other drakes of the Dragon Isles. The red scales most common to the renewed proto-drakes are not limited to their variety. Each of the other main drakes can show red scales as well! Please, choose a manuscript for the drake you prefer. If you wish to trade for the others, come see me again!" }
WordHunterWoW_QuestEN[70811] = { title = "Expert Excavation Tools", description = "", objectives = "" }
WordHunterWoW_QuestEN[70812] = { title = "Expedition Cloaks", description = "", objectives = "A good cloak can be the most essential piece of gear on an expedition. Your help's earned you your choice of cloak. See me if you want to trade for a different one." }
WordHunterWoW_QuestEN[70813] = { title = "Digging Up Treasure", description = "", objectives = "Most of the treasure around here is in the ground--ancient artifacts, maybe even valuables. You're going to need a good shovel to get to it, though. Lucky you, I've got an official expedition shovel with your name on it. Look for disturbed dirt, and see what you can find." }
WordHunterWoW_QuestEN[70814] = { title = "Unlocking Magical Treasures", description = "", objectives = "This place has many treasures you have yet to see, as they are bound in magic. I can teach you to see them. Many lie hidden deep within caves, or are magically locked away in the various ruins of the land. Good luck in your search!" }
WordHunterWoW_QuestEN[70815] = { title = "Demolitions Access", description = "", objectives = "Some excavations require a delicate touch, and others need something a little more explosive. I think we can trust you to know when to use which. You can have this first explosive for no trade. Use it wisely, and don't prove me wrong." }
WordHunterWoW_QuestEN[70816] = { title = "Treasure Tracking Techniques", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[70817] = { title = "New Dragonscale Equipment", description = "", objectives = "The Dragonscale Expedition has access to some of the best artisans in Azeroth. They've created excellent equipment to help with exploration. Why, we just received a shipment of fine gloves. Take a look at my wares to see if they're something you want to trade for." }
WordHunterWoW_QuestEN[70818] = { title = "New Dragonscale Equipment", description = "", objectives = "A shipment of well-crafted leg armor just arrived. If you see something you like, let me know, and we can trade for it." }
WordHunterWoW_QuestEN[70819] = { title = "Renowned Explorer's Armor", description = "", objectives = "You've done some great things, adventurer--and it hasn't gone unnoticed. The expedition leadership has authorized me to issue you a set of our best armor. Thank you for all your help." }
WordHunterWoW_QuestEN[70820] = { title = "The Basecamp 'Pets'", description = "", objectives = "Ach! I thought a lifetime of gryphon wrangling would have prepared me for taming the unruly beasts of the Dragon Isles. But these Marmoni and Skitterbugs are pushing me to my limits! I will gladly offload one to you. If you seek another, I'll offer ye a fair trade!" }
WordHunterWoW_QuestEN[70821] = { title = "Skitterfly Riding", description = "", objectives = "Who woulda known that caring for juvenile skitterbugs would have consequences? Their parents, Skitterflies, came looking for them. Rather than wanting a fight, they nested--just like a gryphon would! I started training them and wouldn't you know it, it's close to riding a gryphon... once you get used to the buzzing wings. With all the help you're providing around here, I'd like you to have your first Skitterfly mount on me. I will gladly train you another, in exchange for some very specific items." }
WordHunterWoW_QuestEN[70822] = { title = "Lost Expedition Scouts", description = "", objectives = "We've sent out plenty of scouts since we landed, and a fair number of them haven't returned. Could you keep an eye out for them while you're exploring? They can often be spotted with our standard issue Expedition Scout Pack. Oh, and if you find any artifacts, deliver them Cataloger Jakes. She'll appreciate it." }
WordHunterWoW_QuestEN[70828] = { title = "Wayfinder's Compass", description = "", objectives = "These lands are vast--the terrain rises so much that it's easy for even the most knowledgeable tracker to get lost. If you want to help us out, you'll need a way to navigate. Take this compass, it should do the trick." }
WordHunterWoW_QuestEN[70829] = { title = "Cataloging Expeditions", description = "", objectives = "" }
WordHunterWoW_QuestEN[70830] = { title = "Packing for a Climb", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[70831] = { title = "Researching in Comfort", description = "", objectives = "Many hours of expedition work is spent--how do I say this? On your behind. I do not see why we can't make that time a bit more comfortable. Therefore, I have asked our new allies in the Reliquary to fashion us a set of pillows that will do nicely. I will let you have your pick, but you will have to trade if you want more!" }
WordHunterWoW_QuestEN[70832] = { title = "One of Us Now", description = "", objectives = "You're just the type of adventurer we want in our expedition, and we're so glad to have you! To show our appreciation, I'd like to reward you with our tabard. It'll show the world everything you've accomplished! We can't forget our roots, though--if you'd like a banner for the Reliquary or the Explorer's League, I have those available as well. Thank you for everything you've done!" }
WordHunterWoW_QuestEN[70833] = { title = "Rumors of the Jeweled Whelplings", description = "", objectives = "Have you heard the tale of this ancient jewelcrafter from the Dragon Isles? Legend has it they had a technique to craft jeweled whelpling statues that would come to life. I took it for just a story as well, but then this map was found in the pack of one of our fallen scouts with a clue to a jeweled whelpling. Take the map, see if it leads to the secret of creating these fabled living statues." }
WordHunterWoW_QuestEN[70834] = { title = "Titled Story", description = "", objectives = "I've been cataloging every deed and artifact that every member has contributed to the Dragonscale Expedition since we landed. Today I noticed the sheer height of your accomplishment. I could not be prouder to bestow upon you this prestigious title and this coveted Primal Infusion item that you can have crafted into a powerful item. Go forth and carry it as a true accomplishment for your heroic efforts." }
WordHunterWoW_QuestEN[70835] = { title = "Sturdy Expedition Shovel", description = "", objectives = "<Boss Magor waves you down.>\n\nHey there blacksmith, I've a new pattern you might be interested in!" }
WordHunterWoW_QuestEN[70836] = { title = "Siege on Dragonbane Keep", description = "Help the Obsidian Outcasts reclaim Dragonbane Keep.", objectives = "" }
WordHunterWoW_QuestEN[70837] = { title = "Follow the Clues", description = "<Investigator Erima reviews the map.>\n\nIt is clear what the X scrawled over the Seat of the Aspects represents.\n\nBut there is also a circle drawn around the Misty Vale. Perhaps this is the rebels' next target? Or a base of operations.\n\nOnly one way to find out. Meet me at the Vale.", objectives = "Meet Investigator Erima at the Misty Vale.", completion = "This is definitely a base of operations.\n\nThe Misty Vale is crawling with rebels... and Primalists!" }
WordHunterWoW_QuestEN[70838] = { title = "Rebels With a Cause", description = "The rebel staging ground... we have been looking for this very place. How fortunate for us that their saboteur's carelessness led us here.\n\nI cannot believe my brethren would stoop to working with the Primalists. We cannot let this stand. Take out the rebels and their Primalist friends before they can cause any further chaos.", objectives = "Kill 10 rebels and Primalists.", progress = "I trust these turncoats will pose no threat to you.", completion = "You handled yourself well.\n\nThese rebels are no slouches." }
WordHunterWoW_QuestEN[70839] = { title = "The Search for Titan Relics", description = "", objectives = "I have spent all of my time since the waking studying the titans. Their history is fascinating. What power they must have wielded to create the dragonflights! There is so much knowledge to be gained about them! \n\nIf you could bring me any titan relics you find around the Dragon Isles, I will put in a good word for you with the Valdrakken Accord." }
WordHunterWoW_QuestEN[70840] = { title = "A Titan Relic", description = "", objectives = "Have you found a Titan Relic?", progress = "Have you found a Titan Relic?", completion = "Amazing! This relic is perfectly preserved. I will begin studying it right away.\n\nYour efforts are most appreciated! I will remember my promise to speak well of you to the Valdrakken Accord. \n\nNow, where was I? Yes, this will fit in right over here..." }
WordHunterWoW_QuestEN[70841] = { title = "More Titan Relics", description = "", objectives = "What have you brought me today?", progress = "What have you brought me today?", completion = "How did you find so many of these? This is a veritable treasure trove of relics! One day you must tell me your secret. \n\nOnce again you have greatly increased our knowledge of the titans. The Valdrakken Accord will think well of you indeed!" }
WordHunterWoW_QuestEN[70842] = { title = "Detonation Locations", description = "I am sure that the rebels are documenting their plans for future attacks. We must find out what they are attempting to do before it happens.\n\nSearch their camp for any marked maps like the one we found in Valdrakken.", objectives = "Collect Misty Vale maps.", progress = "Were you able to recover the rebel plans?", completion = "I will send word to step up our security measures in these locations." }
WordHunterWoW_QuestEN[70843] = { title = "Ruin the Runestones", description = "<This runestone is strikingly similar to the one a rebel tried to plant in Valdrakken.\n\nThough this stone is unfinished, you spy caches of completed runestones off in the distance.\n\nIf you destroy these caches the rebels will not be able to put them to use.>", objectives = "Destroy caches of incendiary runestones.", progress = "Brave of you to tinker with those strange stones.", completion = "I could feel the tremor of those explosions all the way from here!\n\nValdrakken is now safer, thanks to your efforts." }
WordHunterWoW_QuestEN[70845] = { title = "In Tyr's Footsteps", description = "Keeper Tyr planned for all eventualities. He suspected there would be a need to empower the craftspeople of the realm some day, thus he created the Engine of Innovation. It possesses the ability to create a unique material that can help an item achieve expertise beyond that of mortal ability.\n\nTo ensure his engine would not be misused he created me to oversee any who sought its power. Only those worthy will be able to unlock the engine's full potential. \n\nAre you equal to the challenge?", objectives = "Find the First Challenge of Tyr in the Azure Span.", completion = "<It feels as if the statue reacts to your presence, its mechanism slowly awakening and coming to life.>" }
WordHunterWoW_QuestEN[70847] = { title = "Ancient Obsidian Charm", description = "<Talonstalker Kavia might want this.>", objectives = "Deliver the item to Talonstalker Kavia.\n\nProvided item:", completion = "It's still intact. Hopefully it brings the next owner more luck." }
WordHunterWoW_QuestEN[70848] = { title = "Forgotten Dragon Crest", description = "<Exadria might want this.>", objectives = "Deliver the item to Exadria.\n\nProvided item:", completion = "This crest belonged to the first dragons that lived in this Citadel. We shall display it in a place of honor." }
WordHunterWoW_QuestEN[70849] = { title = "This Calls for a Specialist", description = "Lubbins is doing lots better now, but I think he still needs some more help. \n\nA little bit ago I met a super smart Dragonscale Expedition explorer named Haniko who works with proto-drakes all the time. She's a pet trainer, too. I bet she could help Lubbins more! \n\nI think she was going to the Waking Shores. I bet if you go there you'll find her. \n\nI'm so happy I was able to help you! \n\n<she waves happily>\n\nGoodbye! Good luck, Lubbins.", objectives = "Talk to Haniko at the Wild Preserve in The Waking Shores.", completion = "Patchu was right to send you here. I've been working with proto-drakes my whole life. \n\nI don't know if there's anyone on Azeroth who knows more about them than I do." }
WordHunterWoW_QuestEN[70850] = { title = "Maldra's in Hot Water", description = "Excellent work. While you were off disrupting things I was scouting the camp. I did not expect to find my old friend Maldra Flametongue.\n\nI knew she was missing, but the rumors said she had joined the rebels. From what I could see, though, she is their captive!\n\nWe cannot leave her here. Rescue her from the dragonspawn holding her captive!", objectives = "Rescue Maldra from Orian Darkwater.", progress = "Maldra is a dear friend. We cannot leave her here with these rebels!", completion = "I am indebted to you for rescuing my friend." }
WordHunterWoW_QuestEN[70851] = { title = "Born to Be Wilder", description = "There's a lot of information you need to know. Let's have a talk and then we can decide what's best for Lubbins.", objectives = "Learn what Lubbins needs from Haniko.", progress = "There's a lot to cover. Let's talk.", completion = "Good! Now to get to work, <name>.\n\nBefore you go, take these polished pet charms. Pet trainers like to trade these for useful supplies, so keep an eye out." }
WordHunterWoW_QuestEN[70853] = { title = "A Friend for Lubbins", description = "Like we talked about, Lubbins needs two things: a buddy and a battle.\n\nI think we can get him both at the same time.\n\nThis area is a prime mating ground for Shyflys. If you look around a bit, you're sure to find a bunch.\n\nRemember, you need to weaken it before you can capture it with your trap.\n\nCome back when you have one. It might be a bit bruised after your battle, but I've got some battle-training stones that will fix 'em right up!", objectives = "Capture a Shyfly at the Wild Preserve in The Waking Shores.", progress = "The Shyflys shouldn't be too hard to find, especially now that you know where to look.", completion = "Nicely done. I believe these battle-stones are just what your new pet needs. \n\nYou know what? Take a few polished pet charms too. \n\nDid I mention you can trade them for good stuff? Because you can!" }
WordHunterWoW_QuestEN[70854] = { title = "So How Did It Go?", description = "You've done well, {name}. Lubbins is doing much better and is in excellent spirits. \n\nJyhanna will want to know, so go back and give her the good news!", objectives = "Return to Jyhanna at the Whelp Daycare in Valdrakken.", completion = "I am so glad you were able to help Lubbins. \n\nPerhaps you can help another animal I rescued. His name is Mister Toots. He is extremely sweet, and I think you two would get along.\n\nWhat do you say? Do you think you can handle another pet?" }
WordHunterWoW_QuestEN[70856] = { title = "Kill it with Fire", description = "These vile spiders lay their eggs in corpses.\n\nAnd sometimes the living.\n\nWe've seen several bodies of Sundered Flame who have fallen victim to them.\n\nWe can't let those eggs hatch if we want to survive here and defeat the Sundered Flame.\n\nTake this torch. It is imbued with the power of air and fire. Point it in the direction of what you want scorched, and it will do the rest.\n\nThe Tuskarr don't mess around with spiders. I came prepared.", objectives = "Destroy 10 Infected Corpses with the Flamethrower Torch.", completion = "Good work. This should give us some breathing room." }
WordHunterWoW_QuestEN[70858] = { title = "Back into the Action", description = "All right, the antidote is ready. I'll keep Alia steady. You pour what's in the vial into her mouth.\n\nI hope she will live... we'll need her magic to track down this artifact.", objectives = "Use the Ice Cold Antidote on Alia Sunsoar.", completion = "You have my thanks... I thought I would die before acquiring this artifact." }
WordHunterWoW_QuestEN[70859] = { title = "What the Guardian Beholds", description = "I appreciate your aid, {class}. I was the Kirin Tor mage who first discovered this artifact, Valthrux, and the Sundered Flame's plans.\n\nThe retrieval and study of this supposedly sentient and powerful artifact is of the utmost importance, and mark my word, I shall be the one to do it.\n\nThe Sundered Flame guess at its location, but I've used my magic to find a path for us.\n\nThere is a corrupted guardian nearby that holds a magic shard connected to Valthrux. I can use it to find the rest of the artifact.", objectives = "Recover the Whispered Shard from Edavix, the Corrupted Guardian.", progress = "Did you find the shard?", completion = "Give it to me! Quickly now!\n\nDid you hear the whispers too?" }
WordHunterWoW_QuestEN[70867] = { title = "Scalebane Keep", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[70871] = { title = "Iskaaran Fishing Net", description = "I see you're getting along with the villagers.\n\nYou seek to learn more about our ways of fishing you say? Well, first of all no one fishes with their bare hands. I can craft you a good, strong net worthy of an Iskaaran.", objectives = "Bring Tavio materials and let her craft an Iskaaran fishing net.", progress = "Have you found suitable materials? I need strongest vines of kelp, and some good stones with holes in them.", completion = "Here's your Iskaaran fishing net. Use it wisely, and never take from the cycle of life more than you need to sustain yourself." }
WordHunterWoW_QuestEN[70873] = { title = "Chasing Waterfalls", description = "The real threat lies in the Emberslate Cavern. This is where they carve those runestones and infuse them with primal fire.\n\nNo doubt you noticed the blazing wall of flame that blocks the entrance. I cannot dispel it, however I may be able to do something to help. I believe that with the proper application of Fallingwater, we can pass through it safely.\n\nHarvest water motes from the nearby elementals.", objectives = "Harvest 35 Fallingwater Motes.", progress = "We will need those motes to get you safely into the Emberslate Cavern.", completion = "<Maldra examines the Fallingwater Motes.>\n\nYes, these should do nicely." }
WordHunterWoW_QuestEN[70874] = { title = "To Breach a Fire Wall", description = "The rebels inside the cavern have been imbued with an elemental blessing, allowing them to safely pass through the wall of flame. I can grant you that same boon.\n\nDo not worry; I have seen the blessing granted many times. It shouldn't be any problem to recreate it effectively.", objectives = "Receive Maldra's elemental blessing.", progress = "How do you feel?", completion = "Worry not. That chilly, damp feeling is temporary." }
WordHunterWoW_QuestEN[70875] = { title = "Worst of the Worst", description = "The rebels in the Emberslate Cavern have an unflinching loyalty to the Primalists, and are therefore the greatest threat to Valdrakken.\n\nEliminate them, and any elementals they have unleashed.", objectives = "Kill 3 rebels and 4 elementals in Emberslate Cavern.", completion = "Well done, <name>.\n\nThose who follow the Primalists cannot be allowed to spread chaos and destruction." }
WordHunterWoW_QuestEN[70876] = { title = "Fracture the Foci", description = "If Maldra speaks the truth, the rebels are creating the runestones in the Emberslate Cavern.\n\nGiven the nature of these devices, we know there must be Primalist foci involved.\n\nDestroy the foci. You will know them when you see them.\n\nThe rebels cannot be allowed to create any more weapons of destruction.", objectives = "Destroy 4 Primalist Foci in Emberslate Cavern.", completion = "Without those foci, the rebels will no longer be able to imbue their runestones with explosive flame." }
WordHunterWoW_QuestEN[70877] = { title = "A Quack in Time", description = "<This duckling is despondent, quietly quacking to itself as its eyes dart around in fear.>\n\n<Maybe the ecologists would know how to help it?>", objectives = "Bring the Bubbled Duckling back to the Ecologists' Camp.", progress = "<Tharu coos at the bubbled duckling.>\n\nShh, don't cry, little one.\n\nUs big strong ecologists will keep you safe! And <name> too, of course.", completion = "Thanks for bringing Daisy to us. If there's two so far, there must be more, so keep an eye out next time you venture out there." }
WordHunterWoW_QuestEN[70878] = { title = "Ring of Fire", description = "In the deepest recesses of the Emberslate Cavern, the Primalists erected a fiery portal from which they unleash elementals.\n\nI can seal it, but my actions will draw the ire of whatever is on the other side. Including the revenant Magmaticus the Primalists have been aiding.\n\nI will need your protection if we are to stop them.", objectives = "Protect Maldra Flametongue while she seals the Primalist portal.", completion = "Nicely done, <name>!\n\nMaldra shared with me the details of your heroics." }
WordHunterWoW_QuestEN[70879] = { title = "Report on the Rebels", description = "I am impressed with what you have accomplished today. I hope you agree, {name}.\n\nWe have successfully shut down the nefarious activities of these Primalist-allied rebels. For now at least. We will need to keep a close watch on any dissent going forward.\n\nReturn to Captain Drine at your earliest convenience. She will want our full report.", objectives = "Meet Captain Drine at the top floor of the Seat of the Aspects.", completion = "Welcome back, <name>.\n\nMy eyes and ears have just told me the good news." }
WordHunterWoW_QuestEN[70880] = { title = "To Cook With Finery", description = "", objectives = "Hello there. Can I offer you a fork? Or maybe some tea?\n\nIt is a pleasure to see so many in Valdrakken. I am sure you will aid us admirably. If you find yourself in need of the knife to match your fork, let me know and we will trade!" }
WordHunterWoW_QuestEN[70881] = { title = "Fourth Challenge of Tyr: Resourcefulness", description = "The engine is close to reaching its full potential. All it requires now is a power core to process any essence put into it more efficiently.\n\nTyr left the knowledge of such devices with Watcher Irideus. Go into the Halls of Infusion and find him. I am sure he will help you with whatever you need.", objectives = "Obtain a Power Core from Watcher Irideus and defeat the Primal Tsunami in the Halls of Infusion.", progress = "You found Watcher Irideus?", completion = "Perhaps it was these enemies of order that Keeper Tyr wished to defend against. At least the loss of Watcher Irideus can still be a victory for us. By his power core we may power the engine and part of him shall always live on as creation of Tyr. \n\n<You can swear you see sadness cross over the maiden's face.>" }
WordHunterWoW_QuestEN[70882] = { title = "Renown Supplies", description = "", objectives = "Greetings, <class>. You've proved your worth to the Valdrakken Accord. Here are some supplies to help you aid our cause. Don't let us down!" }
WordHunterWoW_QuestEN[70883] = { title = "A Hand in Cultivation", description = "Greetings mortal, I have word from our Head Gardener Gryrmpech. The word is that the gardens are in a state of chaos, but I don't know if that is abnormal.\n\nThey assured me that they have it in hand--actually, 'in shovel' is the phrase they used. I am not sure what they are meaning; I am sure they will fill you in. Please, seek them out and they will outfit you appropriately for the situation.", objectives = "Seek out Gryrmpech in the Gardens of Unity.", completion = "A garden keeper needs their own weapons. Let me outfit you for battle. \n\nI have more tools of war if you need. I appreciate your help taming these wilds!" }
WordHunterWoW_QuestEN[70884] = { title = "Taking Back", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[70885] = { title = "Renown Supplies", description = "", objectives = "Greetings, <class>. You've proved your worth to the Valdrakken Accord. Here are some supplies to help you aid our cause. Don't let us down!" }
WordHunterWoW_QuestEN[70886] = { title = "Now THIS is Dragon Racing!", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[70887] = { title = "Feeling Freedom", description = "", objectives = "My smaller kin are now able to freely explore the Dragon Isles. It pleases me to see them flourishing and enjoying new experiences.\n\nAllow me to show you more ways that they can express themselves to you and others." }
WordHunterWoW_QuestEN[70888] = { title = "Rubbing Shoulders With The Best", description = "", objectives = "Working day and night to outfit our forces is no small feat. It's arduous work, but I enjoy it. And I hear you have been a boon to our efforts. \n\nAs a show of thanks, I want you to take one of my armor pieces. Just one. If you require another, I will want something in trade.\n\nMake your choice quickly. I have work to do!" }
WordHunterWoW_QuestEN[70889] = { title = "Crafting for Expertise", description = "", objectives = "You have returned, alchemist? I've been watching from afar, and I've seen you hard at work on your skills.\n\nTo reward your effort and mold you into an expert, I present you with these additional notes from our master alchemists. Study them carefully. Only with practice can you stand among the greatest of your craft." }
WordHunterWoW_QuestEN[70890] = { title = "I'm Going on an Adventure!", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[70891] = { title = "Fitting In", description = "", objectives = "If you are going to live or work in this city, you MUST blend in.\n\nI will make a custom garment for you in the latest style--I'll even give you your choice of color! Which flight do you feel most accentuates your eyes?\n\nIf you can't pick just one, then of course we can talk about multiple outfits. For a fair trade, of course!" }
WordHunterWoW_QuestEN[70892] = { title = "Crafting Your Start", description = "", objectives = "You wish to learn from our master alchemists? \n\nYou must improve your skills before requesting their guidance. But don't worry. I have some notes they're willing to give aspiring alchemists.\n\nThe notes will give you something to cut your fangs on! Practice crafting what's in them, and one day they'll entrust you with greater knowledge." }
WordHunterWoW_QuestEN[70893] = { title = "Community Feast", description = "Our community feast is happening RIGHT NOW! This is when everyone pitches in and makes the best soup we can.\n\nYou should join us!", objectives = "Perform 5 tasks in the Community Feast.", progress = "Как удачно, что ты застал пиршество. Мы проводим его всего-то по шесть-семь раз в день!", completion = "When everyone works together, the soup tastes GREAT!\n\nYou should try some when it's ready to eat!" }
WordHunterWoW_QuestEN[70895] = { title = "Soaring in Style", description = "", objectives = "Ah, mortal. Word of your adventures is spreading throughout the city. All eyes are upon you as you and your drake ally soar above the skies!\n\nLet us speak further about the amazing variety of expression among dragonkind." }
WordHunterWoW_QuestEN[70896] = { title = "Waist Not, Want Not", description = "", objectives = "My master Wrathion stationed me in this great forge. He's instructed me to lend a hand to adventurers such as yourself.\n\nI have some fine belts to offer in trade. Be sure to let the boss know I did my duty, eh?" }
WordHunterWoW_QuestEN[70897] = { title = "A Coming of Age", description = "", objectives = "You have returned. The work has not lessened. In fact, my skills are in greater demand than ever before.\n\nSo, are you going to stand there all day or will you select one of my immaculate helms? Yes, I know how good they are. \n\nDo you wish to trade for something else? If you're not ready to trade, I must return to my work." }
WordHunterWoW_QuestEN[70899] = { title = "Fifth Challenge of Tyr: Ingenuity", description = "As this was not how the Power Core was supposed to be obtained, it requires a re-attunement to the energies of the Engine. The resonance frequencies of the denizens of Tyrhold should bring the core to its full potential once more.\n\nThough I do not wish to sacrifice more of my brethren, I believe this is the only way this challenge may be completed.", objectives = "Attune Irideus' Power core with titanic energy from Tyrhold.", progress = "How goes your challenge?", completion = "You have completed the last challenge. Though it comes at a loss, I believe it is for the greater good. Keeper Tyr meant for you to succeed." }
WordHunterWoW_QuestEN[70900] = { title = "Innovating the Engine", description = "Tyr believed that the Engine of Innovation would be necessary for the battles to come. \n\nYou have proven yourself worthy and overcome all the challenges set before you. You may now unlock the Engine's full potential.", objectives = "Insert the newly attuned Power Core into the Engine of Innovation.", progress = "<The Engine hums quietly as you approach>", completion = "<With the new core installed, the Engine pulses with warm energy>" }
WordHunterWoW_QuestEN[70901] = { title = "A Collection of Creatures", description = "", objectives = "Greetings, mortal. I tend the grounds and the creatures that call them home--even stray proto-whelps.\n\nUnfortunately, there are more proto-whelps about than I can reasonably care for.\n\nHmm, you seem responsible. Would you like to take care of one? Later, if you would like a companion for your, uh, companion, please seek me out again." }
WordHunterWoW_QuestEN[70902] = { title = "Crafting for Expertise", description = "", objectives = "Looks like you've been working hard, <name>. Wait, aren't engineers supposed to work smarter, not harder? Perhaps you're not cut out for engineering after all!\n\nMerely a jest, <race>. Here. The master engineers left you further notes to help you increase your skill. They've promised me their documentation is more thorough this time, but you be the judge of that. Good luck!" }
WordHunterWoW_QuestEN[70903] = { title = "Wielding Titanic Might", description = "", objectives = "The study of Tyrhold and all titan artifacts in the Dragon Isles is critical to our efforts in fighting against the Primalists.\n\nThe weapons they left behind are especially important. I have recently discovered a great cache of them, and would like to award one to you in recognition of your efforts.\n\nAfter I catalog my findings, I would be willing to offer others in trade. But I ask that you bring me materials to further my research." }
WordHunterWoW_QuestEN[70904] = { title = "Variety is the Spice of Life", description = "", objectives = "Dragons are ancient beings, as diverse in our appearances as you mortal races.\n\nI could teach you much about our lineage, and about the varied looks I have encountered.\n\nPerhaps this drake you fly with would be interested in hearing my tales and exploring the possibilities before them." }
WordHunterWoW_QuestEN[70905] = { title = "Flying with Our Colors", description = "", objectives = "We dragonkin proudly wear the colors of our flights! As you can see from my attire... and my scales. \n\nBut now scaled and scaleless alike can show that they stand with our renewed flights. Don a tabard and wear it with pride!" }
WordHunterWoW_QuestEN[70907] = { title = "Maruuk Hunts", description = "", objectives = "" }
WordHunterWoW_QuestEN[70908] = { title = "Maruuk Hunts", description = "", objectives = "" }
WordHunterWoW_QuestEN[70909] = { title = "Crafting for Expertise", description = "", objectives = "I can tell by the smudges on your armor that you've been hard at work. And you've caught the attention of our masters as well! For your work, not for the cleanliness of your armor, to be clear...\n\nAs a reward, they have left more notes to help you learn. Study them and keep practicing, and perhaps one day you'll even surpass them. Good luck!" }
WordHunterWoW_QuestEN[70910] = { title = "Mysteries in Paper and Glass", description = "", objectives = "Welcome back to my shop! I have many new goods that may be of interest.\n\nYour efforts in the Dragon Isles are the talk of the market, so I will let you have one item for free.\n\nIf anything else catches your eye, I'm certain we can strike a bargain." }
WordHunterWoW_QuestEN[70911] = { title = "Armored and Ready", description = "", objectives = "Ah, the noble <class> returns from the path of adventure.\n\nA dragon's scales may be thick and tough, but it would be irresponsible to send our young into battle unprotected. Allow me to supply your drake with its first set of armor.\n\nSee me later if you would like to purchase another set. Other armors may be found throughout the Isles. Fair skies and strong winds!" }
WordHunterWoW_QuestEN[70912] = { title = "The Accord's High Standards", description = "", objectives = "Carrying the banner of a dragonflight shows your support for what it stands for.\n\nPlease choose a banner and display it with pride. If you wish to trade for another, seek me out." }
WordHunterWoW_QuestEN[70913] = { title = "To Bear Our Mantle", description = "", objectives = "Back from your adventures, eh? Looks like you've seen a scrape or two. Bet you could use some new pauldrons. \n\nIf you don't see anything you like, there is a special set of armor I can make to order. It requires very specific materials, but that's not a problem for someone with your skills." }
WordHunterWoW_QuestEN[70914] = { title = "The Breadth of Dragon Weaponry", description = "", objectives = "Ah, <class>. Welcome back to our forge. We have all heard tales of the amazing deeds you have done in service of Valdrakken.\n\nWe smiths serve the cause in our own way. To have a hero like you wielding one of my finest weapons would be an honor indeed!" }
WordHunterWoW_QuestEN[70915] = { title = "Crowning Achievement", description = "", objectives = "My, my, you're certainly making a name for yourself. At least, that's what the boss tells us.\n\nAs for me, I spend my days making helms. Finest in the all the Isles! Take a look. My prices are fair.\n\nWell... fair enough, at least." }
WordHunterWoW_QuestEN[70916] = { title = "Beknownst and Glorious", description = "", objectives = "Hail, friend <name>. Your service to Valdrakken has been exceptional.\n\nLet it be known to all that you are truly an Ally of Dragons! \n\nAnd to reinforce our esteem of you and your deeds I am also giving you a Primal Infusion. Take it and make a great crafted piece from it that will continue to crush our enemies." }
WordHunterWoW_QuestEN[70917] = { title = "A Shoulder to Quack On", description = "<This duckling is full of nervous energy. It seems eager to escape its current predicament.>\n\n<Maybe the ecologists would know how to help it?>", objectives = "Bring the Bubbled Duckling back to the Ecologists' Camp.", progress = "<Tharu coos at the bubbled duckling.>\n\nShh, don't cry, little one.\n\nUs big strong ecologists will keep you safe! And <name> too, of course.", completion = "Thanks for bringing Dipper to us-- these ducklings are starting to pile up! Keep an eye out for any more." }
WordHunterWoW_QuestEN[70918] = { title = "Quack for Your Life", description = "<This duckling is quacking frantically. If someone doesn't help it, the gorlocs will surely get annoyed!>\n\n<Maybe the ecologists would know how to help it?>", objectives = "Bring the Bubbled Duckling back to the Ecologists' Camp.", progress = "<Tharu coos at the bubbled duckling.>\n\nShh, don't cry, little one.\n\nUs big strong ecologists will keep you safe! And <name> too, of course.", completion = "Quackers is certainly a lively little guy, hmm? Thank you for bringing him to us-- there can't be too many more out there!" }
WordHunterWoW_QuestEN[70919] = { title = "Quacking Out for a Hero", description = "<This duckling has been bubbled so long that it's fallen fast asleep. It quacks softly as it snores.>\n\n<Maybe the ecologists would know how to help it?>", objectives = "Bring the Bubbled Duckling back to the Ecologists' Camp.", progress = "<Tharu coos at the bubbled duckling.>\n\nShh, don't cry, little one.\n\nUs big strong ecologists will keep you safe! And <name> too, of course.", completion = "Cheese and Quackers, hehe... I'd say that's about all the bubbled ducklings we can handle, <name>. Good work." }
